/* §rfSoft · ตารางกว้าง ๆ (ตารางการทำงาน ตารางวิเคราะห์) เลื่อนอยู่ในกล่องของตัวเอง
   ไม่ใช่ที่ main · วาดใหม่ทีไรจึงเด้งกลับซ้ายสุดทุกที ทั้งที่ผู้ใช้ไม่ได้สั่งอะไร
   จำเฉพาะกล่องที่ "เลื่อนค้างไว้จริง" ในหน้าที่เปิดอยู่ แล้วคืนค่าให้หลังวาดเสร็จ */
function _laScrollKey(el){
  var p=[], n=el, d=0;
  while(n && n.nodeType===1 && d<6){
    var c=(typeof n.className==='string' && n.className)
      ? ('.'+n.className.trim().split(/\s+/).slice(0,2).join('.')) : '';
    var ix=0; try{ ix=Array.prototype.indexOf.call(n.parentNode.children, n); }catch(_){}
    p.unshift(n.tagName+(n.id?('#'+n.id):'')+c+'['+ix+']');
    if(n.id) break;
    n=n.parentNode; d++;
  }
  return p.join('>');
}
function _laScrollSnap(){
  var out=[];
  try{
    var els=document.querySelectorAll('.view.active div, .view.active table');
    for(var i=0;i<els.length;i++){
      var e=els[i];
      if(e.scrollLeft>0 || e.scrollTop>0) out.push({k:_laScrollKey(e), l:e.scrollLeft, t:e.scrollTop});
    }
  }catch(_){}
  return out;
}
function _laScrollBack(list){
  if(!list || !list.length) return;
  try{
    var m={}; list.forEach(function(x){ m[x.k]=x; });
    var els=document.querySelectorAll('.view.active div, .view.active table');
    for(var i=0;i<els.length;i++){
      var e=els[i], x=m[_laScrollKey(e)];
      if(x){ if(x.l) e.scrollLeft=x.l; if(x.t) e.scrollTop=x.t; }
    }
  }catch(_){}
}
window._laRerender=function(){
  try{
    var mn=document.querySelector('main'); var sc=mn?mn.scrollTop:0; var scw=window.scrollY||0;
    var inner=_laScrollSnap();
    /* §ckLive (2026-09-12) · คืนโฟกัส + ตำแหน่ง cursor ของช่องที่กำลังพิมพ์อยู่
       หน้าเช็คอินต้องวาดใหม่ได้แม้โฟกัสอยู่ในช่องค้นหา (คนอื่นเช็คอินเข้ามาแล้วต้องเห็นทันที)
       ถ้าไม่คืนโฟกัส คนที่กำลังพิมพ์ชื่อลูกค้าจะโดนเด้งออกจากช่องกลางคัน */
    var _fid='', _fsel=null;
    try{ var _ae=document.activeElement;
      if(_ae && _ae.id && (_ae.tagName==='INPUT'||_ae.tagName==='TEXTAREA')){
        _fid=_ae.id;
        if(_ae.setSelectionRange) _fsel=[_ae.selectionStart, _ae.selectionEnd];
      } }catch(e){}
    var act=document.querySelector('.nav-item.active'); var v=act&&act.dataset?act.dataset.view:'';
    if(v==='booking' && typeof bkV2Render==='function') bkV2Render();
    else if(act && typeof nav==='function') nav(act);
    if(_fid){ try{ var _fe=document.getElementById(_fid);
      if(_fe && _fe.focus){ _fe.focus(); if(_fsel && _fe.setSelectionRange) _fe.setSelectionRange(_fsel[0], _fsel[1]); } }catch(e){} }
    _laScrollBack(inner);
    setTimeout(function(){ try{ var m2=document.querySelector('main'); if(m2&&sc) m2.scrollTop=sc; if(scw) window.scrollTo(0,scw);
      _laScrollBack(inner); }catch(e){} }, 60);
  }catch(e){}
};
