/* ══ §user→sales · สิทธิ์รายแถว ═══════════════════════════════════════════════════════════════════
   admin เห็นหมดเสมอ · user ที่ผูกกับ sales คนหนึ่ง (salesId มีค่า และ role ไม่ใช่ admin) = เห็นเฉพาะ
   เอเยนต์ที่ a.sales === salesId ของตัว · localhost/ไม่ผูก = เห็นหมด (เหมือนเดิม ไม่กระทบใครที่ยังไม่ตั้งค่า) */
function laMySalesId(){ return (window.LA_ME && window.LA_ME.salesId) || null; }
function laSalesScoped(){ const me = window.LA_ME||{}; return !!(me.salesId && me.role !== 'admin'); }
/* กรอง list ของเอเยนต์ให้เหลือเฉพาะของตัว (ถ้าถูก scope) · ตัวเดียวใช้ทุกที่ที่โชว์รายชื่อเอเยนต์ */
function laScopeAgents(list){
  if(!Array.isArray(list)) return list;
  if(!laSalesScoped()) return list;
  const my = laMySalesId();
  return list.filter(a => a && a.sales === my);
}
