// One-time seed · ตม.ทอ.ภูเก็ต ขาเข้า รายเดือน · 2568(2025) ครบปี + 2569(2026) ม.ค.–พ.ค.
(function(){ try{
  const flag='_md_monthly_seed_2569v1'; if(localStorage.getItem(flag)==='1') return;
  const seed={'2025-01':681606,'2025-02':538471,'2025-03':506019,'2025-04':432615,'2025-05':309158,'2025-06':315550,'2025-07':380168,'2025-08':375983,'2025-09':299371,'2025-10':418136,'2025-11':522789,'2025-12':644833,'2026-01':650837,'2026-02':601479,'2026-03':493585,'2026-04':382379,'2026-05':316745};
  let added=0; Object.keys(seed).forEach(k=>{ if(SB_MARKET_MONTHLY[k]==null){ SB_MARKET_MONTHLY[k]=seed[k]; added++; } });
  if(added) sbMarketMonthlyPersist();
  localStorage.setItem(flag,'1');
  console.log('Seeded monthly arrivals:', added, 'months');
}catch(e){ console.warn('monthly seed failed', e); } })();
