let INSURANCE_OVERRIDES=null;
function insEnsure(){ if(INSURANCE_OVERRIDES) return INSURANCE_OVERRIDES; try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); INSURANCE_OVERRIDES=(d.insurance_overrides&&typeof d.insurance_overrides==='object')?d.insurance_overrides:{}; }catch(e){ INSURANCE_OVERRIDES={}; } return INSURANCE_OVERRIDES; }
function insPersist(){ if(typeof window.laCanEditArea==='function' && !window.laCanEditArea('operations')) return;   /* §edit-guard · ดูอย่างเดียว → ไม่ persist */  try{ const raw=localStorage.getItem(LS_KEY); const d=raw?JSON.parse(raw):{}; d.insurance_overrides=insEnsure(); localStorage.setItem(LS_KEY, JSON.stringify(d)); }catch(e){} }
function insKey(bkId,pk){ return bkId+'::'+pk; }
function insOv(bkId,pk){ const s=insEnsure(); return s[insKey(bkId,pk)]||null; }
function insHas(bkId,pk,field){ const o=insOv(bkId,pk); return !!(o && o[field]!==undefined); }
function insEff(bkId,pk,field,src){ const o=insOv(bkId,pk); return (o && o[field]!==undefined)?o[field]:src; }
function insSetField(bkId,pk,field,val){ const s=insEnsure(); const k=insKey(bkId,pk); const o=s[k]=s[k]||{}; o[field]=val; o.at=Date.now(); insPersist(); const d=document.getElementById('ins-dot-'+field+'-'+bkId+'-'+pk); if(d) d.style.display='inline-block'; }
function insToggleReviewed(bkId,pk){ const s=insEnsure(); const k=insKey(bkId,pk); const o=s[k]=s[k]||{}; o.reviewed=!o.reviewed; o.at=Date.now(); insPersist(); renderInsurance(); }
function insRevertRow(bkId,pk){ const s=insEnsure(); const o=s[insKey(bkId,pk)]; if(!o) return; delete o.firstName; delete o.lastName; delete o.age; delete o.nat; insPersist(); renderInsurance(); }
function insDateShift(n){ const d=new Date(_insDate+'T00:00:00'); d.setDate(d.getDate()+n); _insDate=(typeof bkV2LocalYMD==='function')?bkV2LocalYMD(d):d.toISOString().slice(0,10); renderInsurance(); }
function insToday(){ _insDate=(typeof bkV2LocalYMD==='function')?bkV2LocalYMD(new Date()):new Date().toISOString().slice(0,10); renderInsurance(); }
function insSetDate(ds){ if(!ds) return; _insDate=ds; renderInsurance(); }   /* §laDatePick */
function insSplitName(nm){ nm=String(nm||'').trim(); if(!nm) return {f:'',l:''}; nm=nm.replace(/\s*\+?\d[\d\s().\-]{5,}\d\s*$/,'').trim(); nm=nm.replace(/^(mr|mrs|ms|miss|mstr|master|dr|prof|mx|khun)\b\.?\s*/i,'').trim(); if(!nm) return {f:'',l:''}; const p=nm.split(/\s+/); return {f:p[0], l:p.slice(1).join(' ')}; }
function insNatLabel(code){ if(!code) return ''; try{ return (typeof bkV2NatDDLabel==='function')?bkV2NatDDLabel(code):code; }catch(e){ return code; } }
function insBkPax(b){ const rows=[]; rows.push({key:'lead', name:b.leadPax||'', natCode:b.leadNationality||'', lead:true}); (b.passengers||[]).forEach((p,i)=>{ rows.push({key:String(i), name:(p&&p.name)||'', natCode:(p&&p.nationality)||''}); }); return rows; }
function insTripsForDate(ds){ const map={}; (typeof SB_BOOKINGS!=='undefined'?SB_BOOKINGS:[]).forEach(b=>{ if(!b||b.status==='cancelled'||b.status==='cancelled_weather'||b.status==='rejected') return; const tr=(b.trips||[]).filter(t=>t && t.date===ds); if(!tr.length) return; const rid=tr[0].routeId; const g=map[rid]=map[rid]||{routeId:rid, bookings:[]}; if(g.bookings.indexOf(b)<0) g.bookings.push(b); }); return Object.values(map); }
function insRouteName(rid){ const r=(typeof getRoute==='function')?getRoute(rid):null; if(!r) return rid||'-'; const f=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(rid):null; return (r.name||(f?f.name:rid)); }
// ── Booking Flow · incoming-bookings analytics (intake by day/week/month · market · sales · lead time · travel calendar) ──
let _bfMode='month';
function bfSetMode(m){ _bfMode=m; renderBookingFlow(); }
function renderBookingFlow(){
  const host=document.getElementById('bookingflow-host'); if(!host) return;
  const e=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ymd=d=>(typeof bkV2LocalYMD==='function')?bkV2LocalYMD(d):d.toISOString().slice(0,10);
  const paxOf=t=>(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot((t&&t.pax)||{}):0;
  const B=(typeof SB_BOOKINGS!=='undefined'?SB_BOOKINGS:[]).filter(b=>b && !['cancelled','cancelled_weather','rejected'].includes(b.status));
  const bkDate=b=>{ if(b.bookingDate) return String(b.bookingDate).slice(0,10); const tr=(b.trips||[]).map(t=>t.date).filter(Boolean).sort(); return tr[0]||''; };
  const firstTrip=b=>((b.trips||[]).filter(t=>t.date).sort((x,y)=>String(x.date).localeCompare(String(y.date)))[0])||null;
  const mkOf=b=>{ let code=(typeof pmMarket==='function')?pmMarket(b):((b.marketSnapshot&&b.marketSnapshot.market)||'unassigned'); code=code||'unassigned'; const m=(typeof sbGetMarket==='function')?sbGetMarket(code):null; return {code:code, name:m?(m.name||m.code||code):(code==='b2c'?'B2C':code==='unassigned'?'ไม่ระบุ':code), color:m?(m.color||'#94A3B8'):'#94A3B8'}; };
  const slOf=b=>{ const sid=b.soldBy||((typeof sbGetAgent==='function'&&sbGetAgent(b.agentId))||{}).sales; const s=sid&&typeof sbGetSales==='function'?sbGetSales(sid):null; return {id:sid||'__none', name:s?(s.name||sid):'(ไม่ระบุเซลล์)', color:s?(s.color||'#185FA5'):'#B8B3C8'}; };
  const famOf=rid=>{ const f=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(rid):null; const r=(typeof getRoute==='function')?getRoute(rid):null; return {id:f?f.id:(rid||'-'), name:f?(f.name||rid):(r?r.name:rid), color:(r&&r.color)||(f&&f.color)||'#1683C7'}; };
  const FALL=['#E0457F','#185FA5','#0F6E56','#A05A1A','#8B5CF6','#19A7C9'];
  const thMon=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];

  if(!B.length){ host.innerHTML='<div style="padding:40px;text-align:center;color:#9aa49c;font-size:13px;font-family:DM Sans,sans-serif">ยังไม่มีบุคกิ้ง · หน้านี้จะสรุปจากบุคกิ้งที่บันทึกแล้ว</div>'; return; }

  // ── period buckets ──
  const today=new Date();
  function periodBuckets(mode){
    const out=[];
    if(mode==='day'){ const DOW=['Sun','Mon','Tue','Wed','Thu','Fri','Sat']; for(let i=13;i>=0;i--){ const d=new Date(today); d.setDate(d.getDate()-i); out.push({label:String(d.getDate()), dow:DOW[d.getDay()], from:ymd(d), to:ymd(d)}); } }
    else if(mode==='week'){ const mon=new Date(today); mon.setDate(mon.getDate()-((mon.getDay()+6)%7)); for(let i=7;i>=0;i--){ const s=new Date(mon); s.setDate(s.getDate()-i*7); const en=new Date(s); en.setDate(en.getDate()+6); out.push({label:s.getDate()+'/'+(s.getMonth()+1), from:ymd(s), to:ymd(en)}); } }
    else { for(let i=5;i>=0;i--){ const s=new Date(today.getFullYear(), today.getMonth()-i, 1); const en=new Date(today.getFullYear(), today.getMonth()-i+1, 0); out.push({label:thMon[s.getMonth()], from:ymd(s), to:ymd(en)}); } }
    return out;
  }
  const buckets=periodBuckets(_bfMode);
  buckets.forEach(bk=>{ bk.total=0; bk.mk={}; bk.list=[]; });
  const findBucket=ds=>{ for(let i=0;i<buckets.length;i++){ if(ds>=buckets[i].from && ds<=buckets[i].to) return buckets[i]; } return null; };
  // top markets overall
  const mkCountAll={}; B.forEach(b=>{ const c=mkOf(b).code; mkCountAll[c]=(mkCountAll[c]||0)+1; });
  const topN=Object.keys(mkCountAll).sort((a,b)=>mkCountAll[b]-mkCountAll[a]).slice(0,4);
  B.forEach(b=>{ const bd=bkDate(b); if(!bd) return; const bk=findBucket(bd); if(!bk) return; bk.total++; bk.list.push(b); const c=mkOf(b).code; bk.mk[c]=(bk.mk[c]||0)+1; });
  buckets.forEach(bk=>{ let s=0; topN.forEach(c=>s+=bk.mk[c]||0); bk.mk.__other=Math.max(0,bk.total-s); });
  const mkOrder=topN.map((c,i)=>{ const m=(typeof sbGetMarket==='function')?sbGetMarket(c):null; return {code:c, name:m?(m.name||m.code||c):(c==='b2c'?'B2C':c==='unassigned'?'ไม่ระบุ':c), color:(m&&m.color)||FALL[i%FALL.length]}; }).concat([{code:'__other',name:'อื่นๆ',color:'#94A3B8'}]);

  // ── stacked intake bars SVG ──
  function barsSVG(){
    const W=940,H=248,padL=38,padR=12,padT=10,padB=34,iw=W-padL-padR,ih=H-padT-padB;
    const totals=buckets.map(b=>b.total); const mx=Math.max(1,Math.max.apply(null,totals))*1.15;
    let g='';
    for(let gy=0;gy<=4;gy++){ const y=padT+ih-ih*gy/4; g+='<line x1="'+padL+'" y1="'+y+'" x2="'+(W-padR)+'" y2="'+y+'" stroke="rgba(0,0,0,.06)"/><text x="'+(padL-6)+'" y="'+(y+3)+'" text-anchor="end" font-size="9" fill="#9aa0aa">'+Math.round(mx*gy/4)+'</text>'; }
    const bw=iw/buckets.length, bar=Math.min(30,bw*0.62);
    buckets.forEach((bk,i)=>{ let x=padL+bw*i+(bw-bar)/2, yy=padT+ih; mkOrder.forEach((m,mi)=>{ const v=bk.mk[m.code]||0; const h=ih*v/mx; yy-=h; g+='<rect x="'+x.toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+bar.toFixed(1)+'" height="'+Math.max(0,h).toFixed(1)+'" fill="'+m.color+'" '+(mi===mkOrder.length-1?'rx="3"':'')+'/>'; }); if(bk.dow){ g+='<text x="'+(x+bar/2).toFixed(1)+'" y="'+(H-18)+'" text-anchor="middle" font-size="8.5" fill="#b0b6bf">'+bk.dow+'</text><text x="'+(x+bar/2).toFixed(1)+'" y="'+(H-5)+'" text-anchor="middle" font-size="9.5" font-weight="600" fill="#8a919c">'+e(bk.label)+'</text>'; } else { g+='<text x="'+(x+bar/2).toFixed(1)+'" y="'+(H-8)+'" text-anchor="middle" font-size="9" fill="#8a919c">'+e(bk.label)+'</text>'; } });
    const pts=totals.map((t,i)=>{ const a=totals[Math.max(0,i-1)],c=totals[Math.min(totals.length-1,i+1)]; const mv=(a+t+c)/3; return [padL+bw*i+bw/2, padT+ih-ih*mv/mx]; });
    g+='<path d="M'+pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' L')+'" fill="none" stroke="#12314b" stroke-width="2" stroke-linecap="round" stroke-opacity=".85"/>';
    pts.forEach(p=>{ g+='<circle cx="'+p[0].toFixed(1)+'" cy="'+p[1].toFixed(1)+'" r="2.6" fill="#12314b"/>'; });
    return '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;display:block">'+g+'</svg>';
  }

  // ── dual line: bookings-in (pax) vs travel (pax) · window today-14 .. today+15 ──
  const inMap={},tvMap={};
  B.forEach(b=>{ const bd=bkDate(b); const ft=firstTrip(b); const fp=ft?paxOf(ft):0; if(bd) inMap[bd]=(inMap[bd]||0)+fp; (b.trips||[]).forEach(t=>{ if(t.date) tvMap[t.date]=(tvMap[t.date]||0)+paxOf(t); }); });
  const _DOW=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const days=[]; for(let off=-14; off<=15; off++){ const d=new Date(today); d.setDate(d.getDate()+off); const k=ymd(d); days.push({k:k, inV:inMap[k]||0, tvV:tvMap[k]||0, dnum:d.getDate(), dow:_DOW[d.getDay()], isToday:off===0}); }
  function dualSVG(){
    const W=620,H=228,padL=30,padR=12,padT=14,padB=32,iw=W-padL-padR,ih=H-padT-padB,N=days.length;
    let allmax=1; days.forEach(d=>{ allmax=Math.max(allmax,d.inV,d.tvV); }); const mx=allmax*1.14;
    let g='';
    for(let gy=0;gy<=3;gy++){ const y=padT+ih-ih*gy/3; g+='<line x1="'+padL+'" y1="'+y+'" x2="'+(W-padR)+'" y2="'+y+'" stroke="rgba(0,0,0,.06)"/>'; }
    // today marker
    const tx=padL+iw*14/(N-1); g+='<line x1="'+tx.toFixed(1)+'" y1="'+padT+'" x2="'+tx.toFixed(1)+'" y2="'+(padT+ih)+'" stroke="#c9ced6" stroke-width="1" stroke-dasharray="3 3"/><text x="'+tx.toFixed(1)+'" y="'+(padT-4)+'" text-anchor="middle" font-size="8.5" fill="#9aa0aa">วันนี้</text>';
    function ln(sel,col,fill){ const pts=days.map((d,i)=>[padL+iw*i/(N-1), padT+ih-ih*sel(d)/mx]); const dd='M'+pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' L'); let s=''; if(fill) s+='<path d="'+dd+' L'+(padL+iw)+','+(padT+ih)+' L'+padL+','+(padT+ih)+' Z" fill="'+col+'" fill-opacity=".08"/>'; s+='<path d="'+dd+'" fill="none" stroke="'+col+'" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>'; return s; }
    g+=ln(d=>d.tvV,'#F2A33C',true); g+=ln(d=>d.inV,'#1683C7',true);
    // x labels (every 5 days)
    days.forEach((d,i)=>{ if(i%5===0){ const lx=(padL+iw*i/(N-1)).toFixed(1); g+='<text x="'+lx+'" y="'+(H-18)+'" text-anchor="middle" font-size="8" fill="#b0b6bf">'+d.dow+'</text><text x="'+lx+'" y="'+(H-6)+'" text-anchor="middle" font-size="8.5" font-weight="600" fill="#8a919c">'+d.dnum+'</text>'; } });
    return '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;display:block">'+g+'</svg>';
  }

  // ── KPIs from current bucket ──
  const cur=buckets[buckets.length-1], prev=buckets[buckets.length-2]||{total:0,list:[]};
  const _fmtD=ds=>{ const d=new Date(ds+'T00:00:00'); return isNaN(d)?ds:(d.getDate()+' '+thMon[d.getMonth()]); };
  const curRangeLbl=(cur.from===cur.to)?_fmtD(cur.from):(_fmtD(cur.from)+' – '+_fmtD(cur.to));
  let perPax=0, leadSum=0, leadN=0; const mkC={}, slC={};
  cur.list.forEach(b=>{ const ft=firstTrip(b); const p=ft?paxOf(ft):0; perPax+=p; const bd=bkDate(b); if(ft&&bd){ const ld=Math.round((new Date(ft.date+'T00:00:00')-new Date(bd+'T00:00:00'))/86400000); if(ld>=0&&ld<400){ leadSum+=ld; leadN++; } } const mc=mkOf(b); mkC[mc.code]=mkC[mc.code]||{n:0,name:mc.name,color:mc.color}; mkC[mc.code].n++; const sl=slOf(b); slC[sl.id]=slC[sl.id]||{n:0,pax:0,name:sl.name,color:sl.color}; slC[sl.id].n++; slC[sl.id].pax+=p; });
  const avgLead=leadN?(leadSum/leadN):0;
  const topMk=Object.values(mkC).sort((a,b)=>b.n-a.n)[0];
  const topSl=Object.values(slC).sort((a,b)=>b.n-a.n)[0];
  const momPct=prev.total?Math.round((cur.total-prev.total)/prev.total*100):0;
  const periodLbl=_bfMode==='day'?'Today':_bfMode==='week'?'This week':'This month';
  const rangeLbl=buckets[0].from+' → '+cur.to;

  // ── horizontal bars ──
  function hbars(items){ const mx=Math.max(1,Math.max.apply(null,items.map(i=>i.val))); return items.map(i=>'<div class="bfw-brow"><div class="bfw-blab"><span class="bfw-dot" style="background:'+i.color+'"></span>'+e(i.label)+'</div><div class="bfw-btrack"><div class="bfw-bfill" style="width:'+(i.val/mx*100).toFixed(1)+'%;background:'+i.color+'"></div></div><div class="bfw-bval">'+e(i.disp)+'</div></div>').join(''); }
  const salesItems=Object.values(slC).sort((a,b)=>b.pax-a.pax).slice(0,6).map(s=>({label:s.name,color:s.color,val:s.pax,disp:s.pax+' ('+s.n+')'}));
  const mktItems=Object.values(mkC).sort((a,b)=>b.n-a.n).slice(0,6).map(m=>({label:m.name,color:m.color,val:m.n,disp:(cur.total?Math.round(m.n/cur.total*100):0)+'%'}));
  const famPax={}; let famTot=0; cur.list.forEach(b=>{ (b.trips||[]).forEach(t=>{ if(!t.date) return; const f=famOf(t.routeId); famPax[f.id]=famPax[f.id]||{name:f.name,color:f.color,p:0}; famPax[f.id].p+=paxOf(t); famTot+=paxOf(t); }); });
  const destItems=Object.values(famPax).sort((a,b)=>b.p-a.p).slice(0,6).map(f=>({label:f.name,color:f.color,val:f.p,disp:(famTot?Math.round(f.p/famTot*100):0)+'%'}));

  // ── calendar heatmap · current month · pax departing ──
  function calHTML(){
    const y=today.getFullYear(), m=today.getMonth(); const first=new Date(y,m,1), firstDow=first.getDay(), ndays=new Date(y,m+1,0).getDate();
    const pax={}; B.forEach(b=>{ (b.trips||[]).forEach(t=>{ if(!t.date) return; const dd=new Date(t.date+'T00:00:00'); if(dd.getFullYear()===y&&dd.getMonth()===m) pax[dd.getDate()]=(pax[dd.getDate()]||0)+paxOf(t); }); });
    const mxp=Math.max(1,Math.max.apply(null,Object.values(pax).concat([1])));
    const dows=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    let cells=''; for(let b0=0;b0<firstDow;b0++) cells+='<div class="bfw-cell empty"></div>';
    for(let d=1;d<=ndays;d++){ const p=pax[d]||0; const op=(0.08+p/mxp*0.84).toFixed(2); const strong=p/mxp>0.55; const isT=(d===today.getDate()); cells+='<div class="bfw-cell'+(isT?' t':'')+'" style="background:rgba(22,131,199,'+op+')" title="'+p+' pax ออกเดินทาง"><div class="bfw-cnum" style="color:'+(strong?'#eaf3fb':'#33465c')+'">'+d+'</div><div class="bfw-cpax" style="color:'+(strong?'#fff':'#1683C7')+'">'+(p||'')+'</div></div>'; }
    return '<div class="bfw-calhd">'+dows.map(x=>'<div>'+x+'</div>').join('')+'</div><div class="bfw-calgrid">'+cells+'</div>';
  }

  // ── cohort heatmap · booking date (rows) × travel date (cols) · pax ──
  function cohortHTML(){
    const rowN=14, colN=28; const start=new Date(today); start.setDate(start.getDate()-13);
    const rows=[],cols=[];
    for(let i=0;i<rowN;i++){ const d=new Date(start); d.setDate(d.getDate()+i); rows.push({k:ymd(d), d:d.getDate(), mo:d.getMonth()+1, today:ymd(d)===ymd(today)}); }
    for(let i=0;i<colN;i++){ const d=new Date(start); d.setDate(d.getDate()+i); cols.push({k:ymd(d), d:d.getDate(), we:(d.getDay()===0||d.getDay()===6), today:ymd(d)===ymd(today)}); }
    const ri={},ci={}; rows.forEach((r,i)=>ri[r.k]=i); cols.forEach((c,i)=>ci[c.k]=i);
    const M=rows.map(()=>cols.map(()=>0));
    B.forEach(b=>{ const bd=bkDate(b); if(!(bd in ri)) return; (b.trips||[]).forEach(t=>{ if(t.date in ci) M[ri[bd]][ci[t.date]]+=paxOf(t); }); });
    let mx=1; M.forEach(r=>r.forEach(v=>{ if(v>mx)mx=v; }));
    let h='<div class="bfw-ch" style="grid-template-columns:56px repeat('+colN+',1fr)"><div class="bfw-chcorner">จอง&#8595;<br>เที่ยว&#8594;</div>';
    cols.forEach(c=>{ h+='<div class="bfw-chlab'+(c.today?' t':'')+(c.we?' we':'')+'">'+c.d+'</div>'; });
    rows.forEach((r,rri)=>{ h+='<div class="bfw-chlab row'+(r.today?' t':'')+'">'+r.d+'/'+r.mo+'</div>'; M[rri].forEach((v,cci)=>{ const op=v===0?0:(0.14+v/mx*0.82); h+='<div class="bfw-chcell'+(cols[cci].today?' tcol':'')+'" title="'+e('จอง '+r.k+' → เที่ยว '+cols[cci].k+' · '+v+' pax')+'" style="background:'+(v===0?'#F4F6F8':'rgba(22,131,199,'+op.toFixed(2)+')')+'"></div>'; }); });
    return h+'</div>';
  }
  // ── lead-time distribution histogram · days between booking and travel · all bookings ──
  function leadHistSVG(){
    const bk=[['same day',0,0],['1–2',1,2],['3–7',3,7],['8–14',8,14],['15–30',15,30],['30+',31,100000]];
    const cnt=bk.map(()=>0); let tot=0;
    B.forEach(b=>{ const ft=firstTrip(b); const bd=bkDate(b); if(!ft||!bd) return; const ld=Math.round((new Date(ft.date+'T00:00:00')-new Date(bd+'T00:00:00'))/86400000); if(ld<0||ld>1200) return; tot++; for(let i=0;i<bk.length;i++){ if(ld>=bk[i][1]&&ld<=bk[i][2]){ cnt[i]++; break; } } });
    const W=520,H=160,padL=22,padB=26,padT=14,iw=W-padL-14,ih=H-padT-padB; const pct=cnt.map(c=>tot?c/tot*100:0); const mx=Math.max(1,Math.max.apply(null,pct))*1.12; const bw=iw/bk.length; let g='';
    bk.forEach((d,i)=>{ const h=ih*pct[i]/mx, x=padL+bw*i+bw*0.16, w=bw*0.68, y=padT+ih-h; g+='<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+Math.max(0,h).toFixed(1)+'" rx="4" fill="'+(i>=2&&i<=3?'#1683C7':'#9DC7E6')+'"/>'; g+='<text x="'+(x+w/2).toFixed(1)+'" y="'+(y-4).toFixed(1)+'" text-anchor="middle" font-size="10" font-weight="700" fill="#39404b">'+Math.round(pct[i])+'%</text>'; g+='<text x="'+(x+w/2).toFixed(1)+'" y="'+(H-9)+'" text-anchor="middle" font-size="9" fill="#8a919c">'+d[0]+'</text>'; });
    return '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="xMidYMid meet" style="width:100%;max-width:560px;height:auto;display:block">'+g+'</svg>';
  }

  const seg=(k,l)=>'<button onclick="bfSetMode(\''+k+'\')" class="'+(_bfMode===k?'on':'')+'">'+l+'</button>';
  const legHTML=mkOrder.map(m=>'<span><i style="background:'+m.color+'"></i>'+e(m.name)+'</span>').join('')+'<span><i style="background:#12314b;height:3px;width:14px;border-radius:2px"></i>avg</span>';

  host.innerHTML=`
  <style>
    #bookingflow-host{font-family:'DM Sans',-apple-system,system-ui,sans-serif;color:#1b2330}
    #bookingflow-host .bfw-seg{display:flex;background:#eef1f5;border-radius:20px;padding:3px}
    #bookingflow-host .bfw-seg button{border:0;background:transparent;color:#6b7280;font:inherit;font-size:12px;font-weight:600;padding:7px 15px;border-radius:16px;cursor:pointer}
    #bookingflow-host .bfw-seg button.on{background:#1683C7;color:#fff}
    #bookingflow-host .bfw-kpi,#bookingflow-host .bfw-card{background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:12px}
    #bookingflow-host .bfw-kl{font-size:10.5px;text-transform:uppercase;letter-spacing:.04em;color:#8a919c;font-weight:600}
    #bookingflow-host .bfw-kv{font-size:24px;font-weight:700;margin-top:4px;font-variant-numeric:tabular-nums}
    #bookingflow-host .bfw-kv span{font-size:12px;font-weight:500;color:#8a919c}
    #bookingflow-host .bfw-kv.sm{font-size:17px;display:flex;align-items:center;gap:6px}
    #bookingflow-host .bfw-kd{font-size:11px;margin-top:4px;color:#8a919c}
    #bookingflow-host .bfw-kd.up{color:#0F8A5F}#bookingflow-host .bfw-kd.dn{color:#C0603A}
    #bookingflow-host .bfw-dot{width:11px;height:11px;border-radius:50%;display:inline-block;flex:none}
    #bookingflow-host .bfw-cardt{font-size:13px;font-weight:700}
    #bookingflow-host .bfw-mut{font-weight:500;color:#9aa0aa;font-size:11.5px}
    #bookingflow-host .bfw-note{font-size:11px;color:#9aa0aa;margin-top:8px;line-height:1.5}
    #bookingflow-host .bfw-leg{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;color:#6b7280}
    #bookingflow-host .bfw-leg span{display:inline-flex;align-items:center;gap:5px}
    #bookingflow-host .bfw-leg i{width:10px;height:10px;border-radius:3px;display:inline-block}
    #bookingflow-host .bfw-brow{display:grid;grid-template-columns:100px 1fr 66px;align-items:center;gap:9px;font-size:12px;margin-bottom:9px}
    #bookingflow-host .bfw-blab{display:flex;align-items:center;gap:6px;color:#39404b;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    #bookingflow-host .bfw-btrack{height:16px;background:#eef1f5;border-radius:8px;overflow:hidden}
    #bookingflow-host .bfw-bfill{height:100%;border-radius:8px}
    #bookingflow-host .bfw-bval{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}
    #bookingflow-host .bfw-calhd{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-bottom:6px}
    #bookingflow-host .bfw-calhd div{text-align:center;font-size:10.5px;font-weight:700;color:#9aa0aa}
    #bookingflow-host .bfw-calgrid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}
    #bookingflow-host .bfw-cell{aspect-ratio:1.5/1;border-radius:8px;padding:6px 8px;position:relative;border:1px solid rgba(0,0,0,.04)}
    #bookingflow-host .bfw-cell.t{outline:2px solid #1683C7;outline-offset:-2px}
    #bookingflow-host .bfw-cell.empty{background:transparent!important;border:0}
    #bookingflow-host .bfw-cnum{font-size:11px;font-weight:700}
    #bookingflow-host .bfw-cpax{position:absolute;right:7px;bottom:5px;font-size:11px;font-weight:800;font-variant-numeric:tabular-nums}
    #bookingflow-host .bfw-sc{width:16px;height:12px;border-radius:3px;display:inline-block}
    #bookingflow-host .bfw-ch{display:grid;gap:2px;min-width:660px}
    #bookingflow-host .bfw-chcell{height:18px;border-radius:2px}
    #bookingflow-host .bfw-chcell.tcol{outline:1.5px solid rgba(22,131,199,.45);outline-offset:-1px}
    #bookingflow-host .bfw-chlab{font-size:9px;color:#8a919c;display:flex;align-items:center;justify-content:center;height:18px}
    #bookingflow-host .bfw-chlab.row{justify-content:flex-end;padding-right:5px;font-weight:600;color:#39404b}
    #bookingflow-host .bfw-chlab.t{color:#1683C7;font-weight:800}
    #bookingflow-host .bfw-chlab.we{color:#c07a3a}
    #bookingflow-host .bfw-chcorner{font-size:8px;color:#b0b6bf;line-height:1.15;display:flex;flex-direction:column;align-items:flex-end;justify-content:center;text-align:right;padding-right:4px}
  </style>
  <div style="width:100%;max-width:1320px;margin:0 auto;padding:2px 4px 20px">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:14px">
      <div><div style="font-size:21px;font-weight:700">Booking Flow</div><div style="font-size:12.5px;color:#7a828e;margin-top:2px">Incoming bookings · market · sales · destination · lead time · trend</div></div>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap"><div class="bfw-seg">${seg('day','Day')}${seg('week','Week')}${seg('month','Month')}</div><div style="font-size:12px;color:#7a828e;background:#eef1f5;border-radius:16px;padding:7px 13px">${e(rangeLbl)}</div></div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px">
      <div class="bfw-kpi" style="padding:13px 15px"><div class="bfw-kl">New bookings · ${periodLbl}</div><div class="bfw-kv">${cur.total.toLocaleString()}</div><div class="bfw-kd ${momPct>=0?'up':'dn'}">${momPct>=0?'▲':'▼'} ${Math.abs(momPct)}% vs ${_bfMode==='month'?'last month':_bfMode==='week'?'last week':'yesterday'}</div></div>
      <div class="bfw-kpi" style="padding:13px 15px"><div class="bfw-kl">Pax booked</div><div class="bfw-kv">${perPax.toLocaleString()}</div><div class="bfw-kd">${periodLbl}</div></div>
      <div class="bfw-kpi" style="padding:13px 15px"><div class="bfw-kl">Avg lead time</div><div class="bfw-kv">${avgLead.toFixed(1)} <span>days</span></div><div class="bfw-kd">booking → travel</div></div>
      <div class="bfw-kpi" style="padding:13px 15px"><div class="bfw-kl">Top market</div><div class="bfw-kv sm"><span class="bfw-dot" style="background:${topMk?topMk.color:'#94A3B8'}"></span>${topMk?e(topMk.name):'-'}</div><div class="bfw-kd">${topMk&&cur.total?Math.round(topMk.n/cur.total*100):0}% of bookings</div></div>
      <div class="bfw-kpi" style="padding:13px 15px"><div class="bfw-kl">Top salesperson</div><div class="bfw-kv sm"><span class="bfw-dot" style="background:${topSl?topSl.color:'#B8B3C8'}"></span>${topSl?e(topSl.name):'-'}</div><div class="bfw-kd">${topSl?topSl.n:0} bookings</div></div>
    </div>

    <div class="bfw-card" style="padding:15px 17px;margin-bottom:13px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px"><div class="bfw-cardt">New Bookings Over Time <span class="bfw-mut">· ${_bfMode==='day'?'daily (14 days)':_bfMode==='week'?'weekly (8 weeks)':'monthly (6 months)'} · by market</span></div><div class="bfw-leg">${legHTML}</div></div>
      ${barsSVG()}
      <div class="bfw-note">แท่ง = บุคกิ้งที่ <b>เข้ามา</b> (วันที่จอง) · เส้น = ค่าเฉลี่ยเคลื่อนที่ (ทิศทาง)</div>
    </div>

    <div style="display:grid;grid-template-columns:1.7fr 1fr;gap:13px;margin-bottom:13px">
      <div class="bfw-card" style="padding:15px 17px">
        <div class="bfw-cardt">Bookings In <span style="color:#1683C7">━</span> vs Travel Date <span style="color:#F2A33C">━</span> <span class="bfw-mut">· lead time (pax/day)</span></div>
        ${dualSVG()}
        <div class="bfw-note">เส้นน้ำเงิน (จองเข้า) มักมา <b>ก่อน</b> เส้นส้ม (ออกเดินทาง) · ช่องว่างแนวนอน = lead time · เส้นส้มขวาเส้นวันนี้ = ที่จองไว้ล่วงหน้า</div>
      </div>
      <div class="bfw-card" style="padding:15px 17px">
        <div class="bfw-cardt">By Salesperson <span class="bfw-mut">· ${periodLbl} · ${e(curRangeLbl)} · pax (booking)</span></div>
        <div style="margin-top:10px">${salesItems.length?hbars(salesItems):'<div class="bfw-note">ไม่มีข้อมูล</div>'}</div>
      </div>
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-bottom:13px">
      <div class="bfw-card" style="padding:15px 17px"><div class="bfw-cardt">Market Mix <span class="bfw-mut">· ${periodLbl}</span></div><div style="margin-top:10px">${mktItems.length?hbars(mktItems):'<div class="bfw-note">ไม่มีข้อมูล</div>'}</div></div>
      <div class="bfw-card" style="padding:15px 17px"><div class="bfw-cardt">Destination · Program <span class="bfw-mut">· pax</span></div><div style="margin-top:10px">${destItems.length?hbars(destItems):'<div class="bfw-note">ไม่มีข้อมูล</div>'}</div></div>
    </div>

    <div class="bfw-card" style="padding:15px 17px;margin-bottom:13px">
      <div class="bfw-cardt">Booking Date → Travel Date <span class="bfw-mut">· 14 วันจอง × 28 วันเที่ยว · ช่องเข้ม = pax เยอะ</span></div>
      <div style="overflow-x:auto;margin-top:10px">${cohortHTML()}</div>
      <div class="bfw-note">แต่ละแถว = วันที่ <b>จอง</b> หนึ่งวัน → ช่องเข้มบอกว่าคนล็อตนั้นไป <b>เที่ยว</b> วันไหน · แนวทแยง = จองแล้วไปเลย (lead สั้น) · ยิ่งไปทางขวา = จองล่วงหน้านาน · คอลัมน์กรอบน้ำเงิน = วันนี้</div>
    </div>

    <div class="bfw-card" style="padding:15px 17px;margin-bottom:13px">
      <div class="bfw-cardt">Lead-Time Distribution <span class="bfw-mut">· จองล่วงหน้ากี่วันก่อนเดินทาง · ทุกบุคกิ้ง</span></div>
      <div style="margin-top:8px">${leadHistSVG()}</div>
      <div class="bfw-note">ภาพรวมพฤติกรรมจอง — แท่งน้ำเงินเข้ม (3–14 วัน) = ช่วงที่คนจองบ่อยสุด · ซ้ายมาก = จองกระชั้น/วันนี้ · ขวามาก = จองล่วงหน้านาน</div>
    </div>

    <div class="bfw-card" style="padding:15px 17px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px"><div class="bfw-cardt">Travel-Date Calendar <span class="bfw-mut">· ${thMon[today.getMonth()]} ${today.getFullYear()+543} · darker = more pax departing</span></div><div style="display:flex;align-items:center;gap:4px;font-size:10.5px;color:#9aa0aa">less<span class="bfw-sc" style="background:rgba(22,131,199,.15)"></span><span class="bfw-sc" style="background:rgba(22,131,199,.38)"></span><span class="bfw-sc" style="background:rgba(22,131,199,.62)"></span><span class="bfw-sc" style="background:rgba(22,131,199,.9)"></span> more</div></div>
      <div style="margin-top:6px">${calHTML()}</div>
    </div>
  </div>`;
}
function renderInsurance(){
  const host=document.getElementById('insurance-host'); if(!host) return;
  const e=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ds=_insDate;
  const dt=new Date(ds+'T00:00:00');
  const dateLbl=isNaN(dt)?ds:dt.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
  const trips=insTripsForDate(ds);
  let totPax=0, totRev=0, totNoAge=0, totMissing=0;
  const cards=trips.map(g=>{
    g.bookings.sort((a,b)=>String(a.id||'').localeCompare(String(b.id||'')));
    let tPax=0, tRev=0, tNoAge=0, tMiss=0;
    let rowsHtml=''; let ri=0;
    g.bookings.forEach(b=>{
      const pr=insBkPax(b);
      // expected head count for this trip vs listed names → travelers with no name entered (dropped at save · not insurable)
      const _t=(b.trips||[]).find(t=>(t.date||'')===ds && t.routeId===g.routeId) || (b.trips||[]).find(t=>(t.date||'')===ds);
      const _hc=(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot((_t&&_t.pax)||{}):pr.length;
      if(_hc>pr.length) tMiss+=(_hc-pr.length);
      pr.forEach(p=>{
        const sn=insSplitName(p.name);
        const fn=insEff(b.id,p.key,'firstName',sn.f);
        const ln=insEff(b.id,p.key,'lastName',sn.l);
        const ageV=insEff(b.id,p.key,'age','');
        const natSrc=insNatLabel(p.natCode);
        const natV=insEff(b.id,p.key,'nat',natSrc);
        const rev=!!(insOv(b.id,p.key)||{}).reviewed;
        const ageBlank=!(String(ageV).trim());
        tPax++; if(rev)tRev++; if(ageBlank)tNoAge++;
        const zt=ri%2?'#FAFAF7':'#FFFFFF'; ri++;
        const dot=(field)=>`<span id="ins-dot-${field}-${e(b.id)}-${p.key}" title="override" style="display:${insHas(b.id,p.key,field)?'inline-block':'none'};width:7px;height:7px;border-radius:50%;background:#7F77DD;flex:none"></span>`;
        const inp='padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box;border:1px solid #DEDCD2;border-radius:7px;background:#fff;font-family:inherit';
        const ageBox=ageBlank
          ? `<div style="display:flex;align-items:center;gap:5px;border:1px solid #E24B4A;background:#FDECEC;border-radius:7px;padding:0 4px"><span style="color:#A32D2D;font-size:11px;padding-left:3px">!</span><input type="number" min="0" max="120" value="" placeholder="กรอก" oninput="insSetField('${e(b.id)}','${p.key}','age',this.value)" style="width:52px;border:0;background:transparent;font-size:12px;padding:6px 2px;text-align:center;font-family:inherit;color:#A32D2D"></div>`
          : `<div style="display:flex;align-items:center;gap:4px;border:1px solid ${insHas(b.id,p.key,'age')?'#7F77DD':'#DEDCD2'};background:#fff;border-radius:7px;padding:0 6px"><input type="number" min="0" max="120" value="${e(ageV)}" oninput="insSetField('${e(b.id)}','${p.key}','age',this.value)" style="width:44px;border:0;background:transparent;font-size:12px;padding:6px 0;text-align:center;font-family:inherit;font-weight:700;color:#1B2A55">${dot('age')}</div>`;
        const revCell=rev
          ? `<button onclick="insToggleReviewed('${e(b.id)}','${p.key}')" style="display:inline-flex;align-items:center;gap:5px;background:#E1F5EE;color:#0F6E56;border:1px solid #B7E3D2;border-radius:7px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">&#10003; Reviewed</button>`
          : `<button onclick="insToggleReviewed('${e(b.id)}','${p.key}')" style="display:inline-flex;align-items:center;gap:5px;background:#fff;color:#5F5E5A;border:1px solid #D6D4CA;border-radius:7px;padding:4px 10px;font-size:11px;cursor:pointer;font-family:inherit">Mark</button>`;
        const anyOv=insHas(b.id,p.key,'firstName')||insHas(b.id,p.key,'lastName')||insHas(b.id,p.key,'age')||insHas(b.id,p.key,'nat');
        rowsHtml+=`<div style="display:grid;grid-template-columns:32px 128px 1fr 1fr 118px 1.4fr 118px 30px;gap:0 10px;align-items:center;padding:7px 12px;background:${zt};border-top:0.5px solid #EEEDE6">
          <div style="font-size:11px;color:#9a9a90;font-variant-numeric:tabular-nums">${ri}</div>
          <div style="font-size:10.5px;color:#6a6a62">${e(b.voucherRef&&b.voucherRef!==p.name?b.voucherRef:(b.id||''))}${p.lead?' <span style="font-size:8.5px;font-weight:700;color:#0C447C;background:#E6F1FB;border-radius:4px;padding:1px 5px">lead</span>':''}</div>
          <div style="display:flex;align-items:center;gap:5px"><input value="${e(fn)}" placeholder="First" oninput="insSetField('${e(b.id)}','${p.key}','firstName',this.value)" style="${inp}">${dot('firstName')}</div>
          <div style="display:flex;align-items:center;gap:5px"><input value="${e(ln)}" placeholder="Last" oninput="insSetField('${e(b.id)}','${p.key}','lastName',this.value)" style="${inp}">${dot('lastName')}</div>
          <div>${ageBox}</div>
          <div style="display:flex;align-items:center;gap:5px"><input value="${e(natV)}" placeholder="Nationality" oninput="insSetField('${e(b.id)}','${p.key}','nat',this.value)" style="${inp}">${dot('nat')}</div>
          <div style="text-align:center">${revCell}</div>
          <div style="text-align:center">${anyOv?`<button onclick="insRevertRow('${e(b.id)}','${p.key}')" title="คืนค่าจาก Booking" style="border:0;background:transparent;color:#9a9a90;cursor:pointer;font-size:14px;padding:2px">&#8634;</button>`:''}</div>
        </div>`;
      });
    });
    totPax+=tPax; totRev+=tRev; totNoAge+=tNoAge; totMissing+=tMiss;
    const pct=tPax>0?Math.round(tRev/tPax*100):0;
    return `<div style="background:#fff;border:1px solid #E7E5DD;border-radius:14px;overflow:hidden;margin-bottom:14px">
      <div style="display:flex;align-items:center;gap:14px;padding:12px 16px;border-left:4px solid #185FA5;background:#F7FAFC;flex-wrap:wrap">
        <div><div style="font-size:14px;font-weight:800;color:#1B2A55">${e(insRouteName(g.routeId))}</div><div style="font-size:11px;color:#8a8f93">${e(dateLbl)} · ${g.bookings.length} booking</div></div>
        <button onclick="insPrint('${e(g.routeId)}')" title="พิมพ์เฉพาะเส้นทางนี้" style="border:1px solid #C7D6E6;background:#fff;color:#185FA5;border-radius:8px;padding:5px 11px;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit;white-space:nowrap">&#128424; พิมพ์เส้นทางนี้</button>
        <div style="margin-left:auto;display:flex;align-items:center;gap:16px">
          <div style="text-align:center"><div style="font-size:18px;font-weight:800;color:#1B2A55;font-variant-numeric:tabular-nums">${tPax}</div><div style="font-size:9px;text-transform:uppercase;letter-spacing:.04em;color:#9aa49c">pax</div></div>
          <div style="text-align:center"><div style="font-size:18px;font-weight:800;color:${tNoAge?'#A32D2D':'#0F6E56'};font-variant-numeric:tabular-nums">${tNoAge}</div><div style="font-size:9px;text-transform:uppercase;letter-spacing:.04em;color:${tNoAge?'#A32D2D':'#9aa49c'}">no age</div></div>
          <div style="text-align:center" title="ผู้โดยสารที่ยังไม่ได้กรอกชื่อ (นับจากจำนวน pax เทียบกับรายชื่อ) — ประกันไม่ครบ"><div style="font-size:18px;font-weight:800;color:${tMiss?'#A05A1A':'#0F6E56'};font-variant-numeric:tabular-nums">${tMiss}</div><div style="font-size:9px;text-transform:uppercase;letter-spacing:.04em;color:${tMiss?'#A05A1A':'#9aa49c'}">missing name</div></div>
          <div style="min-width:140px"><div style="display:flex;justify-content:space-between;font-size:10.5px;color:#6a6a62;margin-bottom:3px"><span>reviewed</span><span style="font-weight:700">${tRev} / ${tPax}</span></div><div style="height:7px;background:#EEECE4;border-radius:4px;overflow:hidden"><div style="width:${pct}%;height:100%;background:#0F6E56"></div></div></div>
        </div>
      </div>
      <div style="overflow-x:auto"><div style="min-width:840px">
        <div style="display:grid;grid-template-columns:32px 128px 1fr 1fr 118px 1.4fr 118px 30px;gap:0 10px;padding:8px 12px;border-bottom:1.5px solid #E5E2D8;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:#9a9a90">
          <div>#</div><div>Booking</div><div>First name</div><div>Last name</div><div>Age</div><div>Nationality</div><div style="text-align:center">Reviewed</div><div></div>
        </div>${rowsHtml}
      </div></div>
    </div>`;
  }).join('');
  const empty=`<div style="background:#fff;border:1px solid #E7E5DD;border-radius:14px;padding:40px;text-align:center;color:#9aa49c;font-size:13px">ไม่มีทริปในวันนี้</div>`;
  const totPct=totPax>0?Math.round(totRev/totPax*100):0;
  host.innerHTML=`<div style="max-width:100%;font-family:Manrope,-apple-system,system-ui,sans-serif">
    <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px">
      <div style="display:flex;align-items:center;gap:10px">
        <div style="width:36px;height:36px;border-radius:10px;background:#E6F1FB;display:flex;align-items:center;justify-content:center;color:#185FA5;font-size:20px">&#128737;</div>
        <div><div style="font-size:18px;font-weight:800;color:#1B2A55">Insurance · passenger list</div><div style="font-size:12px;color:#8a8f93">รีวิว อายุ + สัญชาติ ลูกค้าอีกรอบ · แก้ทับได้ · ไม่กระทบ Booking หลัก</div></div>
      </div>
      <div style="margin-left:auto;display:flex;align-items:center;gap:8px">
        ${laDateBar(_insDate,'insDateShift','insToday','','insSetDate')}
        <button onclick="insPrint()" title="พิมพ์ทุกเส้นทางของวันนี้ · หนึ่งเส้นทางต่อหนึ่งแผ่น" style="display:inline-flex;align-items:center;gap:6px;border:1px solid #185FA5;background:#185FA5;color:#fff;border-radius:9px;padding:7px 14px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:inherit">&#128424; พิมพ์ทุกเส้นทาง</button>
      </div>
    </div>
    ${trips.length?`<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px">
      <div style="flex:1;min-width:120px;background:#fff;border:1px solid #E7E5DD;border-radius:12px;padding:11px 15px"><div style="font-size:22px;font-weight:800;color:#1B2A55;font-variant-numeric:tabular-nums">${totPax}</div><div style="font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:#9aa49c">total pax · ${trips.length} trip</div></div>
      <div style="flex:1;min-width:120px;background:#fff;border:1px solid ${totNoAge?'#F0C9C9':'#E7E5DD'};border-radius:12px;padding:11px 15px"><div style="font-size:22px;font-weight:800;color:${totNoAge?'#A32D2D':'#0F6E56'};font-variant-numeric:tabular-nums">${totNoAge}</div><div style="font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:${totNoAge?'#A32D2D':'#9aa49c'}">ยังไม่กรอกอายุ</div></div>
      <div style="flex:1;min-width:120px;background:#fff;border:1px solid ${totMissing?'#EAD6B6':'#E7E5DD'};border-radius:12px;padding:11px 15px" title="ผู้โดยสารที่ยังไม่ได้กรอกชื่อ · ประกันไม่ครบจำนวนคน"><div style="font-size:22px;font-weight:800;color:${totMissing?'#A05A1A':'#0F6E56'};font-variant-numeric:tabular-nums">${totMissing}</div><div style="font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:${totMissing?'#A05A1A':'#9aa49c'}">ยังไม่กรอกชื่อ</div></div>
      <div style="flex:1.4;min-width:170px;background:#1F4D2C;border-radius:12px;padding:11px 15px"><div style="display:flex;justify-content:space-between;align-items:baseline"><span style="font-size:22px;font-weight:800;color:#fff;font-variant-numeric:tabular-nums">${totRev}/${totPax}</span><span style="font-size:11px;color:#9BB89B">reviewed ${totPct}%</span></div><div style="height:6px;background:rgba(255,255,255,.18);border-radius:4px;overflow:hidden;margin-top:8px"><div style="width:${totPct}%;height:100%;background:#C8F47C"></div></div></div>
    </div>`:''}
    ${cards||empty}
    <div style="font-size:10.5px;color:#9aa49c;margin-top:6px;line-height:1.6"><span style="display:inline-flex;align-items:center;gap:5px;margin-right:14px"><span style="width:8px;height:8px;border-radius:50%;background:#7F77DD"></span>แก้ทับแล้ว (override)</span>ข้อมูลที่แก้เก็บแยกสำหรับประกันเท่านั้น · ชื่อ/สัญชาติหลักใน Booking ไม่เปลี่ยน · &#8634; = คืนค่าจาก Booking</div>
  </div>`;
}
/* §insRoute · rid ว่าง = ทุกเส้นทาง (คนละแผ่น) · ใส่ rid = พิมพ์เฉพาะเส้นทางนั้น */
function insPrint(rid){
  const e=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ds=_insDate; const dt=new Date(ds+'T00:00:00');
  const dateLbl=isNaN(dt)?ds:dt.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  let trips=insTripsForDate(ds);
  if(rid) trips=trips.filter(g=>String(g.routeId)===String(rid));
  if(!trips.length && rid){ alert('ไม่พบเส้นทางนี้ในวันที่เลือก'); return; }
  let body='';
  trips.forEach(g=>{
    g.bookings.sort((a,b)=>String(a.id||'').localeCompare(String(b.id||'')));
    let rows=''; let i=0;
    g.bookings.forEach(b=>{ insBkPax(b).forEach(p=>{ const sn=insSplitName(p.name); i++;
      const fn=insEff(b.id,p.key,'firstName',sn.f); const ln=insEff(b.id,p.key,'lastName',sn.l);
      const age=insEff(b.id,p.key,'age',''); const nat=insEff(b.id,p.key,'nat',insNatLabel(p.natCode));
      rows+=`<tr><td class="c">${i}</td><td>${e(fn)}</td><td>${e(ln)}</td><td class="c">${e(age)||'-'}</td><td>${e(nat)||'-'}</td></tr>`; }); });
    /* §insRoute · หนึ่งเส้นทาง = หนึ่งแผ่น · หัวใบซ้ำทุกแผ่น เพราะแต่ละแผ่นถูกยื่นแยกกัน
       ยอดคนต่อท้ายตาราง · คนรับประกันนับหัวจากตรงนี้ ไม่ต้องไล่นับบรรทัด */
    body+=`<section class="rt"><h1>Passenger list for insurance</h1>`
      +`<div class="meta">Operation LOVE Andaman · ${e(dateLbl)}</div>`
      +`<h2>${e(insRouteName(g.routeId))}</h2>`
      +`<table><thead><tr><th class="c">#</th><th>First name</th><th>Last name</th><th class="c">Age</th><th>Nationality</th></tr></thead>`
      +`<tbody>${rows}</tbody></table>`
      +`<div class="tot">รวม ${i} ท่าน · ${g.bookings.length} booking</div></section>`;
  });
  if(!body) body='<h1>Passenger list for insurance</h1><p>No trips on this date.</p>';
  const ttl='Insurance · '+(rid?(insRouteName(rid)+' · '):'')+dateLbl;
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${e(ttl)}</title><style>`
   +`body{font-family:Arial,Helvetica,sans-serif;color:#111;margin:24px}`
   +`h1{font-size:18px;margin:0 0 4px}`
   +`h2{font-size:14px;margin:14px 0 6px;border-bottom:2px solid #185FA5;padding-bottom:3px}`
   +`.meta{font-size:12px;color:#555;margin-bottom:6px}`
   +`table{width:100%;border-collapse:collapse;margin-bottom:6px}`
   +`th,td{border:1px solid #bbb;padding:5px 8px;font-size:12px;text-align:left}`
   +`th{background:#eef3f8}.c{text-align:center}`
   +`.tot{font-size:12px;font-weight:700;color:#1B2A55}`
   +`.rt+.rt{margin-top:26px;border-top:1px dashed #bbb;padding-top:18px}`
   /* หัวตารางซ้ำเมื่อเส้นทางเดียวยาวเกินหน้า · แถวไม่ถูกผ่ากลาง */
   +`@media print{@page{size:A4;margin:14mm}`
     +`.rt+.rt{break-before:page;page-break-before:always;margin-top:0;border-top:0;padding-top:0}`
     +`thead{display:table-header-group}tr{break-inside:avoid;page-break-inside:avoid}}`
   +`</style></head><body>${body}</body></html>`;
  const w=window.open('','_blank'); if(!w){ alert('Popup blocked'); return; } w.document.write(html); w.document.close(); w.focus(); setTimeout(()=>{ try{w.print();}catch(e){} }, 300);
}
// ── FOC Detail (own sidebar view) ──
function renderFocDetail(){
  const host=document.getElementById('foc-host'); if(!host) return;
  const SALES=(typeof SB_SALES!=='undefined')?SB_SALES:[];
  const BK=(typeof SB_BOOKINGS!=='undefined')?SB_BOOKINGS:[];
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const isCancel=b=>b.status==='cancelled'||b.status==='cancelled_weather';
  const paxOf=b=>(b.trips||[]).reduce((s,t)=>s+((typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0),0);
  const valOf=b=>(typeof acctBookingTotal==='function')?acctBookingTotal(b):(b.total||0);
  const invOf=b=>(typeof acctBookingInvoice==='function')?acctBookingInvoice(b.id):null;
  const fK=n=>{ n=Math.round(n||0); return n>=1e6?'฿'+(n/1e6).toFixed(2)+'M':n>=1e3?'฿'+Math.round(n/1e3)+'k':'฿'+n; };
  const pf=(n,d)=>d>0?Math.round(n/d*1000)/10:0;
  const sName=s=>esc((s.name||'').replace(/^Khun\s+/,''));
  if(!BK.length){ host.innerHTML='<div class="md-card" style="color:#888">No bookings yet.</div>'; return; }
  const FAM_ORDER=['similan','surin','phiphi','krabi','whaleshark']; const famHdr={similan:'Similan',surin:'Surin',phiphi:'Phi Phi',krabi:'Krabi',whaleshark:'Whale'}; const famCol={similan:'#185fa5',surin:'#3B6D11',phiphi:'#c0392b',krabi:'#0F6E56',whaleshark:'#BA7517'};
  const A={};
  BK.forEach(b=>{ if(b.status==='rejected')return; const a=sbGetAgent(b.agentId); if(!a)return; const o=(A[a.id]=A[a.id]||{a,val:0,pax:0,cancel:0,tot:0,paid:0,ar:0,fam:{},area:{}}); o.tot++; if(isCancel(b)){o.cancel++;return;} o.val+=valOf(b); o.pax+=paxOf(b);
    const aid=b.pickupAreaId||'';   // configured pickup area (Phuket Town, Patong, …) · booking-level
    (b.trips||[]).forEach(t=>{ const px=(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0; const f=bkV2RouteFamily(t.routeId); if(f) o.fam[f.id]=(o.fam[f.id]||0)+px; const k=aid||('_z'+String(t.zone||b.pickupZone||'NT').toUpperCase()); o.area[k]=(o.area[k]||0)+px; });
    const iv=invOf(b); if(iv){o.paid+=Math.max(0,acctInvoicePaid(iv)); o.ar+=acctInvoiceBalance(iv);} });
  const focDetailHtml=(function(){
    const focChip=st=> st==='approved'?'<span style="font-size:8px;font-weight:700;color:#0F6E56;background:#E1F5EE;border-radius:4px;padding:1px 5px;margin-left:5px;vertical-align:1px">approved</span>':(st==='pending'?'<span style="font-size:8px;font-weight:700;color:#854F0B;background:#FAEEDA;border-radius:4px;padding:1px 5px;margin-left:5px;vertical-align:1px">pending</span>':'');
    const focAg={};
    BK.forEach(b=>{ if(b.status==='rejected'||isCancel(b))return;
      const a=sbGetAgent(b.agentId); const sp=SALES.find(s=>s.id===(a&&a.sales));
      const reason=((b.focApproval&&b.focApproval.reason)||b.focReason||'').trim();
      const st=(b.focApproval&&b.focApproval.status)||(b.status==='pending_foc'||b.status==='pending'?'pending':'');
      const key=b.agentId||('b2c:'+(b.b2cChannel||'walk-in'));
      (b.trips||[]).forEach(t=>{ const f=(typeof bkV2PaxTot==='function')?bkV2PaxTot(t.pax,'foc'):0; if(f<=0)return;
        const date=t.date||''; const fam=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(t.routeId):null; const fid=fam?fam.id:'other';
        const g=focAg[key]=focAg[key]||{agentId:b.agentId, agentName:a?(a.name||a.code||a.id):(b.b2cChannel||'B2C / Walk-in'), fc:0, bks:{}, sps:{}, byDate:{}};
        g.fc+=f; g.bks[b.id]=1; if(sp) g.sps[sp.id]=sp;
        const D=g.byDate[date]=g.byDate[date]||{date,total:0,fam:{},reasons:{},anyPending:false,allApproved:true};
        D.total+=f; D.fam[fid]=(D.fam[fid]||0)+f;
        if(reason) D.reasons[reason]=(D.reasons[reason]||0)+1;
        if(st==='pending') D.anyPending=true;
        if(st!=='approved') D.allApproved=false;
      });
    });
    const focRecs=Object.values(focAg).sort((x,y)=>y.fc-x.fc);
    if(!focRecs.length) return '';
    const gFoc=focRecs.reduce((s,r)=>s+r.fc,0);
    const fmtFocD=ds=>{ if(!ds)return'—'; const dt=new Date(ds+'T00:00:00'); if(isNaN(dt))return ds; return dt.getDate()+'/'+(dt.getMonth()+1); };
    const isStaffRec=r=>{ const a=sbGetAgent(r.agentId); return !!(a&&(a.code==='STAFF'||a.id==='a_staff')); };
    const grpAgent=focRecs.filter(r=>!isStaffRec(r)), grpStaff=focRecs.filter(r=>isStaffRec(r));
    let pendingFoc=0,nPend=0; focRecs.forEach(r=>{ let rp=false; Object.values(r.byDate).forEach(D=>{ if(D.anyPending){pendingFoc+=D.total;rp=true;} }); if(rp)nPend++; });
    const agentFoc=grpAgent.reduce((s,r)=>s+r.fc,0), staffFoc=grpStaff.reduce((s,r)=>s+r.fc,0);
    const _GH='background:linear-gradient(150deg,#24513b,#163f2b) padding-box,linear-gradient(140deg,rgba(255,255,255,.55),rgba(255,255,255,.06) 42%,rgba(0,0,0,.2)) border-box;border:1.5px solid transparent;border-radius:16px;box-shadow:inset 0 1px 0 rgba(255,255,255,.28),0 12px 26px rgba(20,50,35,.18)';
    const _GT='background:linear-gradient(#fff,#fff) padding-box,linear-gradient(140deg,rgba(255,255,255,.98),rgba(255,255,255,.25) 38%,rgba(176,190,205,.6)) border-box;border:1.5px solid transparent;border-radius:16px;box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 10px 24px rgba(30,50,42,.07),0 1px 3px rgba(0,0,0,.045)';
    const _glL=(f)=>`background:linear-gradient(${f},${f}) padding-box,linear-gradient(140deg,rgba(255,255,255,.95),rgba(255,255,255,.28) 40%,rgba(176,190,205,.55)) border-box;border:1.5px solid transparent;box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 10px 26px rgba(30,50,42,.08),0 1px 3px rgba(0,0,0,.04)`;
    const _glHero='background:linear-gradient(#1F4D2C,#1F4D2C) padding-box,linear-gradient(140deg,rgba(255,255,255,.35),rgba(255,255,255,.05) 42%,rgba(0,0,0,.28)) border-box;border:1.5px solid transparent;box-shadow:inset 0 1px 0 rgba(255,255,255,.18),0 12px 28px rgba(15,45,30,.22)';
    const _glRed='background:linear-gradient(#FCECEC,#FCECEC) padding-box,linear-gradient(140deg,rgba(255,255,255,.9),rgba(244,180,178,.35) 42%,rgba(224,75,74,.5)) border-box;border:1.5px solid transparent;box-shadow:inset 0 1px 0 rgba(255,255,255,.8),0 10px 26px rgba(224,75,74,.13),0 1px 3px rgba(0,0,0,.04)';
    const famFoc={}; focRecs.forEach(r=>Object.values(r.byDate).forEach(D=>Object.keys(D.fam||{}).forEach(fid=>famFoc[fid]=(famFoc[fid]||0)+(D.fam[fid]||0))));
    const famPax={}; Object.values(A).forEach(o=>Object.keys(o.fam||{}).forEach(fid=>famPax[fid]=(famPax[fid]||0)+(o.fam[fid]||0)));
    const famVal={}; BK.forEach(b=>{ if(b.status==='rejected'||isCancel(b))return; const val=valOf(b); const tot=paxOf(b)||1; (b.trips||[]).forEach(t=>{ const f=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(t.routeId):null; const fid=f?f.id:'other'; const px=(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0; famVal[fid]=(famVal[fid]||0)+val*(px/tot); }); });
    const _FB={similan:'#5B9BD5',surin:'#9CCC65',phiphi:'#EF6C6C',krabi:'#4DB6AC',whaleshark:'#E0A93C',other:'#B0BEC5'};
    const _famChips=FAM_ORDER.concat(['other']).filter(fid=>famFoc[fid]).map(fid=>{ const bc=_FB[fid]||'#9BB89B'; const pct=famPax[fid]>0?Math.round(famFoc[fid]/famPax[fid]*100):0; const pay=famPax[fid]-famFoc[fid]; const focVal=pay>0?Math.round(famFoc[fid]*(famVal[fid]/pay)):0; return `<div style="background:rgba(255,255,255,.06);border-radius:10px;border-left:3px solid ${bc};padding:5px 10px 6px;min-width:66px"><div style="font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:.03em;color:#a8c1ad;white-space:nowrap">${fid==='other'?'อื่นๆ':(famHdr[fid]||fid)}</div><div style="display:flex;align-items:baseline;gap:5px;margin-top:1px"><span style="font-size:16px;font-weight:700;color:#fff;font-variant-numeric:tabular-nums;line-height:1">${famFoc[fid]}</span><span style="font-size:9px;font-weight:700;color:${bc};font-variant-numeric:tabular-nums" title="FOC ${famFoc[fid]} จาก ${famPax[fid]} pax">${pct}%</span></div><div style="font-size:9px;font-weight:700;color:${bc};font-variant-numeric:tabular-nums;margin-top:2px" title="มูลค่า FOC ที่แจกฟรี ≈ FOC × ราคาเฉลี่ย/หัวที่จ่ายจริง">≈${fK(focVal)}</div></div>`; }).join('');
    const _totFocVal=FAM_ORDER.concat(['other']).reduce((s,fid)=>{ if(!famFoc[fid])return s; const pay=famPax[fid]-famFoc[fid]; return s+(pay>0?famFoc[fid]*(famVal[fid]/pay):0); },0);
    const hero=`<div style="flex:1.5;min-width:160px;padding:14px 16px;background:#1F4D2C;border-radius:16px;display:flex;flex-direction:column;justify-content:flex-start;font-family:'DM Sans',sans-serif;${_glHero}"><div style="font-size:10px;color:#9BB89B;text-transform:uppercase;letter-spacing:.04em">FOC pax</div><div style="display:flex;align-items:baseline;gap:8px;margin-top:4px"><span style="font-size:30px;font-weight:700;line-height:1;letter-spacing:-1px;color:#fff">${gFoc}</span><span style="font-size:13px;color:#9BB89B">pax · ${focRecs.length} agents</span></div><div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap;align-items:center"><span style="background:#C8F47C;color:#1F4D2C;padding:2px 9px;border-radius:14px;font-size:10px;font-weight:600">Agent ${agentFoc} · Staff ${staffFoc}</span><span style="background:rgba(212,83,126,.14);border:1.5px solid #E07A9E;color:#F6C2D4;padding:2px 10px;border-radius:14px;font-size:10px;font-weight:700" title="มูลค่ารวมของ FOC ที่แจกฟรี (ประมาณ)">มูลค่า FOC ≈ ${fK(_totFocVal)}</span></div>${_famChips?`<div style="font-size:8.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:#7c9a82;margin:14px 0 6px">FOC ตามเส้นทาง</div><div style="display:flex;gap:6px;flex-wrap:wrap">${_famChips}</div>`:''}</div>`;
    const wtile=(big,lab,sub,numc,bg)=>`<div style="flex:1;min-width:128px;padding:14px 17px;background:${bg};border:1px solid rgba(0,0,0,.06);border-radius:16px;display:flex;flex-direction:column;justify-content:center"><div style="font-size:9.5px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:#6a7a70;margin-bottom:5px">${lab}</div><div style="font-size:26px;font-weight:800;font-variant-numeric:tabular-nums;color:${numc};line-height:1">${big}</div><div style="font-size:10.5px;color:#9aa49c;margin-top:5px">${sub}</div></div>`;
    const _agNG={}; BK.forEach(b=>{ if(b.status==='rejected'||isCancel(b))return; const a=sbGetAgent(b.agentId); if(a&&(a.code==='STAFF'||a.id==='a_staff'))return; const reason=((b.focApproval&&b.focApproval.reason)||b.focReason||'').trim(); if(/guide|ไกด์/i.test(reason))return; (b.trips||[]).forEach(t=>{ const f=(typeof bkV2PaxTot==='function')?bkV2PaxTot(t.pax,'foc'):0; if(f<=0)return; const key=b.agentId||('b2c:'+(b.b2cChannel||'walk-in')); const g=_agNG[key]=_agNG[key]||{name:a?(a.name||a.code||a.id):(b.b2cChannel||'B2C / Walk-in'), agentId:b.agentId, fc:0, reasons:{}}; g.fc+=f; if(reason)g.reasons[reason]=1; }); });
    const _agTotFoc={}; focRecs.forEach(r=>{ if(r.agentId)_agTotFoc[r.agentId]=r.fc; });
    const top5=Object.values(_agNG).filter(x=>x.fc>0).sort((a,b)=>b.fc-a.fc).slice(0,5).map(x=>({name:x.name, fc:x.fc, reason:Object.keys(x.reasons).join(', '), agentId:x.agentId}));
    const _VC='background:linear-gradient(#fff,#fff) padding-box,linear-gradient(150deg,rgba(255,255,255,.98),rgba(176,190,205,.55)) border-box;border:1.5px solid transparent;border-radius:12px;box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 4px 12px rgba(30,50,42,.06);padding:9px 7px 10px;display:flex;flex-direction:column;align-items:center;text-align:center;min-height:102px';
    const agentCards=top5.map((t,i)=>{ const o=A[t.agentId]; const tf=(_agTotFoc[t.agentId]!=null)?_agTotFoc[t.agentId]:t.fc; const px=o?(o.pax||0):tf; const kp=px>0?Math.round(tf/px*100):100; const kc=kp<=8?'#1D9E75':kp<=20?'#BA7517':'#E24B4A'; return `<div style="${_VC}"><span style="font-size:9px;font-weight:800;color:#3B6D11;background:rgba(99,153,34,.15);border-radius:6px;padding:1px 7px;align-self:flex-start">#${i+1}</span><div style="font-size:10.5px;font-weight:700;color:#26352e;margin-top:6px;line-height:1.2;min-height:24px;display:flex;align-items:center;justify-content:center;overflow:hidden">${esc(t.name)}</div><div style="font-size:23px;font-weight:800;font-variant-numeric:tabular-nums;color:#3B6D11;line-height:1;margin-top:2px">${t.fc}</div><div style="font-size:8px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:#9aa49c;margin-top:1px">FOC</div><div style="margin-top:5px"><span style="font-size:8.5px;font-weight:800;font-variant-numeric:tabular-nums;color:${kc};background:${kc}1f;border-radius:6px;padding:1px 7px" title="KPI = FOC ÷ ลูกค้าทั้งหมด (${tf}/${px})">KPI ${kp}%</span></div><div style="font-size:8.5px;color:#9aa49c;margin-top:5px;line-height:1.28;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden" title="${esc(t.reason||'')}">${t.reason?esc(t.reason):'—'}</div></div>`; }).join('');
    const agentDetail=`<div style="flex:2.5;min-width:330px;padding:13px 15px;${_glL('#EAF3DE')};border-radius:16px"><div style="display:flex;align-items:baseline;gap:9px;margin-bottom:10px;flex-wrap:wrap"><span style="font-size:25px;font-weight:800;font-variant-numeric:tabular-nums;color:#1F4D2C;line-height:1">${agentFoc}</span><span style="font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#3B6D11">Agent FOC</span><span style="font-size:9px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#7e8a6f;margin-left:6px">Top 5 ส่งเยอะสุด · ไม่รวม Guide</span><span style="font-size:10px;color:#8a9a80;margin-left:auto">${grpAgent.length} agents</span></div><div style="display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px">${agentCards}</div></div>`;
    const _staffInsp=[],_staffWel=[];
    BK.forEach(b=>{ if(b.status==='rejected'||isCancel(b))return; const a=sbGetAgent(b.agentId); if(!(a&&(a.code==='STAFF'||a.id==='a_staff')))return; const reason=((b.focApproval&&b.focApproval.reason)||b.focReason||'').trim(); const isInsp=/inspect|ตรวจ/i.test(reason); (b.trips||[]).forEach(t=>{ const f=(typeof bkV2PaxTot==='function')?bkV2PaxTot(t.pax,'foc'):0; if(f<=0)return; const fam=(typeof bkV2RouteFamily==='function')?bkV2RouteFamily(t.routeId):null; (isInsp?_staffInsp:_staffWel).push({date:t.date||'',fam:fam?fam.id:'other',fc:f,reason:reason||''}); }); });
    const _byDate=arr=>{ const m={}; arr.forEach(e=>{ const d=m[e.date]=m[e.date]||{date:e.date,fc:0,fams:{},reasons:{}}; d.fc+=e.fc; if(e.fam)d.fams[e.fam]=(d.fams[e.fam]||0)+e.fc; if(e.reason)d.reasons[e.reason]=1; }); return Object.values(m).sort((x,y)=>(x.date||'').localeCompare(y.date||'')); };
    const welCards=_byDate(_staffWel), inspCards=_byDate(_staffInsp);
    const welFc=_staffWel.reduce((s,e)=>s+e.fc,0), inspFc=_staffInsp.reduce((s,e)=>s+e.fc,0);
    const staffCard=(c,col)=>{ const fam=Object.keys(c.fams).sort((a,b)=>c.fams[b]-c.fams[a])[0]; const famNm=fam?(famHdr[fam]||fam):''; const rs=Object.keys(c.reasons).join(', '); return `<div style="${_VC};min-height:106px"><span style="font-size:9px;font-weight:800;color:#56627A;background:rgba(86,98,122,.1);border-radius:7px;padding:1px 8px;align-self:flex-start">${fmtFocD(c.date)}</span><div style="font-size:26px;font-weight:800;font-variant-numeric:tabular-nums;color:${col};line-height:1;margin-top:8px">${c.fc}</div><div style="font-size:8.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:#9aa49c;margin-top:2px">FOC${famNm?' · '+esc(famNm):''}</div><div style="font-size:9px;color:#9aa49c;margin-top:6px;line-height:1.3;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden" title="${esc(rs)}">${rs?esc(rs):'—'}</div></div>`; };
    const staffSection=(title,cards,fc,col)=>`<div style="margin-top:11px"><div style="font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:${col};margin-bottom:7px"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${col};margin-right:5px;vertical-align:1px"></span>${title} <span style="color:#9aa49c;font-weight:700">· ${fc} FOC</span></div>${cards.length?`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(94px,1fr));gap:8px">${cards.map(c=>staffCard(c,col)).join('')}</div>`:`<div style="font-size:10px;color:#bdbcb2;font-style:italic">—</div>`}</div>`;
    const _staffMC=(title,fc,nDays,col,bg)=>`<div style="background:${bg};border:1px solid ${col}33;border-radius:12px;padding:11px 11px 12px;display:flex;flex-direction:column;align-items:flex-start;justify-content:center"><div style="font-size:9px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:${col}"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${col};margin-right:5px;vertical-align:1px"></span>${title}</div><div style="font-size:26px;font-weight:800;font-variant-numeric:tabular-nums;color:${col};line-height:1;margin-top:8px">${fc}</div><div style="font-size:8.5px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#9aa49c;margin-top:3px">FOC · ${nDays} วัน</div></div>`;
    const staffDetail=`<div style="flex:1.6;min-width:215px;padding:13px 15px;${_glL('#fff')};border-radius:16px;display:flex;flex-direction:column"><div style="display:flex;align-items:baseline;gap:9px;margin-bottom:10px"><span style="font-size:25px;font-weight:800;font-variant-numeric:tabular-nums;color:#185FA5;line-height:1">${staffFoc}</span><span style="font-size:9.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#185FA5">Staff FOC</span><span style="font-size:10px;color:#9aa49c;margin-left:auto">${grpStaff.length} staff</span></div><div style="flex:1;display:grid;grid-template-columns:repeat(2,1fr);gap:8px">${_staffMC('Welfare',welFc,welCards.length,'#3B6D11','#F2F7EA')}${_staffMC('Inspection',inspFc,inspCards.length,'#854F0B','#FAF3E6')}</div></div>`;
    const kpiAgents=grpAgent.map(r=>{ const o=A[r.agentId]; const paid=o?Math.max(0,(o.pax||0)-r.fc):0; const tot=paid+r.fc; const focPct=tot>0?(r.fc/tot*100):100; const a=sbGetAgent(r.agentId); const sp=SALES.find(s=>s.id===(a&&a.sales)); return {name:r.agentName, fc:r.fc, paid, focPct, sale:sp?sName(sp):'', saleColor:sp?(sp.color||'#888'):'#caa9a7'}; }).sort((a,b)=> b.focPct-a.focPct || a.paid-b.paid).slice(0,5);
    const lowKpiRows=kpiAgents.map((t,i)=>`<div style="display:flex;align-items:center;gap:7px;padding:6px 0;${i?'border-top:1px solid rgba(163,45,45,.14)':''}"><div style="flex:1;min-width:0;display:flex;align-items:baseline;gap:7px;white-space:nowrap;overflow:hidden"><span style="font-size:11px;font-weight:700;color:#6e1717;overflow:hidden;text-overflow:ellipsis;flex-shrink:1">${esc(t.name)}</span><span style="font-size:8.5px;color:#b58886;flex:none"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${t.saleColor};margin-right:3px;vertical-align:0"></span>${t.sale||'ไม่มีเซลล์'}</span></div><span style="font-size:9px;color:#bb8684;white-space:nowrap">FOC ${t.fc} · ลค ${t.paid}</span><span style="font-size:10.5px;font-weight:800;font-variant-numeric:tabular-nums;color:#fff;background:#E24B4A;border-radius:6px;padding:1px 7px">${Math.round(t.focPct)}%</span></div>`).join('');
    const lowKpiCard=`<div style="flex:1.7;min-width:225px;padding:13px 15px;${_glRed};border-radius:16px;display:flex;flex-direction:column"><div style="display:flex;align-items:baseline;gap:8px;margin-bottom:6px"><span style="font-size:9.5px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#A32D2D"><span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:#E24B4A;margin-right:5px;vertical-align:1px"></span>KPI ต่ำ</span><span style="font-size:9px;color:#c08a88">FOC สูง · ลูกค้าน้อย</span><span style="font-size:10px;color:#c08a88;margin-left:auto">${kpiAgents.length} agent</span></div><div style="flex:1;display:flex;flex-direction:column;justify-content:center">${lowKpiRows||'<div style="font-size:10px;color:#c79a98;font-style:italic">—</div>'}</div></div>`;
    const kpis=`<div style="display:flex;gap:11px;flex-wrap:wrap;align-items:stretch;margin-bottom:13px">${hero}${agentDetail}${staffDetail}${lowKpiCard}</div>`;
    const thF=`font-size:9.5px;text-transform:uppercase;letter-spacing:.04em;color:var(--fd-ink-soft);font-weight:600;padding:0 6px 9px;border-bottom:1.5px solid #E5E2D8`;
    const kpiCol=p=> p<=8?['#0F6E56','#E1F5EE']:p<=20?['#854F0B','#FAEEDA']:['#A32D2D','#FCEBEB'];
    const renderRec=(r,ai)=>{
      const o=A[r.agentId]; const a=sbGetAgent(r.agentId); const mkt=a?(a.market||'—'):'—';
      const paidPax=o?Math.max(0,(o.pax||0)-r.fc):0;
      const bkN=Object.keys(r.bks).length;
      const sps=Object.values(r.sps);
      const anyPending=Object.values(r.byDate).some(D=>D.anyPending);
      const allApproved=Object.values(r.byDate).every(D=>D.allApproved);
      const chip=anyPending?focChip('pending'):(allApproved?focChip('approved'):'');
      const bkTag=bkN>1?` <span style="font-size:8.5px;color:#9a9a90;background:#f1f0ea;border-radius:5px;padding:1px 5px">${bkN} bk</span>`:'';
      const dates=Object.values(r.byDate).sort((x,y)=>(x.date||'').localeCompare(y.date||''));
      const zt=ai%2?'#FAFAF7':'#FFFFFF';
      const accent=(o&&o.val>0)?'#185FA5':'#D9C28A';
      const cellTop='border-top:1px solid #E7E5DD';
      const saleTxt=sps.length?sps.map(s=>`<span style="display:inline-flex;align-items:center;gap:4px;margin-right:8px"><span style="width:8px;height:8px;border-radius:50%;background:${s.color||'#888'}"></span><span style="font-size:11px;color:#5a5a52">${sName(s)}</span></span>`).join(''):'<span style="font-size:11px;color:#b7b7ad">—</span>';
      const tripLines=dates.map(D=>{
        const fams=FAM_ORDER.filter(fid=>D.fam[fid]);
        const chips=fams.map(fid=>{ const col=famCol[fid]||'#854F0B'; return `<span style="display:inline-flex;align-items:center;gap:5px;background:${col}1f;border-radius:7px;padding:2px 9px;margin-right:5px"><span style="font-size:11.5px;font-weight:700;color:${col}">${famHdr[fid]||fid}</span><span style="font-size:11.5px;font-weight:700;color:${col};font-variant-numeric:tabular-nums">${D.fam[fid]}</span></span>`; }).join('');
        const rk=Object.keys(D.reasons); const reasonTxt=rk.length?rk.map(esc).join(', '):'<span style="color:#c4c3ba;font-style:italic">—</span>';
        return `<div style="display:flex;align-items:center;gap:8px;padding:3px 0;flex-wrap:wrap"><span style="font-size:11px;font-weight:700;color:#56627A;min-width:36px;font-variant-numeric:tabular-nums">${fmtFocD(D.date)}</span>${chips}<span style="font-size:11px;color:#8a8a80">${reasonTxt}</span></div>`;
      }).join('');
      const kp=(r.fc+paidPax)>0?Math.round(r.fc/(r.fc+paidPax)*100):100; const kc=kpiCol(kp);
      const perf=`<div style="display:grid;grid-template-columns:1.5fr 1fr 1.15fr;background:#fff;border:1px solid #E7E5DD;border-radius:10px;overflow:hidden">`
        +`<div style="padding:7px 11px;display:flex;flex-direction:column;justify-content:center;gap:2px;background:${kc[1]}"><div style="display:flex;align-items:baseline;gap:6px"><span style="font-size:20px;font-weight:800;font-variant-numeric:tabular-nums;color:${kc[0]};line-height:1">${kp}%</span><span style="font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:${kc[0]}">FOC share</span></div><div style="height:6px;background:rgba(0,0,0,.07);border-radius:4px;overflow:hidden;margin-top:4px"><div style="width:${kp}%;height:100%;background:${kc[0]};border-radius:4px"></div></div></div>`
        +`<div style="padding:7px 8px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;border-left:1px solid #EEECE4"><span style="font-size:19px;font-weight:800;font-variant-numeric:tabular-nums;color:#1B2A55;line-height:1">${o?paidPax:'—'}</span><span style="font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#9aa49c">paying</span></div>`
        +`<div style="padding:7px 11px;display:flex;flex-direction:column;justify-content:center;align-items:flex-end;gap:1px;border-left:1px solid #EEECE4;background:#E9F6F0"><span style="font-size:19px;font-weight:800;font-variant-numeric:tabular-nums;color:#0F6E56;line-height:1">${o?fK(o.val):'—'}</span><span style="font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#0F6E56">value</span></div>`
        +`</div>`;
      return `<tr style="background:${zt}"><td style="${cellTop};vertical-align:middle;padding:10px 10px;border-left:3px solid ${accent}"><div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap"><span style="font-size:12.5px;font-weight:800;color:#1B2A55">${esc(r.agentName)}</span>${chip}${bkTag}</div><div style="display:flex;align-items:center;gap:8px;margin-top:5px;flex-wrap:wrap">${saleTxt}<span style="font-size:9px;font-weight:700;letter-spacing:.04em;background:#ECEEF2;color:#56627A;padding:2px 7px;border-radius:7px">${esc((mkt||'—').toUpperCase())}</span></div></td><td style="${cellTop};vertical-align:middle;padding:6px 10px">${tripLines}</td><td style="${cellTop};vertical-align:middle;text-align:center;border-left:1px solid #ECEAE2"><span style="display:inline-block;min-width:28px;padding:4px 11px;border-radius:9px;background:rgba(239,159,39,.22);color:#7A4A00;font-weight:800;font-variant-numeric:tabular-nums;font-size:14px">${r.fc}</span></td><td style="${cellTop};vertical-align:middle;padding:6px 10px 6px 8px">${perf}</td></tr>`;
    };
    let _focAi=0;
    const focSecHdr=(label,recs)=>{ const fc=recs.reduce((s,x)=>s+x.fc,0); return `<tr><td colspan="4" style="padding:9px 12px 7px;background:#F1EFE8;border-top:2px solid #DAD5C6;font-size:10.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:#6B6456">${esc(label)} <span style="font-weight:600;color:#9a9486;letter-spacing:.02em;text-transform:none">· ${recs.length} agent${recs.length===1?'':'s'} · ${fc} FOC</span></td></tr>`; };
    const focBody=[
      grpAgent.length?focSecHdr('Agent',grpAgent)+grpAgent.map(r=>renderRec(r,_focAi++)).join(''):'',
      grpStaff.length?focSecHdr('Staff',grpStaff)+grpStaff.map(r=>renderRec(r,_focAi++)).join(''):''
    ].join('');
    return `<div style="margin-top:14px;font-family:Manrope,-apple-system,system-ui,sans-serif;background:#fafbfb;border-radius:20px;padding:20px;border:1px solid rgba(0,0,0,.04)">
      <div style="font-size:15px;font-weight:800;margin-bottom:3px;display:flex;align-items:center;gap:8px;color:#26352e"><span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:#E0A23C"></span>FOC detail <span style="font-weight:500;color:#7d8c84;font-size:12px">· ที่นั่งฟรี แยกตามเอเจ้น · วันเดินทาง · โปรแกรม</span></div>
      <div style="font-size:11px;color:#97a59d;margin-bottom:14px;margin-left:17px">ใครได้ FOC · ทริปไหน · กี่คน · เหตุผล · เทียบกับลูกค้าที่จ่ายเงินจริง</div>
      ${kpis}
      <div style="overflow-x:auto;padding:12px 6px 6px;${_GT}"><table style="width:100%;border-collapse:collapse"><thead><tr style="background:rgba(250,249,245,.6)">
        <th style="${thF};text-align:left;padding-left:10px;width:230px">Agent</th><th style="${thF};text-align:left">Trips · program</th>
        <th style="${thF};text-align:center;border-left:1px solid #ECEAE2;width:74px">FOC</th>
        <th style="${thF};text-align:left;padding:0 10px 9px 8px;width:404px"><div style="display:grid;grid-template-columns:1.5fr 1fr 1.15fr;text-align:center;gap:0 6px"><span>KPI · FOC share</span><span>Paying</span><span style="text-align:right">Value</span></div></th>
      </tr></thead><tbody>${focBody}</tbody></table></div>
      <div style="font-size:10px;color:var(--fd-ink-soft);margin-top:8px">โปรแกรมแสดงเฉพาะทริปที่มี FOC · FOC = รวมต่อเอเจ้น · <b>FOC share = FOC ÷ (FOC + ลูกค้าจ่ายจริง) · Paying / Value = ลูกค้าที่จ่ายเงิน (ไม่รวม FOC) และยอดขาย</b></div>
    </div>`;
  })();
  host.innerHTML = `<div style="max-width:100%;margin:0 auto;padding:4px">${focDetailHtml||'<div class="md-card" style="color:#8a9088;text-align:center;padding:30px">ยังไม่มีข้อมูล FOC</div>'}</div>`;
}
