  rows.forEach(function(r){ (byRoute[r.routeId]=byRoute[r.routeId]||[]).push(r); (byAgent[r.d.key]=byAgent[r.d.key]||[]).push(r); totPax+=r.d.pax; });
  var agentKeys=Object.keys(byAgent), sentAgents=agentKeys.filter(function(k){ return byAgent[k].every(function(r){return _rcSent(r.bk);}); }).length;
  var dObj=new Date(date+'T00:00:00'), dLabel=dObj.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'});
  var TH='padding:7px 9px;text-align:left;font-weight:600;color:#5F5E5A;white-space:nowrap;border-bottom:1px solid #E8E6DF;background:#FAF9F6;font-size:10.5px;text-transform:uppercase;letter-spacing:.03em';
  var TD='padding:6px 9px;white-space:nowrap;border-bottom:1px solid #F2F0EA;font-size:11.5px;color:#2C2C2A;vertical-align:top';
  var MONO="font-variant-numeric:tabular-nums";
