    const full=(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0;
    const _pk = _ovnRet ? '' : (b.hotelName||b.pickup||b.pickupArea||'').trim();
    const O = (typeof bkOpsRead==='function') ? bkOpsRead(b, date) : (b.ops||{});   // this DAY's van
    // a "job" = one van on ONE program(route) that day → key by van~route so a van running 2 programs prints 2 separate job orders
