    <div style="position:absolute;inset:0;overflow:auto;background:#fff">${vanJobsOrderCss(true)}<div class="vjo" style="${vjTplVars(fvid)};padding:12px 24px 22px">${vanJobsOrderInner(date,fvid,frt,fleg,fgrp)}</div></div>
