var PCK_THEAD='<thead><tr>'
 +'<th style="width:11%">Voucher / Agency</th>'
 +'<th style="width:15%">ลูกค้า (lead) · โทร</th>'
 +'<th class="ck-c pck-px">AD</th><th class="ck-c pck-px">CHD</th><th class="ck-c pck-px">INF</th><th class="ck-c pck-px">FOC</th>'
 +'<th style="width:16%">เวลา / จุดรับ</th>'
