    if(r.money.due>0 && r.stage!=='on'){ cnt.stat.due++; tDue+=r.money.due; }
    if(r.stage!=='vd') tExpect+=r.expect;
    if(r.ck && r.ck.at) tNoShow+=(r.ck.noShow||0);
