let TRAVEL_SUM={};
(function(){ try{ const lsKey=(typeof LS_KEY!=='undefined'?LS_KEY:'loveandaman_v2'); const d=JSON.parse(localStorage.getItem(lsKey)||'{}'); if(d&&d.travel_sum&&typeof d.travel_sum==='object') TRAVEL_SUM=d.travel_sum; }catch(_){} })();
var _tsDate=(typeof bkV2LocalYMD==='function')?bkV2LocalYMD(new Date()):new Date().toISOString().slice(0,10);
// §tsCotSettle · คำตัดสินการจัดการ Cash on Tour
//   { mode:'full'|'part'|'none'|'payout', deduct, payout, ref, by, at }
let TS_COT={};
(function(){ try{ const lsKey=(typeof LS_KEY!=='undefined'?LS_KEY:'loveandaman_v2');
  const d=JSON.parse(localStorage.getItem(lsKey)||'{}');
  if(d && d.ts_cot && typeof d.ts_cot==='object') TS_COT=d.ts_cot; }catch(_){} })();
var _tsOnlyIssue=false;
// §tsRoute · แยกดูรายเส้นทาง · '' = ทุกเส้นทาง
var _tsRoute='';
var _tsVatF='';   // '' = ทั้งหมด · 'vat' = เฉพาะมี VAT · 'novat' = เฉพาะไม่มี VAT
