    var _lost=(typeof ckLostByType==='function')?ckLostByType(b,date):null;
    var _gone = r.cxlRow || r.travelled<=0 || (r.booked>0 && _lost && _lost.total>=r.booked);
    var noVan  = _gone || (r.vanDone  && (r.vanActual!=null)  && r.vanActual<=0)
