function renderTripPL(){
  var host=document.getElementById('trippl-host'); if(!host) return;
  var e=(typeof ckEsc==='function')?ckEsc:function(x){return String(x==null?'':x);};
  if(!_px.date) _px.date=(typeof bkV2LocalYMD==='function')?bkV2LocalYMD(new Date()):new Date().toISOString().slice(0,10);
  if(!_px.mon) _px.mon=String(_px.date).slice(0,7);
  if(!_px.an) _px.an=47;
  var body='';
  try{
    body=(_px.tab==='m')?pxMonth(e):((_px.tab==='a')?pxAnalysis(e):pxDaily(e));
  }catch(err){
    try{ console.error('[P&L] render failed', err); }catch(_){}
    body='<div class="empty">Could not build this view — '+e(String(err&&err.message||err))+'</div>';
  }
  host.innerHTML=pxBar(e)+body;   // styles: css/03-trippl.css (was pxCSS(), injected per render)
}

/* §mealTrip · ของจริงรายทริป · 'YYYY-MM-DD::boatId'
   คีย์เดียวกับ TRIPS / FL_DAILY / PIER_JOB · หน้า P&L จะอ่านจากที่นี่เป็นตัวทับค่าประมาณ
   เก็บเป็นจำนวนเงิน ไม่ใช่แค่ชื่อร้าน · ร้านขึ้นราคาทีหลังจะได้ไม่ย้อนไปแก้ทริปที่ผ่านมาแล้ว */
var TRIP_ACT = {};
(function(){ try{
  var K = (typeof LS_KEY !== 'undefined' ? LS_KEY : 'loveandaman_v2');
  var d = JSON.parse(localStorage.getItem(K) || '{}');
  if(d && d.trip_actuals && typeof d.trip_actuals === 'object') TRIP_ACT = d.trip_actuals;
}catch(_){} })();
function taKey(date, bid){ return String(date || '') + '::' + String(bid || ''); }
function taGet(date, bid){ return TRIP_ACT[taKey(date, bid)] || null; }
function taSet(date, bid, patch){
  var k = taKey(date, bid), cur = TRIP_ACT[k] || {};
  Object.keys(patch).forEach(function(f){ if(patch[f] == null) delete cur[f]; else cur[f] = patch[f]; });
  if(Object.keys(cur).length) TRIP_ACT[k] = cur; else delete TRIP_ACT[k];
  try{
    var d = (typeof laBlob === 'function') ? laBlob() : null;
    if(d){ d.trip_actuals = TRIP_ACT; if(typeof laBlobSave === 'function') laBlobSave(); }
  }catch(e){ console.warn('[trip] actuals persist failed', e); }
}

