function renderAccounting(){
  const host=document.getElementById('acct-body'); if(!host) return;
  const live=SB_INVOICES.filter(i=>i.status!=='void');
  const outstanding=live.reduce((s,i)=>s+acctInvoiceBalance(i),0);
  const ym=new Date().toISOString().slice(0,7);
  const paidMonth=SB_PAYMENTS.filter(p=>p.type==='payment'&&(p.date||'').slice(0,7)===ym).reduce((s,p)=>s+(p.amount||0),0);
  let exposure=0; (SB_AGENTS||[]).forEach(a=>{ exposure+=agCreditState(a.id).used; });
  const now=new Date(); const overdue=live.filter(i=>acctInvoiceBalance(i)>0 && i.dueAt && new Date(i.dueAt)<now).length;
  const kpi=(lab,val,col)=>`<div style="flex:1;min-width:150px;background:#fff;border:0.5px solid var(--fd-line-soft);border-radius:12px;padding:13px 15px"><div style="font-size:10.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em;font-weight:600">${lab}</div><div style="font-size:22px;font-weight:700;color:${col||'var(--fd-ink)'};font-variant-numeric:tabular-nums;margin-top:3px">${val}</div></div>`;
  const kpis=`<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px">
    ${kpi('Outstanding', acctFmt(outstanding), '#A05A1A')}
    ${kpi('Paid this month', acctFmt(paidMonth), '#0F6E56')}
    ${kpi('Credit exposure', acctFmt(exposure), '#185FA5')}
    ${kpi('Overdue invoices', String(overdue), overdue>0?'#A32D2D':'var(--fd-ink)')}
    ${kpi('Deposits held', acctFmt(acctDepositHeldTotal()), '#5B289A')}
    ${kpi('Extras · cash · mo', acctFmt(acctExtrasMonthTotal()), '#0F6E56')}
  </div>`;
  const _allInv=SB_INVOICES.slice().sort((a,b)=>(b.issuedAt||'').localeCompare(a.issuedAt||''));
  const _voidCount=_allInv.filter(i=>i.status==='void').length;
  const _shownInv = _acctShowVoid ? _allInv : _allInv.filter(i=>i.status!=='void');
  const rows=_shownInv.map(inv=>{
    const a=sbGetAgent(inv.agentId); const st=acctInvoiceState(inv); const bal=acctInvoiceBalance(inv); const paid=acctInvoicePaid(inv);
    return `<tr style="border-top:0.5px solid var(--fd-line-soft);${st==='void'?'opacity:.5':''}">
      <td style="padding:9px 10px;font-size:11.5px;font-family:'DM Mono',monospace;font-weight:600">${inv.number}</td>
      <td style="padding:9px 10px;font-size:12px">${a?`<span onclick="acctStatementOpen('${a.id}')" style="cursor:pointer;color:#185FA5;text-decoration:underline">${a.name}</span>`:(inv.agentId||'—')}</td>
      <td style="padding:9px 10px;font-size:11px;color:var(--fd-ink-soft)">${(inv.bookingIds||[]).length} booking</td>
      <td style="padding:9px 10px;text-align:right;font-size:12px;font-variant-numeric:tabular-nums">${acctFmt(inv.total)}</td>
      <td style="padding:9px 10px;text-align:right;font-size:12px;font-variant-numeric:tabular-nums;color:#0F6E56">${acctFmt(paid)}</td>
      <td style="padding:9px 10px;text-align:right;font-size:12px;font-variant-numeric:tabular-nums;color:${bal>0?'#A05A1A':'var(--fd-ink-soft)'}">${acctFmt(bal)}</td>
      <td style="padding:9px 10px">${acctStateChip(st)}</td>
      <td style="padding:9px 10px;text-align:right;white-space:nowrap">
        ${`<button onclick="acctOpenDoc('${inv.id}','invoice')" style="background:#fff;border:1px solid var(--fd-line);color:var(--fd-ink);font-family:inherit;font-size:10.5px;padding:5px 11px;border-radius:7px;cursor:pointer;margin-right:5px">View</button>`}
        ${(st!=='paid'&&st!=='void')?`<button onclick="acctPayOpen('${inv.id}')" style="background:var(--fd-coral);color:#fff;border:none;font-family:inherit;font-size:10.5px;font-weight:600;padding:5px 11px;border-radius:7px;cursor:pointer">Record payment</button>`:''}
        ${st!=='void'?`<button onclick="acctVoidConfirm('${inv.id}')" title="Void invoice" style="background:#fff;border:1px solid var(--fd-line);color:var(--fd-ink-soft);font-family:inherit;font-size:10.5px;padding:5px 9px;border-radius:7px;cursor:pointer;margin-left:5px">Void</button>`:''}
      </td>
    </tr>`;
  }).join('');
  const table=`<div style="background:#fff;border:0.5px solid var(--fd-line-soft);border-radius:12px;overflow:hidden">
    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 15px;border-bottom:0.5px solid var(--fd-line-soft)">
      <div style="font-size:13px;font-weight:600;display:flex;align-items:center;gap:10px">Invoices <span style="color:var(--fd-ink-soft);font-weight:400">· ${_shownInv.length}</span>${_voidCount>0?`<button onclick="acctToggleVoid()" style="background:#fff;border:1px solid var(--fd-line);color:var(--fd-ink-soft);font-family:inherit;font-size:10.5px;font-weight:600;padding:4px 10px;border-radius:7px;cursor:pointer">${_acctShowVoid?`ซ่อนใบที่ยกเลิก`:`ดูใบที่ยกเลิก (${_voidCount})`}</button>`:''}</div>
      <button onclick="acctDepositOpen('')" style="background:#fff;border:1px solid #D9C7EE;color:#5B289A;font-family:inherit;font-size:12px;font-weight:600;padding:8px 14px;border-radius:9px;cursor:pointer;margin-right:8px">+ รับมัดจำ</button><button onclick="acctNewInvoiceOpen()" style="background:var(--fd-coral);color:#fff;border:none;font-family:inherit;font-size:12px;font-weight:600;padding:8px 15px;border-radius:9px;cursor:pointer">+ New invoice</button>
    </div>
    ${_shownInv.length? `<table style="width:100%;border-collapse:collapse"><thead><tr style="background:#fafaf8">
      <th style="padding:8px 10px;text-align:left;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Invoice</th>
      <th style="padding:8px 10px;text-align:left;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Agent</th>
      <th style="padding:8px 10px;text-align:left;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Items</th>
      <th style="padding:8px 10px;text-align:right;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Total</th>
      <th style="padding:8px 10px;text-align:right;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Paid</th>
      <th style="padding:8px 10px;text-align:right;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Balance</th>
      <th style="padding:8px 10px;text-align:left;font-size:9.5px;color:var(--fd-ink-soft);text-transform:uppercase;letter-spacing:.05em">Status</th>
      <th></th></tr></thead><tbody>${rows}</tbody></table>`
    : `<div style="padding:30px;text-align:center;color:var(--fd-ink-soft);font-size:12px">${_voidCount>0&&!_acctShowVoid?`ไม่มีใบแจ้งหนี้ที่ใช้งานอยู่ · มี ${_voidCount} ใบที่ยกเลิก (กด "ดูใบที่ยกเลิก" ด้านบน)`:'ยังไม่มีใบแจ้งหนี้ — กด "+ New invoice" เพื่อออกจาก booking'}</div>`}
  </div>`;
  host.innerHTML=kpis+acctDashboardHtml()+table;
}

