(function(){ try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); if(Array.isArray(d.sb_nationalities)) SB_CUSTOM_NATIONALITIES = d.sb_nationalities; }catch(e){ console.warn('load sb_nationalities failed', e); } })();
function sbNationalitiesPersist(){ try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); d.sb_nationalities=SB_CUSTOM_NATIONALITIES; localStorage.setItem(LS_KEY, JSON.stringify(d)); }catch(e){ console.warn('persist sb_nationalities failed', e); } }
// One-time idempotent purge: strip junk custom nationalities with <2 letters (e.g. a stray "Q" that
// was auto-added before manual-add was introduced) and clear those codes off any bookings.
(function(){
  try{
    if(!Array.isArray(SB_CUSTOM_NATIONALITIES) || !SB_CUSTOM_NATIONALITIES.length) return;
    const bad = new Set();
    const keep = SB_CUSTOM_NATIONALITIES.filter(n=>{
      const letters = String(n&&n.name||'').replace(/[^A-Za-z฀-๿]/g,'');
      if(letters.length < 2){ bad.add(n.code); return false; }
      return true;
    });
    if(!bad.size) return;
    SB_CUSTOM_NATIONALITIES.length=0; keep.forEach(n=>SB_CUSTOM_NATIONALITIES.push(n));
    sbNationalitiesPersist();
    let changed=0;
    if(typeof SB_BOOKINGS!=='undefined' && Array.isArray(SB_BOOKINGS)){
      SB_BOOKINGS.forEach(b=>{
        if(b && bad.has(b.leadNationality)){ b.leadNationality=''; changed++; }
        if(b && Array.isArray(b.passengers)) b.passengers.forEach(p=>{ if(p && bad.has(p.nationality)) p.nationality=''; });
      });
      if(changed){ if(typeof acctPersistBookings==='function') acctPersistBookings(); else if(typeof sbBookingsPersist==='function') sbBookingsPersist(); }
    }
    console.log('Purged junk nationality codes:', [...bad].join(','), '· bookings cleared:', changed);
  }catch(e){ console.warn('nat purge failed', e); }
})();
// One-time dedupe/normalize of malformed custom nationalities (e.g. "Barbados)" + "Barbados · BAR" → one "Barbados") · remaps affected bookings
