// ════════ Document Check (sidebar · verify B2B/agent bookings against attached documents) ════════
const _docCheck = { date: (typeof TODAY_STR!=='undefined'?TODAY_STR:new Date().toISOString().slice(0,10)), filter:'all', openId:null };
const DOCCHK_ITEMS = [ {k:'route',label:'เส้นทาง / โปรแกรม'},{k:'date',label:'วันเดินทาง'},{k:'lead',label:'ชื่อ'},{k:'pax',label:'จำนวนคน'},{k:'voucher',label:'Voucher / Ref'},{k:'payment',label:'Payment'} ];

// ─────────────────────────────────────────────────────────────────────────────
// §Doc-Check Pre-Check (OCR auto-compare) · reads the attached image with
// Tesseract.js then fuzzy-matches each of the 6 checklist fields against the
// system booking. Auto-ticks high-confidence matches; the user still does the
// final ✅/⚠ decision. Result cached on bk.docCheck.pre (never re-OCRs on reopen).
// ─────────────────────────────────────────────────────────────────────────────
const _docPre = { running:{}, prog:0, activeId:null };
// Lazy-load the OCR library (network needed · only on first Pre-Check).
function _docOcrEnsureLib(){
  if(window.Tesseract) return Promise.resolve();
  if(window._docOcrLibP) return window._docOcrLibP;
  window._docOcrLibP = new Promise(function(res,rej){
    var s=document.createElement('script');
    s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
    s.onload=function(){ res(); };
    s.onerror=function(){ window._docOcrLibP=null; rej(new Error('OCR library load failed (no network?)')); };
    document.head.appendChild(s);
  });
  return window._docOcrLibP;
}
// One shared worker (eng) reused across bookings.
function _docOcrGetWorker(){
  if(window._docOcrWorker) return Promise.resolve(window._docOcrWorker);
  if(window._docOcrWorkerP) return window._docOcrWorkerP;
  window._docOcrWorkerP = _docOcrEnsureLib().then(function(){
    return window.Tesseract.createWorker('eng', 1, {
      logger:function(m){ if(m&&m.status==='recognizing text'){ _docPre.prog=m.progress||0; _docPreThrottleRender(); } }
    });
  }).then(function(w){ window._docOcrWorker=w; return w; });
  return window._docOcrWorkerP;
}
var _docPreRenderT=null;
// Surgical: update ONLY the #dc-prebar element during OCR (keeps the drawer's document
// scroll position — no full re-render, no image reflow). Falls back to full render.
function _docPreThrottleRender(){ if(_docPreRenderT) return; _docPreRenderT=setTimeout(function(){ _docPreRenderT=null;
  var id=_docPre.activeId, bar=document.getElementById('dc-prebar');
  if(id && _docCheck.openId===id && bar){ var b=SB_BOOKINGS.find(function(x){return x.id===id;}); if(b){ bar.innerHTML=_docPreBarHTML(b, id); return; } }
  if(_docCheck.openId) renderDocCheck();
},380); }
// Build just the Pre-Check bar (self-contained · used by the drawer + surgical progress updates).
function _docPreBarHTML(b, bkId){
  var e=function(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];}); };
  var dc=b.docCheck||{}, _pre=dc.pre||null, files=(b.attachments||[]);
  var _running=!!_docPre.running[bkId], _hasImg=files.some(function(a){return /^image\//.test(a.mime||'');});
  if(_running){ return `<div style="background:#EAF3FB;border:1px solid #BFDCF2;border-radius:9px;padding:9px 11px;margin-bottom:9px;font-size:12px;color:#185FA5;font-weight:600;display:flex;align-items:center;gap:8px"><span style="display:inline-block;width:14px;height:14px;border:2px solid #BFDCF2;border-top-color:#185FA5;border-radius:50%;animation:docspin .8s linear infinite"></span>กำลังอ่านเอกสารด้วย OCR… ${Math.round((_docPre.prog||0)*100)}%</div>`; }
  if(_pre&&_pre.error){ return `<div style="background:#FBE7E5;border:1px solid #E7B3AE;border-radius:9px;padding:9px 11px;margin-bottom:9px;font-size:12px;color:#B5271F"><b>Pre-Check ไม่สำเร็จ:</b> ${e(_pre.error)} <button onclick="docCheckRunPre('${e(bkId)}')" style="margin-left:6px;background:#fff;border:1px solid #E7B3AE;border-radius:7px;padding:3px 9px;font-size:11px;font-weight:700;color:#B5271F;cursor:pointer;font-family:inherit">ลองใหม่</button></div>`; }
  if(_pre&&_pre.summary){ var s=_pre.summary; return `<div style="background:#F0F7F3;border:1px solid #CFE7DA;border-radius:9px;padding:9px 11px;margin-bottom:9px"><div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap"><span style="font-size:12px;color:#0F6E56;font-weight:700">⚡ Pre-Check (OCR): ตรง ${s.match} · อาจตรง ${s.maybe} · ไม่ตรง ${s.mismatch} · ไม่พบ ${s.none}</span><button onclick="docCheckRunPre('${e(bkId)}')" style="background:#fff;border:1px solid #CFE7DA;border-radius:7px;padding:3px 10px;font-size:11px;font-weight:700;color:#0F6E56;cursor:pointer;font-family:inherit">🔄 ตรวจใหม่</button></div><div style="font-size:10.5px;color:#6b7280;margin-top:4px">ระบบติ๊กช่องที่ตรงให้อัตโนมัติ — โปรดตรวจขั้นสุดท้ายก่อนกด ✅${_pre.autoTick===false?' · (โหมดดูอย่างเดียว: ไม่ติ๊กให้)':''}</div></div>`; }
  if(_hasImg){ return `<div style="margin-bottom:9px"><button onclick="docCheckRunPre('${e(bkId)}')" style="width:100%;background:#0F6E56;color:#fff;border:none;border-radius:9px;padding:9px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:inherit">⚡ Pre-Check ด้วย OCR (เทียบเอกสารอัตโนมัติ)</button></div>`; }
  if(files.length){ return `<div style="background:#F1F2EF;border:1px solid #e3e6e1;border-radius:9px;padding:8px 11px;margin-bottom:9px;font-size:11.5px;color:#8a8a82">Pre-Check รองรับเฉพาะเอกสารรูปภาพ (PDF ต้องตรวจมือ)</div>`; }
  return '';
}

// Run OCR + match for one booking (async · re-renders when done).
function docCheckRunPre(bkId){
  var b=SB_BOOKINGS.find(function(x){return x.id===bkId;}); if(!b) return;
  var imgs=(b.attachments||[]).filter(function(a){return /^image\//.test(a.mime||'');});
  if(!imgs.length){ alert('Pre-Check supports image attachments only (PDF must be checked manually).'); return; }
  if(_docPre.running[bkId]) return;
  _docPre.running[bkId]=true; _docPre.prog=0; _docPre.activeId=bkId;
  renderDocCheck();
  _docOcrGetWorker().then(function(worker){
    var chain=Promise.resolve('');
    imgs.forEach(function(a){ chain=chain.then(function(acc){
      return worker.recognize('/api/attach/'+encodeURIComponent(a.id)).then(function(r){
        return acc+'\n'+((r&&r.data&&r.data.text)||'');
      });
    }); });
    return chain;
  }).then(function(text){
    var results=_docPreCheckMatch(b, text);
    var summary={match:0,maybe:0,mismatch:0,none:0};
    DOCCHK_ITEMS.forEach(function(it){ var s=(results[it.k]||{}).s||'none'; summary[s]=(summary[s]||0)+1; });
    b.docCheck=b.docCheck||{status:'pending',items:{}};
    b.docCheck.items=b.docCheck.items||{};
    var canWrite = !(typeof window.laCanEditArea==='function') || window.laCanEditArea('operations');
    if(canWrite){ DOCCHK_ITEMS.forEach(function(it){ if(results[it.k]&&results[it.k].s==='match') b.docCheck.items[it.k]=true; }); }
    b.docCheck.pre={ at:new Date().toISOString(), lang:'eng', autoTick:canWrite, results:results, summary:summary, text:String(text||'').slice(0,3000) };
    if(canWrite) _docCheckPersist();
  }).catch(function(err){
    b.docCheck=b.docCheck||{items:{}};
    b.docCheck.pre={ at:new Date().toISOString(), error:(err&&err.message)||'OCR failed' };
  }).then(function(){
    _docPre.running[bkId]=false; _docPre.activeId=null; renderDocCheck();
  });
}

// ── Matcher · returns {key:{s:'match'|'maybe'|'mismatch'|'none', ev, detail}} ──
function _docPreCheckMatch(b, ocrText){
  var rName=function(id){ var r=(typeof getRoute==='function'?getRoute(id):null)||{}; return r.name||id||''; };
  var norm=function(s){ return String(s||'').toLowerCase().replace(/\s+/g,' ').trim(); };
  var alnum=function(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,''); };
  var ocrN=norm(ocrText), ocrA=alnum(ocrText);
  // system side
  var trips=(b.trips||[]);
  var chkT = trips.find(function(t){return (t.date||'')===_docCheck.date;}) || trips[0] || {};
  var paxSys = (typeof bkV2PaxAllTot==='function') ? bkV2PaxAllTot(chkT.pax||{}) : 0;
  var ag=(typeof sbGetAgent==='function'?sbGetAgent(b.agentId):null);
  var out={};

  // voucher / ref
  (function(){ var v=alnum(b.voucherRef||b.code||b.id); if(v.length<4){ out.voucher={s:'none'}; return; }
    if(ocrA.indexOf(v)>=0){ out.voucher={s:'match', ev:(b.voucherRef||b.code||b.id)}; return; }
    var tail=v.slice(-8); if(tail.length>=6 && ocrA.indexOf(tail)>=0){ out.voucher={s:'maybe', ev:'…'+tail}; return; }
    out.voucher={s:'none'};
  })();

  // date (any trip date found in the doc)
  (function(){ var months=['january','february','march','april','may','june','july','august','september','october','november','december'];
    var cands=[];
    trips.forEach(function(t){ var iso=(t.date||''); var mm=iso.match(/^(\d{4})-(\d{2})-(\d{2})$/); if(!mm) return;
      var Y=+mm[1], M=+mm[2], D=+mm[3], mon=months[M-1], mon3=mon.slice(0,3);
      var d=String(D), dd=mm[3], mo=mm[2];
      cands.push(iso, d+' '+mon+' '+Y, dd+' '+mon+' '+Y, d+' '+mon3+' '+Y, dd+' '+mon3+' '+Y,
        mon+' '+d+' '+Y, mon3+' '+d+' '+Y, mon+' '+d, mon3+' '+d,
        dd+'/'+mo+'/'+Y, d+'/'+M+'/'+Y, mo+'/'+dd+'/'+Y, M+'/'+d+'/'+Y, dd+'.'+mo+'.'+Y);
    });
    var hit=cands.find(function(c){ return c && ocrN.indexOf(norm(c))>=0; });
    out.date = hit ? {s:'match', ev:hit} : {s:'none'};
  })();

  // lead name (token-based · order-independent)
  (function(){ var toks=norm(b.leadPax).split(' ').filter(function(t){return t.length>=2;});
    if(!toks.length){ out.lead={s:'none'}; return; }
    var hit=toks.filter(function(t){return ocrN.indexOf(t)>=0;});
    if(hit.length===toks.length) out.lead={s:'match', ev:b.leadPax};
    else if(hit.length>0) out.lead={s:'maybe', ev:hit.join(' ')+' (บางส่วน)'};
    else out.lead={s:'none'};
  })();

  // §ocr · pax · เทียบรายประเภท ไม่ใช่แค่ยอดรวม
  //   เอกสาร "3 Adults & 1 child" กับ ระบบ "4 AD" รวมได้ 4 เท่ากันทั้งคู่
  //   ของเดิมจะขึ้น "✓ ตรง" แล้วคนตรวจติ๊กผ่าน ทั้งที่ราคาสองแบบนี้ไม่เท่ากัน
  (function(){ var num=function(re){ var m=ocrN.match(re); return m?parseInt(m[1],10):null; };
    var sysB=(typeof ckPaxBreak==='function')?ckPaxBreak(chkT.pax||{}):{ad:paxSys,chd:0,inf:0,foc:0};
    var who=function(o){ return [['ad','AD'],['chd','CHD'],['inf','INF'],['foc','FOC']]
        .filter(function(k){ return (+o[k[0]]||0)>0; })
        .map(function(k){ return (+o[k[0]])+' '+k[1]; }).join(' · ') || '0'; };
    var sysTxt='ระบบ '+who(sysB)+' = '+paxSys+' pax';
    var ad=num(/(\d+)\s*adult/), ch=num(/(\d+)\s*child/)||num(/(\d+)\s*children/), inf=num(/(\d+)\s*infant/);
    var docTot=null, docB=null, evTxt='';
    if(ad!=null){ docB={ad:ad,chd:ch||0,inf:inf||0,foc:0}; docTot=ad+(ch||0)+(inf||0); evTxt=who(docB)+' = '+docTot+' pax'; }
    else { var px=num(/(\d+)\s*(?:pax|persons?|people|pers\b|ท่าน|คน)/); if(px!=null){ docTot=px; evTxt=px+' pax'; } }
    if(docTot==null){ out.pax={s:'none', detail:sysTxt}; return; }
    if(docTot!==paxSys){ out.pax={s:'mismatch', detail:'เอกสาร '+evTxt+' · '+sysTxt}; return; }
    // ยอดรวมตรงแล้ว · เทียบรายประเภทต่อ เฉพาะตอนที่เอกสารแยกประเภทมาให้
    // FOC รวมเข้าฝั่งผู้ใหญ่ เพราะเอกสารเอเยนต์ไม่เคยแยก FOC ออกมา
    if(docB){
      var sysAd=(+sysB.ad||0)+(+sysB.foc||0);
      if(docB.ad!==sysAd || docB.chd!==(+sysB.chd||0) || docB.inf!==(+sysB.inf||0)){
        out.pax={s:'mismatch', detail:'ยอดรวมตรง แต่ประเภทไม่ตรง · เอกสาร '+evTxt+' · '+sysTxt};
        return;
      }
    }
    out.pax={s:'match', ev:evTxt};
  })();

  // route / program (keyword score)
  (function(){ var stop={by:1,the:1,and:1,'of':1,to:1,a:1,an:1,trip:1,day:1,tour:1,tours:1,program:1,'&':1,daytrip:1};
    var kws=[]; trips.forEach(function(t){ norm(rName(t.routeId)).split(/[^a-z0-9]+/).forEach(function(w){ if(w.length>=3 && !stop[w] && kws.indexOf(w)<0) kws.push(w); }); });
    if(!kws.length){ out.route={s:'none'}; return; }
    var hit=kws.filter(function(w){ return ocrN.indexOf(w)>=0 || ocrA.indexOf(w)>=0; });
    var score=hit.length/kws.length;
    if(score>=0.5) out.route={s:'match', ev:hit.join(' · ')};
    else if(score>0) out.route={s:'maybe', ev:hit.join(' · ')+' (บางส่วน)'};
    else out.route={s:'none'};
  })();

  /* §dcCot · เงินที่ต้องเก็บหน้างาน · ลืมแล้วเก็บไม่ได้อีกเลย
     เทียบยอดในเอกสารกับยอดในระบบ · ฝั่งไหนมีแต่อีกฝั่งไม่มี ก็ต้องเตือน */
  (function(){
    var sys=(b.cashOnTour && +b.cashOnTour.amount>0) ? Math.round(+b.cashOnTour.amount) : 0;
    var doc=null;
    var mm=ocrN.match(/cash[\s\-]*on[\s\-]*(?:tour|board)\D{0,24}?([\d][\d,\.]*)/);
    if(!mm) mm=ocrN.match(/([\d][\d,\.]*)\s*(?:thb|baht|บาท)\D{0,24}?cash[\s\-]*on[\s\-]*(?:tour|board)/);
    if(mm){ var nRaw=String(mm[1]).replace(/,/g,'').replace(/\.00$/,''); var nv=parseFloat(nRaw); if(isFinite(nv)) doc=Math.round(nv); }
    if(doc==null && !sys){ out.cot={s:'none'}; return; }
    if(doc==null){ out.cot={s:'none', detail:'ระบบ '+sys.toLocaleString()+' · ไม่พบในเอกสาร'}; return; }
    if(!sys){ out.cot={s:'mismatch', detail:'เอกสารมี '+doc.toLocaleString()+' แต่ระบบยังไม่ได้ใส่'}; return; }
    if(doc!==sys){ out.cot={s:'mismatch', detail:'เอกสาร '+doc.toLocaleString()+' · ระบบ '+sys.toLocaleString()}; return; }
    out.cot={s:'match', ev:doc.toLocaleString()};
  })();

  // payment terms
  (function(){ var pt=ag&&ag.payType; var kw={ invoice:['invoice','credit'], proforma:['pro forma','proforma','pro-forma'], cot:['cash on tour','cash-on-tour','cash on board','pay on tour'] }[pt]||[];
    if(!kw.length){ out.payment={s:'none'}; return; }
    var hit=kw.find(function(k){ return ocrN.indexOf(k)>=0; });
    out.payment = hit ? {s:'match', ev:hit} : {s:'none'};
  })();

  return out;
}

function _docIsB2B(b){ return !!(b && b.schemaVer===2 && b.agentId); }   // B2B/agent bookings only
function docCheckStatus(bk){ const dc=bk&&bk.docCheck; if(dc&&dc.status) return dc.status; const n=((bk&&bk.attachments)||[]).length; return n?'pending':'nofiles'; }
function _docBadge(st){ if(st==='verified') return {t:'✅ ตรวจแล้ว',bg:'#E6F5EA',c:'#1B7F4B'}; if(st==='issue') return {t:'⚠ มีปัญหา',bg:'#FCEBEB',c:'#B5271F'}; if(st==='pending') return {t:'⏳ รอตรวจ',bg:'#FFF6E0',c:'#8A5B00'}; return {t:'📄 ยังไม่แนบ',bg:'#F0F0EC',c:'#8a8a82'}; }
function _docCheckPersist(){ try{ acctPersistBookings(); }catch(e){ try{ const k=(typeof LS_KEY!=='undefined'?LS_KEY:'loveandaman_v2'); const o=JSON.parse(localStorage.getItem(k)||'{}'); o.sb_bookings=SB_BOOKINGS; localStorage.setItem(k,JSON.stringify(o)); }catch(_){} } }
function docCheckSetDate(shift){ const d=new Date(_docCheck.date+'T12:00:00'); d.setDate(d.getDate()+shift); _docCheck.date=d.toISOString().slice(0,10); _docCheck.calOpen=false; renderDocCheck(); }
function docCheckToday(){ _docCheck.date=(typeof TODAY_STR!=='undefined'?TODAY_STR:new Date().toISOString().slice(0,10)); _docCheck.calOpen=false; renderDocCheck(); }
function docCheckToggleCal(){ _docCheck.calOpen=!_docCheck.calOpen; if(_docCheck.calOpen) _docCheck.calMonth=_docCheck.date.slice(0,7); renderDocCheck(); }
function docCheckCalShift(n){ const m=_docCheck.calMonth||_docCheck.date.slice(0,7); const d=new Date(+m.slice(0,4),+m.slice(5,7)-1+n,1); _docCheck.calMonth=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); renderDocCheck(); }
function docCheckPickDate(ds){ _docCheck.date=ds; _docCheck.calOpen=false; renderDocCheck(); }
function _docCheckCalHTML(e){
  const m=_docCheck.calMonth||_docCheck.date.slice(0,7); const yy=+m.slice(0,4), mm=+m.slice(5,7);
  const first=new Date(yy,mm-1,1); const startDow=(first.getDay()+6)%7; const dim=new Date(yy,mm,0).getDate();
  const monLbl=first.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
  const today=(typeof TODAY_STR!=='undefined'?TODAY_STR:new Date().toISOString().slice(0,10));
  let cells=''; for(let i=0;i<startDow;i++) cells+='<div></div>';
  for(let d=1;d<=dim;d++){ const ds=yy+'-'+String(mm).padStart(2,'0')+'-'+String(d).padStart(2,'0'); const sel=ds===_docCheck.date; const isT=ds===today;
    cells+=`<div onclick="docCheckPickDate('${ds}')" style="text-align:center;font-size:11px;padding:5px 0;border-radius:6px;cursor:pointer;${sel?'background:#1B2A55;color:#fff;font-weight:700':(isT?'background:#EAF3FB;color:#185FA5;font-weight:700':'color:#3F4654')}">${d}</div>`; }
  return `<div onclick="event.stopPropagation()" style="position:absolute;right:0;top:48px;background:#fff;border:1px solid #e3e6e1;border-radius:14px;box-shadow:0 14px 40px rgba(0,0,0,.18);padding:12px;z-index:20;width:252px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><button onclick="docCheckCalShift(-1)" style="border:none;background:transparent;cursor:pointer;font-size:16px;color:#888">&lsaquo;</button><span style="font-size:13px;font-weight:700">${monLbl}</span><button onclick="docCheckCalShift(1)" style="border:none;background:transparent;cursor:pointer;font-size:16px;color:#888">&rsaquo;</button></div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;font-size:10px;color:#9aa0aa;text-align:center;margin-bottom:3px"><div>M</div><div>T</div><div>W</div><div>T</div><div>F</div><div>S</div><div>S</div></div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px">${cells}</div>
  </div>`;
}
function docCheckSetFilter(f){ _docCheck.filter=f; renderDocCheck(); }
function docCheckOpen(bkId){ _docCheck.openId=bkId; renderDocCheck(); }
function docCheckClose(){ _docCheck.openId=null; renderDocCheck(); }
function docCheckToggleItem(bkId,k){ if(typeof window.laGuardEdit==='function' && !window.laGuardEdit('operations')) return; const bk=SB_BOOKINGS.find(b=>b.id===bkId); if(!bk) return; bk.docCheck=bk.docCheck||{status:'pending',items:{}}; bk.docCheck.items=bk.docCheck.items||{}; bk.docCheck.items[k]=!bk.docCheck.items[k]; _docCheckPersist(); renderDocCheck(); }
function docCheckSetStatus(bkId,status){ if(typeof window.laGuardEdit==='function' && !window.laGuardEdit('operations')) return; const bk=SB_BOOKINGS.find(b=>b.id===bkId); if(!bk) return; bk.docCheck=bk.docCheck||{items:{}}; bk.docCheck.status=status; bk.docCheck.by=(typeof laBy==='function'?laBy():'') ; bk.docCheck.at=new Date().toISOString(); _docCheckPersist(); if(typeof bkV2AddHistory==='function') bkV2AddHistory(bk,'edit','Document check · '+(status==='verified'?'✅ verified':status==='issue'?'⚠ issue':status)+((bk.docCheck.note)?(' · '+bk.docCheck.note):''),'DocCheck'); renderDocCheck(); }
function docCheckSetNote(bkId,val){ const bk=SB_BOOKINGS.find(b=>b.id===bkId); if(!bk) return; bk.docCheck=bk.docCheck||{items:{}}; bk.docCheck.note=val; _docCheckPersist(); }   // no re-render (keep focus)
function _docCheckList(date){ const out=[]; (SB_BOOKINGS||[]).forEach(b=>{ if(!_docIsB2B(b)) return; if(b.status==='rejected') return; const t=(b.trips||[]).find(tt=>(tt.date||'')===date); if(!t) return; out.push({bk:b,trip:t}); }); return out; }   // cancelled kept (shown · linked to booking) · rescheduled follow their trip.date automatically
// Ordered as displayed: grouped by route (program), voucher within · honours the status filter
function _docCheckOrdered(date){ const rN=id=>((typeof getRoute==='function'?getRoute(id):null)||{}).name||id; let rows=_docCheckList(date); if(_docCheck.filter!=='all') rows=rows.filter(r=>docCheckStatus(r.bk)===_docCheck.filter); rows.sort((a,b)=>{ const ra=rN(a.trip.routeId), rb=rN(b.trip.routeId); if(ra!==rb) return ra<rb?-1:1; return String(a.bk.voucherRef||a.bk.id).localeCompare(String(b.bk.voucherRef||b.bk.id)); }); return rows; }
// Search box · DOM-filter (no re-render → keeps focus) · hides route headers whose group is empty
function docCheckFilterRows(){ const host=document.getElementById('doccheck-host'); if(!host) return; const q=String(_docCheck.search||'').trim().toLowerCase(); const gv={}; host.querySelectorAll('tr[data-drow]').forEach(tr=>{ const txt=tr.getAttribute('data-drow')||''; const g=tr.getAttribute('data-drg')||''; const show=!q||txt.indexOf(q)>=0; tr.style.display=show?'':'none'; if(show)gv[g]=true; }); host.querySelectorAll('tr[data-dghdr]').forEach(h=>{ const g=h.getAttribute('data-dghdr')||''; h.style.display=gv[g]?'':'none'; }); }
// Drawer Next / Previous · step through the displayed order without closing
function docCheckNav(dir){ const ids=_docCheckOrdered(_docCheck.date).map(r=>r.bk.id); const i=ids.indexOf(_docCheck.openId); if(i<0) return; const ni=i+dir; if(ni<0||ni>=ids.length) return; _docCheck.openId=ids[ni]; renderDocCheck(); }

// ══════════════════════════════════════════════════════════════════════════════
// §Doc Check · A4 print pack — ONE voucher = ONE page. Every scan of that voucher
// stays on that same page (layout adapts to the file count). Missing docs still
// get a page so nothing silently falls off the checklist.
// ══════════════════════════════════════════════════════════════════════════════
// §docPack (2026-08-03) · แยกตัวสร้างหน้ากระดาษ "ชุดเอกสารตรวจ" ออกมา
//   เดิมฝังอยู่ใน docCheckPrintPack ที่เดียว · Travel Summary เลยเอาไปต่อท้ายไม่ได้
//   ตอนนี้ทั้งสองหน้าเรียกตัวเดียวกัน หน้ากระดาษจึงหน้าตาเหมือนกันเป๊ะเสมอ
function _docPackEsc(x){ return String(x==null?'':x).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); }
var _DOCPACK_PIER = {tublamu:'Tub Lamu Pier', panwa:'Visit Panwa'};
// หนึ่ง voucher = หนึ่งหน้า · สแกนทุกใบของ voucher นั้นอยู่หน้าเดียวกัน
function _docPackPage(r, i, total, seq, date, kicker){
  var e=_docPackEsc, b=r.bk, t=r.trip;
  var R=((typeof getRoute==='function'?getRoute(t.routeId):null)||{});
  var ag=((typeof sbGetAgent==='function'?sbGetAgent(b.agentId):null)||{});
  var pax=(typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0;
  var files=(b.attachments||[]), n=files.length;
  var pick=String(b.hotelName||b.pickup||'').trim();
  var pickHtml=pick?e(pick):'<span class="warn">&#9888; ยังไม่มีที่รับ</span>';
  var grid=(n<=1)?'one':(n===2)?'two':(n<=4)?'four':'many';
  var body;
  if(!n){
    body='<div class="miss"><div class="mi">&#9888;</div><b>ยังไม่ได้แนบเอกสาร</b><span>'+pax+' pax &middot; ต้องการ '+pax+' ไฟล์</span></div>';
  } else {
    body='<div class="grid '+grid+'">'+files.map(function(f,k){
      var url='/api/attach/'+encodeURIComponent(f.id);
      var isImg=/^image\//.test(f.mime||'');
      var isPdf=/pdf/i.test(f.mime||'') || /\.pdf$/i.test(f.name||'');
      // §mark · PDF วาดเป็นภาพจริงตอนเปิดหน้าต่างพิมพ์ (ดู _docPackBoot)
      var box=isImg?('<img src="'+url+'" alt="">')
             :isPdf?('<canvas class="pdfc" data-pdf="'+url+'"></canvas>'
                    +'<div class="pdfw">&#128196; '+e(f.name||'file')+' &middot; กำลังเปิดไฟล์ PDF…</div>')
                   :('<div class="nf"><div class="mi">&#128196;</div><span>'+e(f.name||'file')+'</span></div>');
      return '<figure><div class="sc">'+box+'</div><figcaption>'+(k+1)+'/'+n+' &middot; '+e(f.name||'')+'</figcaption></figure>';
    }).join('')+'</div>';
    if(n<pax) body+='<div class="short">&#9888; '+pax+' pax แต่แนบมา '+n+' ไฟล์ — ขาดเอกสาร '+(pax-n)+' คน</div>';
  }
  return '<section class="pg">'
    + '<header><span>LOVE Andaman &middot; '+e(kicker||'ชุดเอกสารตรวจ')+' &middot; '+e(date)+'</span><span>หน้า '+(i+1)+' / '+total+'</span></header>'
    + '<div class="trip">ทริป &middot; '+e(R.name||t.routeId)+(R.pier?(' &middot; '+e(_DOCPACK_PIER[R.pier]||R.pier)):'')
    +   (t.ovnLeg?(' &middot; \u21a9 OVN ขากลับ'
          +(function(){ var o=(typeof _ovnOutDate==='function')?_ovnOutDate(b,t):''; return o?(' \u00b7 ไปเมื่อ '+e((typeof ovnDayTh==='function')?ovnDayTh(o):o)):''; })()):'')
    +   '</div>'
    + '<div class="bk"><div class="r1"><b>#'+seq+' &middot; '+e(b.leadPax||'—')+'</b><span>'+pax+' pax</span></div>'
    +   '<div class="r2">'+e(ag.name||b.agentId||'')+(b.voucherRef?(' &middot; '+e(b.voucherRef)):'')+' &middot; รับที่ '+pickHtml+'</div></div>'
    + '<div class="body">'+body+'</div>'
    + '<footer><span>&#9744; ตรวจแล้ว &nbsp;&nbsp; &#9744; เอกสารครบ</span><span>ผู้ตรวจ ________________</span></footer>'
    + '</section>';
}
function _docPackPages(list, date, kicker){
  var html='', lastRoute=null, seq=0, total=list.length;
  list.forEach(function(r,i){
    var R=((typeof getRoute==='function'?getRoute(r.trip.routeId):null)||{});
    if(R.id!==lastRoute){ lastRoute=R.id; seq=0; }
    seq++;
    html+=_docPackPage(r, i, total, seq, date, kicker);
  });
  return html;
}
// S = ตัวนำหน้า selector · ''  = เอกสารเดี่ยว (หน้าตรวจเอกสาร)
//                          '.la-docpack' = เอาไปแปะต่อท้ายเอกสารอื่น (Travel Summary)
function _docPackCSS(S){
  var p=S?(S+' '):'';
  return (S?'':'*{box-sizing:border-box}')
   + (S?(S+'{box-sizing:border-box}'+S+' *{box-sizing:border-box}')
       :'body{margin:0;font-family:"DM Sans",-apple-system,system-ui,sans-serif;color:#1f2a24;-webkit-print-color-adjust:exact;print-color-adjust:exact}')
   + (S?(S+'{font-family:"DM Sans",-apple-system,system-ui,sans-serif;color:#1f2a24}'):'')
   + p+'.pg{width:192mm;height:279mm;display:flex;flex-direction:column;page-break-after:always}'
   + p+'.pg:last-child{page-break-after:auto}'
   + p+'.pg > header{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #1f2a24;padding-bottom:3mm;font-size:8pt;color:#6b736e}'
   + p+'.trip{background:#eef2f0;border-left:3px solid #0F6E56;padding:2mm 3mm;margin-top:3mm;font-size:9pt;font-weight:600}'
   + p+'.bk{margin-top:2.5mm;font-size:9pt}'+p+'.bk .r1{display:flex;justify-content:space-between;font-size:11pt}'+p+'.bk .r2{color:#6b736e;margin-top:1mm}'
   + p+'.warn{color:#A32D2D;font-weight:600}'
   + p+'.body{flex:1;margin-top:3mm;min-height:0;display:flex;flex-direction:column}'
   + p+'.grid{flex:1;display:grid;gap:3mm;min-height:0}'
   + p+'.grid.one{grid-template-columns:1fr}'
   + p+'.grid.two{grid-template-columns:1fr;grid-template-rows:1fr 1fr}'
   + p+'.grid.four{grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr}'
   + p+'.grid.many{grid-template-columns:1fr 1fr 1fr;grid-auto-rows:1fr}'
   + p+'figure{margin:0;display:flex;flex-direction:column;min-height:0}'
   + p+'.sc{flex:1;border:1px solid #cfd6d2;border-radius:1mm;background:#f4f2ec;display:flex;align-items:center;justify-content:center;overflow:hidden;min-height:0}'
   + p+'.sc img{max-width:100%;max-height:100%;object-fit:contain}'
   + p+'.sc canvas.pdfc{max-width:100%;max-height:100%;object-fit:contain;display:none}'
   + p+'.sc canvas.pdfc.on{display:block}'
   + p+'.pdfw{position:absolute;font-size:8pt;color:#8a938d;text-align:center;padding:3mm}'
   + p+'.pdfw.err{color:#A32D2D;font-weight:600}'
   + p+'.sc{position:relative}'
   + p+'.nf{display:flex;flex-direction:column;align-items:center;gap:2mm;color:#8a938d;font-size:8pt;padding:3mm;text-align:center}'
   + p+'.mi{font-size:20pt}'
   + p+'figcaption{font-size:7.5pt;color:#6b736e;text-align:center;padding-top:1mm}'
   + p+'.miss{flex:1;border:1px dashed #d99;border-radius:1mm;background:#fdf3f2;color:#A32D2D;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2mm;font-size:10pt}'
   + p+'.short{color:#A32D2D;font-size:8pt;text-align:center;padding-top:2mm}'
   + p+'.pg > footer{border-top:1px solid #d9d5cc;padding-top:2.5mm;margin-top:3mm;display:flex;justify-content:space-between;font-size:8pt;color:#6b736e}'
   + (S?(''):'@media screen{body{background:#e9e7e1;padding:8mm}.pg{background:#fff;box-shadow:0 2px 10px rgba(0,0,0,.15);margin:0 auto 6mm;padding:9mm}}');
}
// รอสแกนโหลดครบก่อนค่อยสั่งพิมพ์ · ไม่งั้นกระดาษออกมาเป็นกรอบเปล่า
function _docPackBoot(){ return ''; }   // §drive · ไม่ใช้แล้ว · ดู _docPackDrive
// โหลด pdf.js ครั้งเดียวที่หน้าหลัก · worker ต้องแปลงเป็น blob ก่อน
//   เพราะ new Worker() ข้ามโดเมนไม่ได้ · ถ้าดึงไม่ได้ก็ปล่อยให้ pdf.js ถอยเอง
var _docPdfP=null;
function _docPdfLib(){
  if(_docPdfP) return _docPdfP;
  _docPdfP = new Promise(function(res, rej){
    if(window.pdfjsLib) return res(window.pdfjsLib);
    var sc=document.createElement('script');
    sc.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
    sc.onerror=function(){ _docPdfP=null; rej(new Error('load')); };
    sc.onload=function(){ res(window.pdfjsLib); };
    document.head.appendChild(sc);
  }).then(function(lib){
    var wsrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    return fetch(wsrc).then(function(r){ return r.text(); }).then(function(t){
      lib.GlobalWorkerOptions.workerSrc=URL.createObjectURL(new Blob([t],{type:'application/javascript'}));
      return lib;
    }).catch(function(){ try{ lib.GlobalWorkerOptions.workerSrc=wsrc; }catch(_){} return lib; });
  });
  return _docPdfP;
}
// วาด PDF ลงหน้าต่างพิมพ์ → รอรูป → รอฟอนต์ → สั่งพิมพ์
function _docPackDrive(w){
  var doc;
  try{ doc = w.document; }catch(_){ return; }
  var printed=false;
  var finish=function(){
    if(printed) return; printed=true;
    var go=function(){
      var f=(doc.fonts&&doc.fonts.ready)?doc.fonts.ready:Promise.resolve();
      var p=function(){ setTimeout(function(){ try{ w.focus(); }catch(_){} try{ w.print(); }catch(_){} },250); };
      f.then(p, p);
    };
    var im=[].slice.call(doc.images), n=im.filter(function(x){ return !x.complete; }).length;
    if(!n) return go();
    im.forEach(function(x){ if(x.complete) return; x.onload=x.onerror=function(){ if(--n<=0) go(); }; });
  };
  var cvs=[].slice.call(doc.querySelectorAll('canvas.pdfc'));
  if(!cvs.length) return finish();
  var warn=function(c,msg){ var el=c.parentNode.querySelector('.pdfw');
    if(el){ el.className='pdfw err'; el.innerHTML='⚠ '+msg; } };
  // นาฬิกากันค้าง · ไม่ว่าอะไรจะเกิดขึ้น ภายใน 15 วิต้องเข้าหน้าพิมพ์
  var tmr=setTimeout(function(){
    cvs.forEach(function(c){ if(String(c.className).indexOf('on')<0) warn(c,'เปิดไฟล์ PDF ไม่ทัน · ต้องเปิดดูจากในระบบ'); });
    finish();
  }, 15000);
  _docPdfLib().then(function(lib){
    var left=cvs.length, done=function(){ if(--left<=0){ clearTimeout(tmr); finish(); } };
    cvs.forEach(function(c){
      var el=c.parentNode.querySelector('.pdfw');
      lib.getDocument(c.getAttribute('data-pdf')).promise.then(function(pdf){
        return pdf.getPage(1).then(function(pg){
          var vp=pg.getViewport({scale:2.2});   // 2.2x ให้ตัวหนังสือในเอกสารยังคมตอนพิมพ์
          c.width=vp.width; c.height=vp.height;
          return pg.render({canvasContext:c.getContext('2d'), viewport:vp}).promise.then(function(){
            c.className='pdfc on';
            if(el){
              if(pdf.numPages>1){ el.className='pdfw'; el.style.position='static'; el.style.paddingTop='1mm';
                el.innerHTML='หน้า 1 จาก '+pdf.numPages+' · หน้าอื่นเปิดดูจากในระบบ'; }
              else { el.parentNode.removeChild(el); }
            }
          });
        });
      }).catch(function(){ warn(c,'ไฟล์ PDF นี้เปิดไม่ได้ · ต้องเปิดดูจากในระบบ'); })
        .then(done, done);
    });
  }).catch(function(){
    clearTimeout(tmr);
    cvs.forEach(function(c){ warn(c,'เปิดตัวอ่าน PDF ไม่ได้ (ไม่มีเน็ต?) · ต้องเปิดดูจากในระบบ'); });
    finish();
  });
}
function docCheckPrintPack(opts){
  opts = opts || {};
  const date = _docCheck.date;
  let list = _docCheckOrdered(date);                       // already sorted: route → voucher
  if(opts.onlyIncomplete){
    list = list.filter(r => (r.bk.attachments||[]).length < bkV2PaxAllTot(r.trip.pax||{}));
  }
  if(!list.length){ alert('ไม่มีรายการตามเงื่อนไขที่เลือก'); return; }
  const html=_docPackPages(list, date, 'ชุดเอกสารตรวจ');
  const css='@page{size:A4;margin:9mm}'+_docPackCSS('');
  const w = window.open('','_blank');
  if(!w){ alert('เบราว์เซอร์บล็อกป๊อปอัป · อนุญาต pop-up แล้วลองใหม่'); return; }
  let fl=''; try{ [].slice.call(document.querySelectorAll('link[rel="stylesheet"],link[rel="preconnect"]')).forEach(function(L){
    var h=L.getAttribute('href')||''; if(/fonts\.(googleapis|gstatic)\.com/.test(h)) fl+=L.outerHTML; }); }catch(_){}
  w.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>ชุดเอกสาร '+_docPackEsc(date)+'</title>'+fl+'<style>'+css+'</style></head><body>'+html+'</body></html>');
  w.document.close();
  if(typeof _docPackDrive==='function') _docPackDrive(w);   // §drive
}

/* ══ Daily PFM · จัดการสลิปการชำระของบุ๊กกิ้ง — ดู · แนบเพิ่ม · ลบ ═══════════════
   เดิมหน้านี้เป็น "viewer" อย่างเดียว: เปิดดู/ดาวน์โหลดได้ แต่แนบผิดแล้วลบไม่ได้
   และปุ่มแนบมีอยู่ที่เดียวคือ Record modal ซึ่งโผล่เฉพาะตอน "ยังค้างจ่าย"
   → พอกดบันทึกการชำระไปแล้ว (หรือจ่ายครบ) จะแนบสลิปเพิ่มไม่ได้อีกเลย
   ฝั่ง backend รองรับอยู่แล้วทั้งหมด (POST/DELETE /api/attach รับทุก mime · paymentSlips
   เก็บเป็น json_text) — ที่ขาดคือ UI เท่านั้น                                        */
let _pfmSlipBk = null;   /* booking id ที่กำลังเปิดหน้าจัดการสลิปอยู่ */
/* วางรูปจากคลิปบอร์ดขณะเปิดหน้าจัดการสลิป (คนละตัวกับ listener ของ Record modal) */
document.addEventListener('paste', function(ev){
  try{
    if(!_pfmSlipBk || !document.getElementById('pfm-slipview')) return;
    const items=(ev.clipboardData && ev.clipboardData.items)||[];
    for(let i=0;i<items.length;i++){
      const it=items[i];
      if(it.type && it.type.indexOf('image')===0){ const f=it.getAsFile(); if(f){ ev.preventDefault(); pfmSlipsAttach(f,'paste'); } }
    }
  }catch(_){}
});


function renderDocCheck(){
  const host=document.getElementById('doccheck-host'); if(!host) return;
  // ── scroll-keep: remember where the user was reading so a re-render (cloud soft-refresh,
  //    filter, tick, OCR done) does NOT bounce the page/drawer to the top ──
  const _mn=document.querySelector('main'); const _scMn=_mn?_mn.scrollTop:0, _scW=window.scrollY||0;
  const _pL=document.getElementById('dc-panel-left'), _pR=document.getElementById('dc-panel-docs');
  const _scL=_pL?_pL.scrollTop:0, _scR=_pR?_pR.scrollTop:0;
  const _restoreScroll=()=>{ try{ if(_mn&&_scMn) _mn.scrollTop=_scMn; if(_scW) window.scrollTo(0,_scW);
    const l=document.getElementById('dc-panel-left'); if(l&&_scL) l.scrollTop=_scL;
    const r=document.getElementById('dc-panel-docs'); if(r&&_scR) r.scrollTop=_scR; }catch(_){} };
  const e=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]);
  const date=_docCheck.date;
  const allRows=_docCheckList(date);
  const cnt={all:allRows.length,pending:0,verified:0,issue:0,nofiles:0};
  allRows.forEach(r=>{ cnt[docCheckStatus(r.bk)]=(cnt[docCheckStatus(r.bk)]||0)+1; });
  const rows=_docCheckOrdered(date);
  let dlbl=date; try{ dlbl=new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}); }catch(_){}
  const rName=id=>((typeof getRoute==='function'?getRoute(id):null)||{}).name||id;
  const chip=(f,lbl,n,col)=>`<span onclick="docCheckSetFilter('${f}')" style="cursor:pointer;font-size:12px;padding:5px 12px;border-radius:16px;font-weight:600;${_docCheck.filter===f?'background:'+(col||'#1B2A55')+';color:#fff':'background:#fff;border:1px solid #dfe3e8;color:#5a6b62'}">${lbl} <b style="font-variant-numeric:tabular-nums">${n}</b></span>`;
  const th='padding:9px 11px;font-size:10px;color:#7a8088;font-weight:700;text-transform:uppercase;letter-spacing:.04em;text-align:left;border-bottom:1px solid #e6e8e3;white-space:nowrap';
  const thc=th+';text-align:center';
  const rc={}; rows.forEach(r=>{ const rn=rName(r.trip.routeId); rc[rn]=(rc[rn]||0)+1; });
  let prevR=null, body='';
  rows.forEach(r=>{
    const b=r.bk, t=r.trip; const ag=(typeof sbGetAgent==='function'?sbGetAgent(b.agentId):null); const rn=rName(t.routeId);
    const st=docCheckStatus(b); const bd=_docBadge(st); const nf=(b.attachments||[]).length;
    const cxl=['cancelled','cancelled_weather'].includes(b.status);
    const P=k=>(typeof bkV2PaxTot==='function'?bkV2PaxTot(t.pax||{},k):0);
    const tm=(b.ops&&b.ops.pickupTimeFinal)||t.pickupTime||b.pickupTime||'-';
    const zl=(typeof bkV2ZoneLabel==='function')?bkV2ZoneLabel(t.zone||b.pickupZone||''):(t.zone||b.pickupZone||'-');
    const sel=_docCheck.openId===b.id;
    const rowBg=sel?'#EAF3FB':(st==='verified'?'#E7F6EC':'');
    const _sr=e(((b.voucherRef||'')+' '+(b.code||'')+' '+(ag?ag.name:'')+' '+(b.leadPax||'')+' '+rn).toLowerCase());
    if(rn!==prevR){ prevR=rn; body+=`<tr data-dghdr="${e(rn)}"><td colspan="13" style="background:#EEF3F8;padding:9px 14px;border-top:2px solid #d3deea;border-bottom:1px solid #e3e9f0"><span style="font-size:13px;font-weight:700;color:#15396B">&#128676; ${e(rn)}</span> <span style="font-size:11px;color:#7a8696;font-weight:500">· ${rc[rn]} booking</span></td></tr>`; }
    const _agchip=ag?(function(){var _c=(typeof bkV2AgentColor==='function')?bkV2AgentColor(b.agentId):'#EAF3FB';var _i=(typeof bkV2ContrastInk==='function')?bkV2ContrastInk(_c):'#1B2A55';return `<span style="background:${_c};color:${_i};padding:5px 11px;border-radius:8px;font-size:12px;font-weight:600;display:inline-block;max-width:170px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${e(ag.name)}</span>`;})():'<span style="color:#3F4654">-</span>';
    const stCell=cxl?`<span style="font-size:11px;font-weight:700;background:#FBE3E1;color:#B5271F;padding:3px 10px;border-radius:9px;white-space:nowrap">✕ ยกเลิก</span>`:`<span style="font-size:11px;font-weight:700;background:${bd.bg};color:${bd.c};padding:3px 10px;border-radius:9px;white-space:nowrap">${bd.t}</span>`;
    body+=`<tr data-drow="${_sr}" data-drg="${e(rn)}" onclick="docCheckOpen('${e(b.id)}')" style="cursor:pointer;border-bottom:1px solid #eef0ec;${rowBg?'background:'+rowBg+';':''}${cxl?'opacity:.55;':''}">
      <td style="padding:9px 11px;font-size:12.5px;font-weight:600;color:#15396B${cxl?';text-decoration:line-through':''}">${st==='verified'?'✅ ':''}${e(b.voucherRef||b.code||b.id)}</td>
      <td style="padding:6px 11px">${_agchip}</td>
      <td style="padding:9px 11px;font-size:12.5px;color:#1B2A55;font-weight:600">${e(b.leadPax||'-')}</td>
      <td style="padding:9px 6px;text-align:center;font-size:12.5px;font-weight:700;color:#15396B">${P('ad')||'·'}</td>
      <td style="padding:9px 6px;text-align:center;font-size:12.5px;color:#5a6b62">${P('chd')||'·'}</td>
      <td style="padding:9px 6px;text-align:center;font-size:12.5px;color:#5a6b62">${P('inf')||'·'}</td>
      <td style="padding:9px 6px;text-align:center;font-size:12.5px;color:#5a6b62">${P('foc')||'·'}</td>
      <td style="padding:9px 11px;font-size:12px;color:#3F4654;max-width:210px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${e(b.hotelName||b.pickupArea||'-')}</td>
      <td style="padding:9px 11px;text-align:center;font-size:12px;color:#5a6b62">${e(b.roomNumber||'-')}</td>
      <td style="padding:9px 11px;font-size:12px;color:#5a6b62;white-space:nowrap">${e(zl)}</td>
      <td style="padding:9px 11px;text-align:center;font-size:12px;color:${nf?'#185FA5':'#c00'}">📎 ${nf}</td>
      <td style="padding:9px 11px">${stCell}</td>
      <td style="padding:9px 11px;text-align:right"><button onclick="event.stopPropagation();docCheckOpen('${e(b.id)}')" style="background:#0F6E56;color:#fff;border:none;border-radius:7px;padding:5px 13px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">ตรวจ</button></td>
    </tr>`;
  });
  const rowHtml = rows.length ? body : `<tr><td colspan="13" style="padding:40px;text-align:center;color:#b7bcc2;font-size:13px">ไม่มี booking B2B ที่ต้องตรวจในวันนี้</td></tr>`;
  const table=`<div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:12px;overflow:hidden;overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;min-width:1040px">
      <thead><tr style="background:#F4F7F5"><th style="${th}">Voucher</th><th style="${th}">Agency</th><th style="${th}">Customer</th><th style="${thc}">AD</th><th style="${thc}">CHD</th><th style="${thc}">INF</th><th style="${thc}">FOC</th><th style="${th}">Pickup</th><th style="${thc}">Room</th><th style="${th}">Zone</th><th style="${thc}">ไฟล์</th><th style="${th}">สถานะ</th><th style="${th}"></th></tr></thead>
      <tbody>${rowHtml}</tbody>
    </table></div>`;
  const header=`<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px;flex-wrap:wrap">
    <div><div style="font-size:22px;font-weight:700;color:#1A1A1A">📑 ตรวจเอกสาร · Document Check <span style="font-size:11px;font-weight:600;color:#185FA5;background:#EAF3FB;padding:3px 10px;border-radius:12px;vertical-align:middle">B2B / Agent</span></div>
      <div style="display:flex;gap:8px;margin-top:11px;flex-wrap:wrap">${chip('all','ทั้งหมด',cnt.all)}${chip('pending','⏳ รอตรวจ',cnt.pending||0,'#8A5B00')}${chip('verified','✅ ตรวจแล้ว',cnt.verified||0,'#1B7F4B')}${chip('issue','⚠ มีปัญหา',cnt.issue||0,'#B5271F')}${chip('nofiles','ยังไม่แนบ',cnt.nofiles||0,'#8a8a82')}</div>
      <div style="margin-top:10px"><input id="docSearch" value="${e(_docCheck.search||'')}" oninput="_docCheck.search=this.value;docCheckFilterRows()" placeholder="&#128269; ค้นหา voucher / agent / ลูกค้า / เส้นทาง" style="width:380px;max-width:62vw;border:1px solid #d7dbe2;border-radius:18px;padding:7px 15px;font-size:12.5px;font-family:inherit"></div></div>
    <div style="position:relative">
      <div style="display:flex;gap:6px;justify-content:flex-end;margin-bottom:8px">
        <button onclick="docCheckPrintPack()" title="พิมพ์ชุดเอกสาร A4 · 1 voucher = 1 หน้า" style="background:#163d2b;color:#eafbe0;border:none;border-radius:9px;padding:8px 13px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit">🖨 พิมพ์ชุดเอกสาร A4</button>
        <button onclick="docCheckPrintPack({onlyIncomplete:true})" title="พิมพ์เฉพาะที่เอกสารยังไม่ครบ" style="background:#fff;border:1px solid #cfcabf;border-radius:9px;padding:8px 12px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;color:#3F4654">เฉพาะที่ยังไม่ครบ</button>
      </div>
      ${laDateBar(date,'docCheckSetDate','docCheckToday','docCheckToggleCal')}
      ${_docCheck.calOpen?_docCheckCalHTML(e):''}
    </div>
  </div>`;
  const drawer = _docCheck.openId ? _docCheckDrawer(_docCheck.openId, e, rName) : '';
  host.innerHTML = `<div>${header}${table}</div>${drawer}`;
  _restoreScroll(); requestAnimationFrame(_restoreScroll);   // keep reading position across re-render
  if(_docCheck.search) docCheckFilterRows();
  // Auto-run Pre-Check once when a booking with image attachments is opened (cached on bk.docCheck.pre).
  if(_docCheck.openId){ const _ob=SB_BOOKINGS.find(x=>x.id===_docCheck.openId);
    if(_ob && !(_ob.docCheck&&_ob.docCheck.pre) && !_docPre.running[_ob.id] && (_ob.attachments||[]).some(a=>/^image\//.test(a.mime||''))){
      setTimeout(()=>docCheckRunPre(_ob.id),120);
    }
  }
}
