  const _agc=(typeof bkV2AgentColor==='function')?bkV2AgentColor(b.agentId):'#EAF3FB'; const _agi=(typeof bkV2ContrastInk==='function')?bkV2ContrastInk(_agc):'#1B2A55';
  const sm=b.specialMeals||{}; const _diet=[]; if(+sm.veg)_diet.push('Veg '+sm.veg); if(+sm.vegan)_diet.push('Vegan '+sm.vegan); if(+sm.halal)_diet.push('Halal '+sm.halal); const _al=((typeof bkV2AllergyText==='function')?bkV2AllergyText(sm):'')||sm.allergies||''; if(_al)_diet.push('Allergy: '+_al); const dietStr=_diet.length?e(_diet.join(' · ')):'-';
