  const subrow=(l,v)=>`<div style="display:flex;gap:10px;margin-bottom:3px"><span style="flex:0 0 84px;font-size:10px;color:#8a8a82;text-transform:uppercase;letter-spacing:.03em;font-weight:600">${l}</span><span style="flex:1;font-size:13px;color:#1B2A55;font-weight:600">${v}</span></div>`;
