function renderTeamMkt(){
  // Sales list
  document.getElementById('tm-sales-count').textContent = `${SB_SALES.length} sales people`;
  const slHost = document.getElementById('tm-sales-list');
  if(SB_SALES.length===0){
    slHost.innerHTML = '<div class="tm-empty">ยังไม่มี Sales — เพิ่มคนแรกได้เลย</div>';
  } else {
    slHost.innerHTML = SB_SALES.map(s=>{
      const agentCount = SB_AGENTS.filter(a=>a.sales===s.id).length;
      const fullDisplay = s.fullName ? `<div class="tm-row-fullname">${s.fullName} <span class="tm-row-fullname-pos">· ${s.designation||'—'}</span></div>` : '';
      return `
        <div class="tm-row">
          <div class="tm-color-chip" style="background:${s.color}">${s.code}</div>
          <div class="tm-row-info">
            <div class="tm-row-name">${s.name}</div>
            ${fullDisplay}
            <div class="tm-row-meta">${s.email||'—'} ${s.tel?`· ${s.tel}`:''} · <span class="tm-row-meta-pill">${agentCount} agents</span></div>
          </div>
          <div class="tm-row-actions">
            <button class="tm-icon-btn" onclick="tmEditSales('${s.id}')" title="แก้ไข">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="tm-icon-btn danger" onclick="tmDeleteSales('${s.id}')" title="ลบ">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg>
            </button>
          </div>
        </div>
      `;
    }).join('');
  }

  // Market list
  document.getElementById('tm-mkt-count').textContent = `${SB_MARKETS.length} markets`;
  const mkHost = document.getElementById('tm-mkt-list');
  if(SB_MARKETS.length===0){
    mkHost.innerHTML = '<div class="tm-empty">ยังไม่มี Market — เพิ่มอันแรกได้เลย</div>';
  } else {
    mkHost.innerHTML = SB_MARKETS.map(m=>{
      const agentCount = SB_AGENTS.filter(a=>a.market===m.id).length;
      const subs = (m.subs||[]).slice(0,3).map(s=>`<span class="tm-row-meta-pill">${s}</span>`).join('');
      const more = (m.subs||[]).length>3 ? `<span class="tm-row-meta-pill">+${(m.subs||[]).length-3}</span>` : '';
      return `
        <div class="tm-row tm-drag" draggable="true" data-sort-id="${m.id}" data-sortgroup="mkt">
          ${LA_GRIP}
          <div class="tm-color-chip" style="background:${m.color||'#7a8fa3'}">${m.id.toUpperCase().slice(0,3)}</div>
          <div class="tm-row-info">
            <div class="tm-row-name">${m.name} <span style="font-size:10px;color:var(--ink-soft);font-weight:400">· ${agentCount} agents</span></div>
            <div class="tm-row-meta" style="margin-top:3px">${subs}${more}</div>
          </div>
          <div class="tm-row-actions">
            <button class="tm-icon-btn" onclick="tmEditMarket('${m.id}')" title="แก้ไข">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.12 2.12 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="tm-icon-btn danger" onclick="tmDeleteMarket('${m.id}')" title="ลบ">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-2 14a2 2 0 01-2 2H9a2 2 0 01-2-2L5 6"/></svg>
            </button>
          </div>
        </div>
      `;
    }).join('');
    laMakeSortable(mkHost, '.tm-row', tmApplyMarketOrder);   // drag-to-reorder markets
  }
}

