// B2B SALES DASHBOARD (view: b2b-dash) — spec: dashboard_implementation.md v1.0
// All metrics computed client-side over "trip-lines" (1 row per confirmed
// booking × trip) derived live from SB_BOOKINGS/SB_AGENTS/SB_SALES/SB_MARKETS.
// ══════════════════════════════════════════════════════════════════════════
window._b2d = window._b2d || { basis:'bd', mode:'mom', ref:null, T:10, tab:'overview', trip:null, stack:[], screen:null };
const B2D_FAM = {r1:'Similan',r2:'Similan',r3:'Similan',r4:'Similan',r5:'Similan',r6:'Surin',r7:'Phi Phi',r8:'Phi Phi',r9:'Phi Phi',r10:'Phi Phi',r11:'Krabi',r12:'Phi Phi'};   // §4.7 lookup, NOT name-parsing
