const B2D_MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
// InvestIQ design language (investiq_financial_dashboard.tsx): emerald accent, slate neutrals,
// rounded-3xl white cards, arrow delta pills, sparkline KPI cards.
const B2D_UI = { accent:'#00D084', accentD:'#059669', green:'#10B981', red:'#EF4444', rose:'#F43F5E',
  ink:'#0F172A', ink2:'#334155', mut:'#94A3B8', line:'#F1F5F9', line2:'#F8FAFC', navy:'#1E293B',
  card:'background:#fff;border:1px solid #F1F5F9;border-radius:24px;box-shadow:0 1px 2px rgba(15,23,42,.04),0 1px 3px rgba(15,23,42,.05);',
  pillG:'color:#059669;background:#ECFDF5;', pillR:'color:#E11D48;background:#FFF1F2;', pillN:'color:#64748B;background:#F1F5F9;' };
const B2D_CLS = { growth:{t:'Growth',c:'#059669',bg:'#ECFDF5'}, new:{t:'New',c:'#0F766E',bg:'#F0FDFA'}, stable:{t:'Stable',c:'#64748B',bg:'#F1F5F9'}, loss:{t:'Loss',c:'#E11D48',bg:'#FFF1F2'}, churn:{t:'Churned',c:'#B45309',bg:'#FEF3C7'} };
const B2D_HINT = { growth:'Keep momentum · consider more allotment', new:'New agent · onboard + check send quality', stable:'Maintain as usual', loss:'Follow up · find why volume dropped', churn:'Contact urgently · fully gone this period' };
const B2D_PALETTE = ['#10B981','#1E293B','#3B82F6','#F59E0B','#8B5CF6','#EC4899','#14B8A6','#F97316','#64748B','#0EA5E9','#84CC16','#A855F7'];
var SALES_SYS_URL = '';   // §7 integration hook — e.g. 'https://<sales-system>/agent/{code}' · '{id}'/'{code}' substituted

// ═══════════ MAIN RENDER ═══════════
function renderB2BDash(){
  const wrap=document.getElementById('b2bdash-wrap'); if(!wrap) return;
  const st=_b2d;
  const L=b2dLines(); window._b2dL=L;
  const w=b2dWin(L);  window._b2dW=w;
  const agAll=b2dAgents(L,w,null);
  const cur=b2dSum(L,w.cs,w.ce,null), prev=b2dSum(L,w.ps,w.pe,null);
  window._b2dCsvRows=[]; window._b2dCsvName='dashboard';

  // ── global controls (§5.1) · InvestIQ styling ──
  const segBtn=(k,v,label)=>'<button onclick="b2dSet(\''+k+'\',\''+v+'\')" style="border:none;padding:6px 14px;border-radius:99px;font-size:11.5px;cursor:pointer;font-weight:600;font-family:inherit;transition:all .15s;background:'+(st[k]===v?B2D_UI.accent:'transparent')+';color:'+(st[k]===v?'#fff':'#64748B')+';'+(st[k]===v?'box-shadow:0 2px 8px rgba(0,208,132,.25);':'')+'">'+label+'</button>';
  const modes=[['wow','Week (WoW)'],['mom','Month (MoM)'],['wly','Same week last year'],['mly','Same month last year'],['r12','Rolling 12M']];
  const inputSt='border:1px solid #E2E8F0;border-radius:99px;padding:7px 13px;font-size:11.5px;font-family:inherit;color:'+B2D_UI.ink2+';background:#fff';
  const controls=
    '<div style="'+B2D_UI.card+'padding:12px 18px;margin-bottom:18px;display:flex;flex-wrap:wrap;gap:10px;align-items:center">'
    +'<div style="background:#F1F5F9;border-radius:99px;padding:3px;display:flex;gap:2px">'+segBtn('basis','bd','Booking date')+segBtn('basis','td','Travel date')+'</div>'
    +'<select onchange="b2dSet(\'mode\',this.value)" style="'+inputSt+';cursor:pointer">'+modes.map(m=>'<option value="'+m[0]+'"'+(st.mode===m[0]?' selected':'')+'>'+m[1]+'</option>').join('')+'</select>'
    +'<input type="date" value="'+w.ref+'" onchange="if(this.value)b2dSet(\'ref\',this.value)" style="'+inputSt+'">'
    +'<label style="font-size:11.5px;color:'+B2D_UI.mut+';font-weight:600;display:inline-flex;align-items:center;gap:4px">Threshold ±<input type="number" min="1" max="50" step="1" value="'+st.T+'" onchange="b2dSet(\'T\',this.value)" style="'+inputSt+';width:58px;text-align:center;border-radius:12px">%</label>'
    +'<button onclick="b2dExport()" style="border:none;background:'+B2D_UI.accent+';color:#fff;border-radius:99px;padding:8px 16px;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit;box-shadow:0 3px 10px rgba(0,208,132,.3)">⬇ Export CSV</button>'
    +'<span style="font-size:11px;color:'+B2D_UI.mut+';margin-left:auto">Period <b style="color:'+B2D_UI.ink2+';font-weight:600">'+b2dThD(w.cs)+' – '+b2dThD(w.ce)+'</b> vs <b style="color:'+B2D_UI.ink2+';font-weight:600">'+b2dThD(w.ps)+' – '+b2dThD(w.pe)+'</b></span>'
    +'</div>';

  // ── §10 comparison-empty notice ──
  const notice = (prev.rev<=0 && cur.rev>0) ? '<div style="background:#FEF3C7;color:#92400E;border-radius:16px;padding:9px 16px;margin-bottom:16px;font-size:11.5px;font-weight:500">⚠ Comparison window has no data (records start Dec 2025) — growth % is not meaningful yet; treat as a live inventory for now</div>' : '';

  let body='';
  if(st.screen&&st.screen.t==='agent') body=b2dAgentDetail(L,w,agAll,st.screen.id);
  else if(st.screen&&st.screen.t==='staff') body=b2dStaffDetail(L,w,agAll,st.screen.id);
  else if(st.screen&&st.screen.t==='market') body=b2dMarketDetail(L,w,agAll,st.screen.id);
  else body=b2dTabsScreen(L,w,agAll,cur,prev);

  wrap.innerHTML='<div style="font-family:\'DM Sans\',\'Noto Sans Thai\',sans-serif;color:'+B2D_UI.ink+';background:#F3F4F6;border-radius:26px;padding:24px 22px 34px;margin:-6px">'
    +'<div style="max-width:1120px;margin:0 auto">'
    +'<div style="display:flex;align-items:center;gap:11px;margin-bottom:18px">'
    +'<div style="width:8px;height:32px;background:'+B2D_UI.accent+';border-radius:3px"></div>'
    +'<div><h2 style="margin:0;font-size:22px;font-weight:800;letter-spacing:-.02em;color:'+B2D_UI.ink+'">B2B Sales Dashboard</h2>'
    +'<div style="font-size:11px;color:'+B2D_UI.mut+';margin-top:1px">computed live from system bookings · confirmed only</div></div></div>'
    +controls+notice+body+'</div></div>';
}

