  +H+' .pa-away{position:absolute;left:2px;bottom:1px;z-index:2;font-size:7.5px;font-weight:800;letter-spacing:.02em;color:#20477E;background:#E9EFF7;border-radius:3px;padding:0 3px;line-height:11px}'
