    +'max-height:min(70vh,560px);overflow-y:auto;overscroll-behavior:contain}'
  +' .pa-pop .h{font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#8B93A1;margin-bottom:7px}'
  /* §paLayers · สลับว่ากำลังวางโครงหรือแก้ทับ · ต้องเลือกก่อนกดรหัส ไม่ใช่รู้ทีหลัง */
  +' .pa-lay{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-bottom:8px}'
