  +' .pa-lay button.on span{color:#B9C6E4}'
  +' .pa-pop button{display:flex;align-items:center;gap:8px;width:100%;border:1px solid #E7EAEF;background:#fff;border-radius:8px;padding:5px 8px;margin-bottom:4px;font:600 11.5px inherit;color:#242730;cursor:pointer;text-align:left}'
  +' .pa-pop button:hover{border-color:#16265C}'
  +' .pa-pop button i{font-style:normal;min-width:36px;text-align:center;border-radius:5px;font-size:9.5px;font-weight:800;line-height:18px}'
