  +' .pa-pop button.cur{border-color:#16265C;background:#F3F6FC;box-shadow:inset 0 0 0 1px #16265C}'
  +' .pa-pop button.cur:after{content:"\u2713";margin-left:auto;color:#16265C;font-weight:800}'
  +' .pa-pop .cap{font-size:9.5px;color:#8B93A1;font-weight:600;padding:0 2px 7px;line-height:1.45}';
