function paCellHtml(date, pier, st, day, hasJob, today, E, nOn){
  var v=paCell(date,pier,st,E), C=paCodeMeta(v.c);
  var bg=C?C.bg:'transparent', fg=C?C.color:'#D5D9E0';
  var we=(day.w===0||day.w===6);
  var away=(v.atPier && v.atPier!==pier) ? v.atPier : '';
  var tip=(v.c||'ยังไม่มีใบงาน')+((C&&C.route&&C.label)?(' · '+C.label):'')+(v.boat?(' · '+v.boat):'')
    +(away?(' · ไปช่วยท่า '+((PO_PIERS.filter(function(x){return x.k===away;})[0]||{}).t||away)):'')
    +(v.src==='manual'?' · แก้ทับรายช่อง (ใบงานทับไม่ได้)'
     :(v.src==='plan'?' · โครงงานที่วางไว้ (ใบงานทับได้)'
     :(v.src==='boat'?' · จากใบงานเรือ'
     :(v.src==='todo'?' · ยังไม่ได้วางงานให้คนนี้':''))));
  /* §paNight · แถบล่างของช่อง · โผล่เฉพาะรอบที่มีเวรกลางคืนจริง
     รอบไหนไม่มีใครเข้าเวร ตารางหน้าตาเหมือนเดิมทุกประการ ไม่ต้องเสียความสูงเปล่า */
  var nc=nOn?paNight(date,st.id):'';
  if(nOn) tip+=' · '+(nc?('เวรกลางคืน '+nc):'ไม่มีเวรกลางคืน');
  return '<td class="pa-c'+(!hasJob?' nf':(we?' we':''))+(v.src==='todo'?' todo':'')
      +(nOn?' nt':'')+'" title="'+poE(tip)+'"'
    +' onclick="paPick(event,\''+date+'\',\''+st.id+'\')">'
    +'<span class="pa-cd" style="background:'+bg+';color:'+fg+'">'+poE(v.c||'·')+'</span>'
    +(away?'<span class="pa-away">'+poE(pjPierShort(away))+'</span>':'')
    +(nOn?('<span class="pa-nb'+(nc?' on':'')+'">'+poE(nc||'')+'</span>'):'')+'</td>';
}

/* §paRtSkin · ชุดสีของรหัสเส้นทางในตารางการทำงาน · [สีตัวอักษร, สีพื้น]
   เลือกให้ห่างจากแดง (ลา/ขาดงาน) เทา (หยุด) และม่วง (งานซ่อม) โดยตั้งใจ */
var PA_RT_SKIN={
  PP:['#9E1E5C','#FBE4EE'],   SL:['#0B6552','#E2F5EF'],   WS:['#8A5100','#FDF0DC'],
  SR:['#0E6E86','#E3F2F7'],   KB:['#5C6B12','#F1F4DC'],   RY:['#2E4C9B','#E8ECFA'],
  CR:['#96501E','#FBEEE4'],   JB:['#6B3A7A','#F4EAF7']
};
/* รหัสเส้นทางที่ไม่อยู่ในชุดข้างบน · หมุนใช้สีสำรอง แบบเดิม ๆ ทุกครั้งจากตัวรหัสเอง
   ใช้ผลรวมตัวอักษรแทนลำดับที่เจอ · เพิ่มหรือลบเส้นทางแล้วสีของรหัสอื่นจะได้ไม่สลับกันทั้งตาราง */
var PA_RT_MORE=[['#1F5F8B','#E4EFF6'],['#7A4B12','#F7EFE3'],['#4B3B8F','#ECE9F8'],
                ['#2F6B4F','#E6F1EC'],['#8C3A5E','#F8E8EF'],['#55632A','#EFF2E3']];
function paRtSkin(code){
  var k=String(code||'').toUpperCase();
  if(PA_RT_SKIN[k]) return PA_RT_SKIN[k];
  var n=0; for(var i=0;i<k.length;i++) n=(n*31+k.charCodeAt(i))%1000;
  return PA_RT_MORE[n%PA_RT_MORE.length];
}
/* §paSkinC · ชุดสีมาตรฐาน · [สีตัวอักษร, สีพื้น]
   วันหยุดพื้นเกือบขาว ไม่ใช่ไม่มีพื้น · เก็บเป็นสีจริงไว้ ช่องเลือกสีในทะเบียนรหัสจะได้ไม่เพี้ยน */
var PA_SKIN_C={
  PP:  ['#20477E','#E9EFF7'],   SE:  ['#20477E','#E9EFF7'],
  OFF: ['#B8BFC9','#FCFCFD'],   PH:  ['#9AA3B0','#FBFBFD'],
  LWOP:['#A3251A','#FDECEA'],   ABS: ['#A3251A','#FDECEA'],
  LWP: ['#9B4A3A','#FBEDE9'],                               // ตระกูลลาเหมือน LWOP · เดิมเป็นเหลืองอำพันซึ่งชนกับ WS
  SC:  ['#185FA5','#E7F0FA'],   SR:  ['#0E6E86','#E3F2F7'],  // SR ใช้สีเดียวกับรหัสเส้นทาง SR ตั้งใจให้ตรงกัน
  '5': ['#4A5568','#EDEFF3'],   MT:  ['#5B3B96','#F2EBFA']
};
/* ค่าตั้งต้น "ชุดเดิม" · ใช้ดูว่ารหัสนี้ยังไม่เคยถูกแก้สี ถึงจะเขียนทับได้ */
var PA_SKIN_OLD={
  PP:  ['#A82063','#FCE7F0'],   SE:  ['#20477E','#E9EFF7'],
  OFF: ['#8B93A1','#F3F4F6'],   PH:  ['#6C3FB0','#EFE7FB'],
  LWOP:['#B32B1E','#FDECEA'],   ABS: ['#A3251A','#FDECEA'],
  LWP: ['#8A5A00','#FFF3E0'],
  SC:  ['#1668A8','#E4F1FB'],   SR:  ['#0E7D74','#E2F7F5'],
  '5': ['#8A6D1F','#FFF7CC'],   MT:  ['#5B3B96','#F2EBFA']
};
/* §paSkinReset · กดเอง · คืนทั้งชุดรวมถึงรหัสที่เคยเลือกสีไว้เอง
   ต่างจาก paSkinApply ตรงที่อันนั้นทำเงียบ ๆ ตอนบูตและเลี่ยงของที่ผู้ใช้เลือก */
function paSkinReset(){
  if(!poGuard()) return;
  var n=0; (PIER_CODES||[]).forEach(function(c){ if(PA_SKIN_C[String(c.code||'').trim()]) n++; });
  if(!confirm('คืนสีของรหัสมาตรฐาน '+n+' ตัวให้เป็นชุดที่ออกแบบไว้\n\n'
    +'สีที่เคยเลือกเองของรหัสเหล่านี้จะถูกทับ · รหัสที่ตั้งเองใหม่ไม่ถูกแตะ\n'
    +'รหัสของเส้นทาง (PP · SL · WS …) ใช้ชุดสีของตารางอยู่แล้ว')) return;
  (PIER_CODES||[]).forEach(function(c){
    var w=PA_SKIN_C[String(c.code||'').trim()]; if(!w) return;
    c.color=w[0]; c.bg=w[1]; delete c.userColor;
  });
  if(PIER_CFG && typeof PIER_CFG==='object') PIER_CFG.skin='c1';
  poPersist(); paCodesOpen();
  try{ renderPierAtt(); }catch(_){}
  try{ if(typeof renderPierJob==='function') renderPierJob(); }catch(_){}
}
/* §paSkinC · ทำครั้งเดียวต่อฐานข้อมูล · ไม่แตะสีที่ผู้ใช้เลือกเอง */
function paSkinApply(){
  try{
    if(!Array.isArray(PIER_CODES) || !PIER_CODES.length) return;
    if(PIER_CFG && PIER_CFG.skin==='c1') return;
    var hit=0;
    PIER_CODES.forEach(function(c){
      var k=String(c.code||'').trim(), want=PA_SKIN_C[k], was=PA_SKIN_OLD[k];
      if(!want || !was) return;
      // ตรงกับค่าตั้งต้นเดิมทั้งคู่ = ยังไม่เคยมีใครเลือกสีนี้เอง
      if(String(c.color||'').toUpperCase()!==was[0] || String(c.bg||'').toUpperCase()!==was[1]) return;
      c.color=want[0]; c.bg=want[1]; hit++;
    });
    if(!PIER_CFG || typeof PIER_CFG!=='object') return;
    PIER_CFG.skin='c1';
    if(typeof poCanEdit==='function' && poCanEdit()) poPersist();
  }catch(_){}
}
/* §pjWork · ทะเบียนที่ตั้งไว้ก่อนมีงานซ่อม จะยังไม่มีรหัส MT · เติมให้ครั้งเดียว
   เติมแล้วแก้ชื่อ เปลี่ยนสี หรือลบทิ้งได้เหมือนรหัสอื่นทุกประการ
   ตรวจก่อนเติมทุกครั้ง จึงไม่เขียนซ้ำและไม่ทับของที่ผู้ใช้แก้ไว้ */
function paEnsureMtCode(){
  try{
    if(!Array.isArray(PIER_CODES) || !PIER_CODES.length) return;
    var want=String(paMtCode()||'MT').trim(); if(!want) return;
    var has=PIER_CODES.some(function(c){ return String(c.code||'').trim().toUpperCase()===want.toUpperCase(); });
    if(has) return;
    var mx=PIER_CODES.reduce(function(a,c){ return Math.max(a,+c.ord||0); },0);
    PIER_CODES.push({id:'c_mt_'+Date.now().toString(36), code:want, label:'งานซ่อม / ขึ้นคาน',
                     color:'#5B3B96', bg:'#F2EBFA', kind:'work', ord:mx+1, active:true});
    if(typeof poCanEdit==='function' && poCanEdit()) poPersist();
  }catch(_){}
}
/* §plMerge · แท็บที่กำลังดูอยู่ในหน้าตารางการทำงาน · roster | lic */
var _paTab='roster';
function renderPierAtt(pier){
  paEnsureMtCode(); paEnsureNightCode(); paSkinApply();
  if(pier) _poPier=pier;
  var P=PO_PIERS.filter(function(p){ return p.k===_poPier; })[0]||PO_PIERS[0];
  var host=document.getElementById('pa-host-'+P.k); if(!host) return;
  /* §plMerge · เดิมใบอนุญาตเป็นเมนูแยกที่ปิดสิทธิ์ได้ต่างหาก
     ยุบมารวมแล้วต้องไม่ทำให้คนที่ไม่มีสิทธิ์ pol-<ท่า> เห็นของที่ไม่ควรเห็น */
  var _licOK=true;
  try{ if(typeof laAllowed==='function') _licOK=!!laAllowed('pol-'+P.k); }catch(_){}
  var _isLic=(_paTab==='lic' && _licOK);
  /* จำนวนใบที่หมดอายุแล้ว · ติดไว้บนแท็บ จะได้เห็นโดยไม่ต้องกดเข้าไปดู */
  var _licBad=0;
  if(_licOK) try{
    (PIER_STAFF||[]).filter(function(s){ return s.pier===P.k && s.active!==false; })
      .forEach(function(s){ plOf(s.id).forEach(function(l){ if(plState(l)==='bad') _licBad++; }); });
  }catch(_){}
  var ro=!poCanEdit(), CY=paCycle(_paDate), groups=paGroups(P.k), today=poYMD(new Date());
  var ed=(!ro && _paEdit);   // §paEditLock · ช่องพิมพ์ทับเปิดเฉพาะตอนกด "แก้ไข" ค้างไว้
  var WD=['SUN','MON','TUE','WED','THU','FRI','SAT'];   // §paSheet · หัวข้อเป็นอังกฤษตามที่ตกลง
  var IDX=paIndex(CY.days);
  var hasJob={}, nJob=0;
  CY.days.forEach(function(d){ hasJob[d.s]=paHasJob(d.s,P.k,IDX[d.s]); if(hasJob[d.s]) nJob++; });

  /* §paSum · รหัสที่ใช้จริงในรอบนี้ · เรียงเส้นทางก่อน แล้วค่อยรหัสของทะเบียน */
  var used={};
  groups.forEach(function(G){ G.rows.forEach(function(st){
    CY.days.forEach(function(d){ var v=paCell(d.s,P.k,st,IDX[d.s]); if(v.c) used[v.c]=1; }); }); });
  var SUMC=Object.keys(used).sort(function(a,b){
    var ma=paCodeMeta(a)||{}, mb=paCodeMeta(b)||{};
    var ra=ma.route?0:1, rb=mb.route?0:1;
    if(ra!==rb) return ra-rb;
    if(ra===0) return String(a).localeCompare(String(b));
    return ((ma.ord!=null?ma.ord:99)-(mb.ord!=null?mb.ord:99)) || String(a).localeCompare(String(b));
  });

  /* §paNight · รอบนี้มีเวรกลางคืนหรือเปล่า · มีแม้ช่องเดียวก็เปิดแถบล่างทั้งตาราง
     ไม่งั้นบางช่องสูงไม่เท่ากันแล้วอ่านเป็นตารางคนละอัน · นับจำนวนคืนของแต่ละคนไปเลยในรอบเดียว */
  var nOn=false, nCnt={}, nTot=0;
  groups.forEach(function(G){ G.rows.forEach(function(st){
    CY.days.forEach(function(d){
      if(paNight(d.s, st.id)){ nOn=true; nCnt[st.id]=(nCnt[st.id]||0)+1; nTot++; }
    }); }); });

  /* §paCols · รอบ 26–25 คร่อมสองเดือนเสมอ · ต้องบอกให้ชัดว่าเลข 1 กับ 26 คนละเดือน */
  var MTH=['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];
  var spans=[]; CY.days.forEach(function(d){
    var key=String(d.s).slice(0,7);
    if(spans.length && spans[spans.length-1].k===key) spans[spans.length-1].n++;
    else spans.push({k:key, n:1, m:d.m, y:+String(d.s).slice(0,4)});
  });
  var head='<tr>'
    + '<th class="pa-h0" colspan="4">CREW DUTY ROSTER &nbsp;&middot;&nbsp; '+poE(CY.from)+' – '+poE(CY.to)+' &nbsp;&middot;&nbsp; '+poE(String(P.n||P.t).toUpperCase())+'</th>'
    + spans.map(function(sp){ return '<th class="pa-mo" colspan="'+sp.n+'">'+MTH[sp.m]+' '+sp.y+'</th>'; }).join('')
    + '<th class="pa-mo sum" colspan="'+(SUMC.length+1+(nOn?1:0))+'">MONTHLY SUMMARY (DAYS)</th>'
    + '<th class="pa-h0 nt">REMARKS</th></tr>'
    + '<tr><th class="pa-no">No.</th><th class="pa-nm2">Full name</th><th class="pa-nk">Nickname</th><th class="pa-rl">Position</th>'
    + CY.days.map(function(d){
        var we=(d.w===0||d.w===6);
        return '<th class="pa-d'+(!hasJob[d.s]?' nf':(we?' we':''))+(d.s===today?' tdy':'')+'">'
          +'<div class="dd">'+d.n+'</div><div class="dw">'+WD[d.w]+'</div></th>'; }).join('')
    + SUMC.map(function(c){ var m=paCodeMeta(c)||{};
        return '<th class="pa-sh'+(m.route?' rt':'')+'" title="'+poE(m.label||c)+'">'+poE(c)+'</th>'; }).join('')
    + (nOn?('<th class="pa-sh ngt" title="จำนวนคืนที่เข้าเวร · นับที่วันเริ่มเวร">'
        +poE(paNightCode())+'</th>'):'')
    + '<th class="pa-sh tot">TOTAL</th><th class="pa-nt">Notes</th></tr>';

  var body='', totW=0, totO=0, totL=0, totAway=0, totTodo=0, gTot={}, _n=0;
  groups.forEach(function(G){
    body+='<tr class="pa-band"><td class="pa-no"></td><td class="pa-nm2" colspan="3">'+poE(G.t)+'</td>'
      +'<td colspan="'+(CY.days.length+SUMC.length+2+(nOn?1:0))+'"></td></tr>';
    G.rows.forEach(function(st){
      var w=0,o=0,l=0,aw=0,cnt={};
      var tds=CY.days.map(function(d){
        var E=IDX[d.s], v=paCell(d.s,P.k,st,E), k=paKindOf(v.c);
        if(v.c){ cnt[v.c]=(cnt[v.c]||0)+1; gTot[v.c]=(gTot[v.c]||0)+1;
                 if(k==='work') w++; else if(k==='off') o++; else if(k==='leave') l++; }
        else if(v.src==='todo') totTodo++;   // §paLayers · ช่องค้าง · ต้องมีตัวเลขให้เห็น ไม่งั้นช่องว่างอ่านเป็น "ไม่มีอะไรต้องทำ"
        if(v.atPier && v.atPier!==P.k) aw++;
        return paCellHtml(d.s,P.k,st,d,hasJob[d.s],today,E,nOn);
      }).join('');
      totW+=w; totO+=o; totL+=l; totAway+=aw;
      var _nc=nCnt[st.id]||0;
      var sums=SUMC.map(function(c){ var v=cnt[c]||0;
        return '<td class="pa-sc'+(v?'':' z')+'">'+(v||'·')+'</td>'; }).join('')
        + (nOn?('<td class="pa-sc ngt'+(_nc?'':' z')+'">'+(_nc||'·')+'</td>'):'')
        + '<td class="pa-sc tot">'+w+'</td>';
      _n++;
      // §paEdit · สี่ช่องแรกพิมพ์ทับได้ตรงนี้ · ออกจากช่องแล้วบันทึกเลย
      var _aw=(aw?('<b class="pa-away" title="ไปลงเรือที่ท่าอื่น '+aw+' วัน · ยังนับเป็นวันทำงานของท่าประจำ">ช่วยท่าอื่น '+aw+'</b>'):'');
      body+='<tr><td class="pa-no">'+_n+'</td>'
        +'<td class="pa-nm2">'+(ed?(paEi(st.id,'name',st.name,'ชื่อ–นามสกุล')+_aw)
            :(poE(st.name||st.nick||st.id)+(_aw?' '+_aw:'')))+'</td>'
        +'<td class="pa-nk">'+(ed?paEi(st.id,'nick',st.nick,'ชื่อเล่น'):poE(st.nick||''))+'</td>'
        // §paDefQuiet · รหัสตั้งต้นเป็นค่าตั้งของการวางแผน ไม่ใช่เนื้อหาของตาราง · โผล่ตอนกดแก้ไขพอ
        +'<td class="pa-rl">'+(ed
            ?('<div class="pa-rlw">'+paEi(st.id,'role',st.role,'ตำแหน่ง')+paDefSel(st)+'</div>')
            :poE(st.role||''))+'</td>'
        +tds+sums
        /* §paNoteEd · หมายเหตุคือของที่คนหน้าท่าพิมพ์ระหว่างวัน ไม่ใช่ของที่ต้องวางแผนก่อน
           บังคับให้กด "แก้ไข" ทั้งแถบก่อนถึงจะพิมพ์ได้ ทำให้ไม่มีใครใช้ · เปิดให้พิมพ์ได้เลย
           คนที่สิทธิ์ดูอย่างเดียว (ro) ยังเห็นเป็นข้อความเหมือนเดิม */
        +'<td class="pa-nt">'+(ro
            ?(poE(st.note||'')||'<span class="pa-dash">—</span>')
            :('<input class="pa-nti" value="'+poE(st.note||'')+'" placeholder="เพิ่มหมายเหตุ…" '
              +'title="พิมพ์แล้วออกจากช่อง = บันทึกเลย" '
              +'onchange="paNote(\''+poE(st.id)+'\',this.value)">'))+'</td></tr>';
    });
  });
  /* แถวรวมท้ายตาราง · ทั้งท่าใช้คนไปกี่วัน-คน กับแต่ละรหัสไปเท่าไหร่ */
  body+='<tr class="pa-tot"><td class="pa-no"></td><td class="pa-nm2" colspan="3">TOTAL &middot; ALL STAFF</td>'
    + CY.days.map(function(){ return '<td></td>'; }).join('')
    + SUMC.map(function(c){ return '<td class="pa-sc">'+(gTot[c]||0)+'</td>'; }).join('')
    + (nOn?('<td class="pa-sc ngt">'+nTot+'</td>'):'')
    + '<td class="pa-sc tot">'+totW+'</td><td class="pa-nt"></td></tr>';

  // §rtLegend · รหัสที่โผล่จริงในรอบนี้มาก่อน (รวมรหัสเส้นทาง) แล้วค่อยรหัสอื่นในทะเบียน
  var _lgSeen={};
  var lg=SUMC.map(function(code){
    var c=paCodeMeta(code); if(!c) return ''; _lgSeen[code]=1;
    return '<div class="i'+(c.route?' rt':'')+'"><b style="background:'+c.bg+';color:'+c.color+'">'+poE(c.code)+'</b>'
      +(c.label?poE(c.label):'<em>ยังไม่ได้ใส่ความหมาย</em>')
      +(c.route?'<span class="rtag">เส้นทาง</span>':'')+'</div>'; }).join('')
    + paCodes().filter(function(c){ return !_lgSeen[c.code]; }).map(function(c){
    return '<div class="i off"><b style="background:'+c.bg+';color:'+c.color+'">'+poE(c.code)+'</b>'
      +(c.label?poE(c.label):'<em>ยังไม่ได้ใส่ความหมาย</em>')+'</div>'; }).join('')
    +'<div class="i"><b style="background:#FFFCF3;color:#B8BEC8">·</b>ยังไม่ได้วางงานให้คนนี้ · วันนั้นท่ามีใบงานอยู่</div>'
    +'<div class="i"><b style="background:transparent;color:#B8BEC8">·</b>ยังไม่มีใบงานของวันนั้นทั้งท่า</div>'
    +'<div class="i"><b style="background:#E9EFF7;color:#20477E">TL</b>ไปช่วยท่าอื่นวันนั้น · ยังนับวันทำงานที่ท่าประจำ</div>';

  host.innerHTML='<style id="pa-style">'+pjCSS()+plCSS()+paCSS()+poCSS()+'</style>'
    +'<div class="pj-h"><div><div class="lab">Pier Office</div>'
      +'<h1>'+poE(P.n||P.t)+' · '+(_isLic?'ใบอนุญาต':'ตารางการทำงาน')+'</h1>'
      +'<p>'+(_isLic
        ? 'ใบกัปตันและใบช่างเครื่องของพนักงานที่<b>ประจำท่านี้</b> (คนที่มาช่วยจากท่าอื่นดูได้ที่ท่าประจำของเขา) · '
          +'ใบงานเรือจะตรวจให้อัตโนมัติทุกลำ ว่ามีคนถือใบครบไหม ชั้นครอบคลุมเรือลำนั้นไหม และใบยังไม่หมดอายุไหม'
        : ('ขึ้นเองจากใบงานเรือ · แก้ทับรายช่องได้ · '
          +'รอบนี้มีใบงานแล้ว <b style="color:#16265C">'+nJob+'</b> วัน จาก '+CY.days.length+' วัน'
          +(ed?' · <b style="color:#8A5A00">กำลังแก้ไขรายชื่ออยู่</b>':'')))+'</p></div></div>'
    /* §plMerge · สองหน้านี้อ่าน PIER_STAFF ชุดเดียวกัน และปุ่ม "ทะเบียนประเภทใบ"
       ก็อยู่บนแถบนี้อยู่แล้ว · ของมันคู่กันตั้งแต่แรก แค่ถูกแยกเป็นสองบรรทัดในเมนู */
    +(_licOK?('<div class="pj-bar" style="margin-bottom:9px">'
      +'<button class="'+(_isLic?'':'pri')+'" onclick="paTab(\'roster\')">ตารางการทำงาน</button>'
      +'<button class="'+(_isLic?'pri':'')+'" onclick="paTab(\'lic\')">ใบอนุญาต'
        +(_licBad?('<span style="margin-left:6px;background:#FBE9E4;color:#C0271C;border-radius:999px;'
          +'padding:1px 7px;font-size:10.5px;font-weight:800">'+_licBad+'</span>'):'')+'</button>'
      +'</div>'):'')
    +(_isLic ? plBody(P, ro) : ''
    +'<div class="pj-bar">'
      +'<button onclick="paShift(-1)">&#8249; รอบก่อน</button>'
      +'<span style="font-size:13px;font-weight:800;color:#16265C;font-variant-numeric:tabular-nums">'+poE(CY.from)+' – '+poE(CY.to)+'</span>'
      +'<button onclick="paShift(1)">รอบถัดไป &#8250;</button>'
      +'<button onclick="paThis()">รอบปัจจุบัน</button>'
      +'<span style="font-size:12px;color:#6E7684;margin-left:6px">รวม ทำงาน <b style="color:#0F6E56">'+totW+'</b> · หยุด <b>'+totO+'</b> · ลา <b style="color:#B4560A">'+totL+'</b> วัน-คน'
        +(totAway?(' · <b style="color:#20477E">ไปช่วยท่าอื่น '+totAway+'</b>'):'')
        +(totTodo?(' · <b style="color:#8A5A00">ยังไม่ได้วาง '+totTodo+' ช่อง</b>'):'')+'</span>'
      +'<span style="flex:1"></span>'
      +(ro?'':'<button class="pa-edb'+(ed?' on':'')+'" onclick="paEditToggle()" '
          +'title="เปิดให้พิมพ์แก้ ชื่อ · ชื่อเล่น · ตำแหน่ง · รหัสตั้งต้น · หมายเหตุ">'
          +(ed?'&#10003; แก้ไขอยู่ · กดเพื่อปิด':'&#9998; แก้ไข')+'</button>')
      +'<button class="gh" onclick="paRangeOpen()"'+(ro?' disabled':'')+'>วางงานเป็นช่วง</button>'
      /* §regHub · ทะเบียนทั้งหมดของท่าอยู่ตรงนี้ที่เดียว · ชื่อขึ้นต้น "ทะเบียน" เหมือนกันหมด */
      +'<span class="sep"></span>'
      +'<button onclick="poStaffOpen()" title="ชื่อ · ตำแหน่ง · ท่าประจำ · รหัสตั้งต้น">ทะเบียนพนักงาน</button>'
      +'<button onclick="goRegOpen(\'\')" title="ไกด์ · ภาษา · บทบาท · เลขที่ใบ · ผู้มีอำนาจลงนาม">ทะเบียนไกด์</button>'
      +'<button onclick="paSectOpen()" title="หัวข้อกลุ่มในตารางนี้">ทะเบียนกลุ่ม</button>'
      +'<button onclick="paCodesOpen()" title="รหัสงานที่ใช้ในตาราง">ทะเบียนรหัส</button>'
      +'<button onclick="plTypesOpen()" title="ประเภทใบอนุญาตของพนักงาน">ทะเบียนประเภทใบ</button>'
      +'<span class="sep"></span>'
      +'<button onclick="paExport()">Export CSV</button>'
      +'<button class="pri" onclick="paPrint()">พิมพ์</button>'
    +'</div>'
    +(groups.length
      ? ('<div class="pl-card" style="margin-bottom:0"><div class="pa-wrap"><table class="pa'+(ed?' ed':'')+'"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div>'
         +'<div class="pa-lg">'+lg+'</div></div>')
      : '<div class="pj-empty">ยังไม่มีพนักงานของท่านี้ · กดปุ่ม "ทะเบียนพนักงาน" ที่แถบด้านบนเพื่อเพิ่ม</div>'));
}
/* §plMerge · สลับแท็บ · จำไว้ระหว่างที่ยังอยู่ในหน้านี้ ไม่ได้เก็บลงข้อมูล */
function paTab(t){ _paTab=(t==='lic')?'lic':'roster'; renderPierAtt(); }
function paShift(n){
  var CY=paCycle(_paDate), d=new Date(CY.from+'T12:00:00');
  d.setMonth(d.getMonth()+n); _paDate=poYMD(d); renderPierAtt();
}
function paThis(){ _paDate=poYMD(new Date()); renderPierAtt(); }

/* ── คลิกช่อง · เลือกรหัส ── */
function paPick(ev, date, sid){
  if(!poCanEdit()) return;
  ev.stopPropagation();
  var old=document.getElementById('pa-pop'); if(old) old.remove();
  var st=(PIER_STAFF||[]).filter(function(x){ return x.id===sid; })[0]; if(!st) return;
  var cur=paCell(date,_poPier,st), m=paManualRec(date,sid);
  var d=document.createElement('div'); d.className='pa-pop'; d.id='pa-pop';
  // §paPickRt · รหัสเส้นทางของท่านี้ต้องเลือกได้ · ไม่งั้นแก้ทับเป็น "วันนี้ไปลง Krabi" ไม่ได้
  var _rtSeen={}, _rtOpts=[];
  try{
    (typeof ROUTES!=='undefined'?ROUTES:[]).forEach(function(r){
      if((r.pier||'')!==_poPier) return;
      var code=paRouteCode(r.id); if(!code || _rtSeen[code]) return;
      _rtSeen[code]=1; _rtOpts.push(paCodeMeta(code));
    });
  }catch(_){}
  // §paLayers · เลือกก่อนว่ากำลังทำอะไร · วางโครง (ใบงานทับได้) หรือแก้ทับ (ใบงานทับไม่ได้)
  //   ค่าตั้งต้นคือแก้ทับ · คนที่มาคลิกทีละช่องมักกำลังแก้ให้ถูก ไม่ใช่วางแผน
  var _pl=(m&&m.plan)?1:0;
  var mk=function(code){ return 'paSet(\''+date+'\',\''+sid+'\',\''+code+'\',_paPlan)'; };
  /* §paPopFix · cur ถูกคำนวณไว้ตั้งแต่แรกแต่ไม่เคยถูกใช้ · เอามาบอกว่าช่องนี้เป็นรหัสอะไรอยู่ */
  var _curC=(cur&&cur.c)||'';
  var _cls=function(code){ return (code&&code===_curC)?' class="cur"':''; };
  var _srcTxt={manual:'แก้ทับรายช่อง', plan:'โครงที่วางไว้', boat:'มาจากใบงานเรือ', todo:'ยังไม่ได้วางงาน'}[cur&&cur.src]||'';
  var _nOn=!!paNight(date,sid);   /* §paNight */
  d.innerHTML='<div class="h">'+poE(st.nick||st.name)+' · '+poE(date)+'</div>'
    + (_curC?('<div class="cap">ตอนนี้คือ <b style="color:#16265C">'+poE(_curC)+'</b>'
        +(_srcTxt?(' · '+poE(_srcTxt)):'')+'</div>'):'')
    + '<div class="pa-lay">'
      + '<button class="'+(_pl?'':'on')+'" onclick="paPlanMode(0,this)">แก้ทับ<span>ใบงานทับไม่ได้</span></button>'
      + '<button class="'+(_pl?'on':'')+'" onclick="paPlanMode(1,this)">วางโครง<span>ใบงานทับได้</span></button>'
    + '</div>'
    + (_rtOpts.length?('<div class="s">เส้นทางของท่านี้</div>'):'')
    + _rtOpts.map(function(c){
        return '<button'+_cls(c.code)+' onclick="'+mk(poE(c.code))+'">'
          +'<i style="background:'+c.bg+';color:'+c.color+'">'+poE(c.code)+'</i>'+poE(c.label||'')+'</button>'; }).join('')
    + (_rtOpts.length?('<div class="s">อื่น ๆ</div>'):'')
    + paCodes().filter(function(c){ return !_rtSeen[c.code] && c.kind!=='night'; }).map(function(c){
        return '<button'+_cls(c.code)+' onclick="'+mk(poE(c.code))+'">'
          +'<i style="background:'+c.bg+';color:'+c.color+'">'+poE(c.code)+'</i>'
          +(c.label?poE(c.label):'<span style="color:#C0271C">ยังไม่ใส่ความหมาย</span>')+'</button>'; }).join('')
    /* §paNight · แยกออกมาเป็นสวิตช์ เพราะเวรกลางคืนไม่ได้แทนงานกลางวัน แต่บวกเพิ่ม */
    + '<div class="s">เวรกลางคืน</div>'
    + '<button'+(_nOn?' class="cur"':'')+' onclick="paNightToggle(\''+date+'\',\''+sid+'\')">'
      +'<i style="background:#1F2937;color:#fff">'+poE(paNightCode())+'</i>'
      +(_nOn?'เอาเวรกลางคืนออก':'ใส่เวรกลางคืน · ไม่ทับงานกลางวัน')+'</button>'
    + '<button onclick="paSet(\''+date+'\',\''+sid+'\',\'\')" style="border-style:dashed;color:#8B93A1">'
      +'<i style="background:#F4F6FA;color:#8B93A1">auto</i>ล้างงานกลางวัน · กลับไปใช้ใบงาน</button>';
  _paPlan=_pl;
  document.body.appendChild(d);
  var r=ev.currentTarget.getBoundingClientRect();
  /* §paPopFix · กล่องสูงกว่าที่เหลือใต้ช่อง ให้เด้งขึ้นไปอยู่เหนือช่องแทนการล้นจอ */
  var h=d.offsetHeight, below=window.innerHeight-r.bottom-10;
  var top=(h<=below) ? (r.bottom+4) : Math.max(8, Math.min(r.top-h-4, window.innerHeight-h-10));
  d.style.left=Math.max(8, Math.min(r.left-90, window.innerWidth-d.offsetWidth-10))+'px';
  d.style.top=Math.max(8, top)+'px';
  setTimeout(function(){ document.addEventListener('click', paPopClose, {once:true}); },0);
}
/* §paPopFix · Esc ปิดได้ · คนที่เปิดผิดช่องจะได้ไม่ต้องเล็งคลิกที่ว่าง */
document.addEventListener('keydown', function(e){
  if(e.key==='Escape' && document.getElementById('pa-pop')) paPopClose();
});
function paPopClose(){ var d=document.getElementById('pa-pop'); if(d) d.remove(); }
/* §paEditLock · ล็อกไว้ก่อน · ไม่เก็บลงข้อมูล รีเฟรชแล้วกลับมาล็อกเสมอ */
var _paEdit=false;
function paEditToggle(){
  if(!poCanEdit()) return;
  _paEdit=!_paEdit;
  paKeep(function(){ renderPierAtt(); });
}
/* §paEdit · ช่องพิมพ์ทับในตาราง · หน้าตาเหมือนข้อความจนกว่าจะชี้ */
function paEi(sid, key, val, ph){
  return '<input class="pa-ei" value="'+poE(val||'')+'" placeholder="'+poE(ph||'')+'" '
    + 'title="แก้ได้ตรงนี้ · ออกจากช่องแล้วบันทึกเอง" '
    + 'onchange="paStaffFld(\''+poE(sid)+'\',\''+key+'\',this.value)">';
}
/* รหัสตั้งต้น · เลือกจากทะเบียนรหัสเท่านั้น · พิมพ์เองแล้วสรุปจะนับไม่ถูก */
function paDefSel(st){
  var cur=String(st.defCode||''), fb=paDefFallback();
  var cs=(PIER_CODES||[]).filter(function(c){ return c && c.active!==false; })
    .sort(function(a,b){ return (+a.ord||0)-(+b.ord||0); });
  var seen={}; cs.forEach(function(c){ seen[c.code]=1; });
  if(cur && !seen[cur]) cs.push({code:cur, label:'(ไม่มีในทะเบียน)'});   // ของเก่าที่ตั้งไว้ก่อน ต้องไม่หายไปเงียบ ๆ
  return '<select class="pa-dc" title="รหัสตั้งต้นของคนนี้ · ใช้เป็นค่าเริ่มต้นตอนวางโครงงาน" '
    + 'onchange="paStaffFld(\''+poE(st.id)+'\',\'defCode\',this.value)">'
    // ตัวย่ออย่างเดียวในช่อง · ความหมายเต็มอยู่ในแถบรหัสท้ายหน้าอยู่แล้ว ใส่ซ้ำจะดันคอลัมน์จนล้น
    + '<option value=""'+(cur?'':' selected')+' title="ใช้ค่ากลางของท่า">&mdash; '+poE(fb)+'</option>'
    + cs.map(function(c){ return '<option value="'+poE(c.code)+'"'+(c.code===cur?' selected':'')
        +' title="'+poE(c.label||c.code)+'">'+poE(c.code)+'</option>'; }).join('')
    + '</select>';
}
/* วาดตารางใหม่โดยไม่ทิ้งตำแหน่งที่เลื่อนค้างไว้ · รอบหนึ่ง 31 คอลัมน์ เลื่อนกลับเองไม่ไหว */
function paKeep(fn){
  var w=document.querySelector('#pa-host-'+_poPier+' .pa-wrap');
  var x=w?w.scrollLeft:0, y=w?w.scrollTop:0;
  fn();
  try{ var w2=document.querySelector('#pa-host-'+_poPier+' .pa-wrap');
    if(w2){ w2.scrollLeft=x; w2.scrollTop=y; } }catch(_){}
}
function paStaffFld(sid, key, txt){
  if(!poGuard()) return;
  var st=(PIER_STAFF||[]).filter(function(x){ return x.id===sid; })[0]; if(!st) return;
  var v=String(txt==null?'':txt).trim().slice(0,80);
  // ชื่อกับชื่อเล่นห้ามว่างพร้อมกัน · ทั้งตารางเรียกคนจากสองช่องนี้ ว่างทั้งคู่แล้วเหลือแต่ id
  if((key==='name' && !v && !String(st.nick||'').trim()) ||
     (key==='nick' && !v && !String(st.name||'').trim())){
    alert('ต้องเหลือชื่อหรือชื่อเล่นไว้อย่างน้อยหนึ่งช่อง');
    paKeep(function(){ renderPierAtt(); }); return;
  }
  if(String(st[key]||'')===v) return;
  st[key]=v; poPersist();
  // รหัสตั้งต้นมีผลกับช่องวันทั้งแถวและยอดสรุป · อีกสามช่องเป็นตัวหนังสือในช่องเดิม ไม่ต้องวาดใหม่
  if(key==='defCode') paKeep(function(){ renderPierAtt(); });
  try{ if(typeof renderPierJob==='function' && key!=='defCode') renderPierJob(); }catch(_){}
}
/* §paCols · หมายเหตุรายคน · เก็บที่ทะเบียนพนักงาน ไม่ใช่รายวัน (ลาออก · กลับมาไฮซีซั่น) */
function paNote(sid, txt){
  if(!poGuard()) return;
  var st=(PIER_STAFF||[]).filter(function(x){ return x.id===sid; })[0]; if(!st) return;
  st.note=String(txt||'').slice(0,120);
  poPersist();
}
/* §paLayers · ปุ่มสองอันบนหัวหน้าต่างเลือกรหัส · จำไว้ระหว่างที่หน้าต่างเปิดอยู่ */
var _paPlan=0;
function paPlanMode(v, el){
  _paPlan=v?1:0;
  try{ var w=el.parentNode.querySelectorAll('button');
    for(var i=0;i<w.length;i++) w[i].className=(i===(v?1:0))?'on':''; }catch(_){}
}
function paSet(date,sid,code,plan){
  paSetManual(date,sid,code,plan);
  poPersist(); paPopClose(); paKeep(function(){ renderPierAtt(); });
}

/* ── ทะเบียนรหัส ── */
/* §paSect · หน้าจัดกลุ่ม · สร้าง เปลี่ยนชื่อ เรียง ลบ ย้ายคน */
function paSectId(){ return 'sc_'+Math.random().toString(36).slice(2,8); }
function paSectStaff(){ return (PIER_STAFF||[]).filter(function(s){ return s.pier===_poPier && s.active!==false; }); }
// §paTickLive · ตัวสร้างตารางติ๊ก · ใช้ทั้งตอนเปิดกล่องและตอนอัปเดตสดหลังติ๊ก
function paTickTable(S, staff, ro){
  var known={}; S.forEach(function(x){ known[x.id]=1; });
  var nUn=staff.filter(function(s){ return !known[s.sect]; }).length;
  var row=function(s){
    var cur=known[s.sect]?s.sect:'';
    var D=ro?'':(' ondragover="paDragOver(event,\''+poE(s.id)+'\')" ondragleave="paDragLeave(event)"'
              +' ondrop="paDrop(event,\''+poE(s.id)+'\')"');
    return '<tr data-sid="'+poE(s.id)+'"'+(cur?'':' class="nos"')+D+'>'
      +'<td class="who"'+(ro?'':' draggable="true" ondragstart="paDragStart(event,\''+poE(s.id)+'\')" ondragend="paDragEnd()"')+'>'
      +(ro?'':'<span class="gr" title="ลากเพื่อสลับลำดับในกลุ่ม">&#8942;&#8942;</span>')
      +(ro?'':'<span class="ord"><button onclick="event.stopPropagation();paStaffBump(\''+poE(s.id)+'\',-1)" title="ขึ้น">&#9650;</button>'
             +'<button onclick="event.stopPropagation();paStaffBump(\''+poE(s.id)+'\',1)" title="ลง">&#9660;</button></span>')
      +'<b>'+poE(s.name||s.nick||s.id)+'</b>'
      +(s.nick?('<em>'+poE(s.nick)+'</em>'):'')+'<i>'+poE(s.role||'')+'</i></td>'
      + S.map(function(x){
          return '<td class="tk'+(cur===x.id?' on':'')+'"'+(ro?'':' onclick="paStaffSect(\''+poE(s.id)+'\',\''+poE(x.id)+'\')"')+'>'
            +'<span>'+(cur===x.id?'&#10003;':'')+'</span></td>'; }).join('')
      + '<td class="tk un'+(cur?'':' on')+'"'+(ro?'':' onclick="paStaffSect(\''+poE(s.id)+'\',\'\')"')+'>'
        +'<span>'+(cur?'':'&#10003;')+'</span></td></tr>';
  };
  var band=function(t,n,cls){
    return '<tr class="bnd'+(cls?(' '+cls):'')+'"><td colspan="'+(S.length+2)+'">'+poE(t)
      +(n==null?'':'<span>'+n+' คน</span>')+'</td></tr>';
  };
  // §paSectFlow · ยังไม่จัดอยู่บนสุดเสมอ · ติ๊กแล้วแถวลงไปอยู่กลุ่มของตัวเอง
  var un=staff.filter(function(s){ return !known[s.sect]; });
  var out='';
  if(un.length) out+=band('ยังไม่จัด · ติ๊กเลือกกลุ่มให้คนเหล่านี้',un.length,'todo')+un.map(row).join('');
  else out+=band('จัดครบทุกคนแล้ว',null,'done');
  S.forEach(function(x){
    var rows=staff.filter(function(s){ return s.sect===x.id; });
    if(!rows.length) return;
    out+=band(x.name||'(ไม่มีชื่อ)',rows.length)+rows.map(row).join('');
  });
  return '<table><thead><tr>'
    +'<th class="who">ใคร<span>'+staff.length+' คน</span></th>'
    + S.map(function(x){ var c=staff.filter(function(s){ return s.sect===x.id; }).length;
        return '<th title="'+poE(x.name||'')+'">'+poE(x.name||'(ไม่มีชื่อ)')+'<span>'+c+'</span></th>'; }).join('')
    +'<th class="un">ยังไม่จัด<span>'+nUn+'</span></th></tr></thead><tbody>'+out+'</tbody></table>';
}
function _paRowBy(w, sid){
  var rs=w.getElementsByTagName('tr');
  for(var i=0;i<rs.length;i++) if(rs[i].getAttribute('data-sid')===sid) return rs[i];
  return null;
}
// §paTickLive · วาดเฉพาะตารางติ๊กใหม่ ไม่สร้างกล่องใหม่ · คืนตำแหน่งที่สายตาจับอยู่
//   หมุดต้องเป็น "แถว" ไม่ใช่ค่า scrollTop ดิบ · แถวที่ย้ายออกจากบล็อกบนทำให้ของข้างล่างเลื่อนขึ้นมาหนึ่งแถว
//   คืนแค่ตัวเลขเดิมจะเหลื่อมไปหนึ่งแถวทุกครั้งที่ติ๊ก
function paTickRefresh(movedSid){
  var w=document.getElementById('pa-tick'); if(!w) return false;
  var ro=!poCanEdit(), S=paSects(_poPier), staff=paSectStaff();
  if(!S.length || !staff.length) return false;
  var top=w.scrollTop, anchor=null, rs=w.getElementsByTagName('tr');
  for(var i=0;i<rs.length;i++){
    var sid=rs[i].getAttribute('data-sid');
    if(!sid || sid===movedSid) continue;              // แถวที่เพิ่งย้ายใช้เป็นหมุดไม่ได้ · มันไปอยู่ที่ใหม่แล้ว
    if(rs[i].offsetTop+rs[i].offsetHeight > top+1){ anchor={sid:sid, off:rs[i].offsetTop-top}; break; }
  }
  w.innerHTML=paTickTable(S, staff, ro);
  var a=anchor?_paRowBy(w, anchor.sid):null;
  w.scrollTop = a ? Math.max(0, a.offsetTop-anchor.off) : top;
  // ป้ายจำนวนคนบนหัวกล่องแต่ละกลุ่มอยู่นอกตาราง · อัปเดตแยก ไม่งั้นเลขค้างจนกว่าจะปิดเปิดใหม่
  try{ var hd=document.querySelectorAll('#po-modal .pa-sec .hd .n');
    S.forEach(function(sec,i){ if(hd[i]) hd[i].textContent=staff.filter(function(s){ return s.sect===sec.id; }).length+' คน'; });
  }catch(_){}
  var m=movedSid?_paRowBy(w, movedSid):null;          // กะพริบสั้น ๆ ตรงที่มันไปโผล่ · ไม่ต้องเลื่อนจอตาม
  if(m){ m.className=(m.className+' mv').trim(); setTimeout(function(){ try{ m.className=m.className.replace(/\s*\bmv\b/,''); }catch(_){} }, 1000); }
  return true;
}
function paSectAdd(){
  if(!poGuard()) return;
  var S=paSects(_poPier);
  PIER_SECT.push({id:paSectId(), pier:_poPier, name:'', ord:(S.length?((+S[S.length-1].ord||0)+1):1)});
  poPersist(); paSectOpen();
}
function paSectSet(id, key, val){
  if(!poGuard()) return;
  var x=(PIER_SECT||[]).filter(function(v){ return v.id===id; })[0]; if(!x) return;
  x[key]=val; poPersist();
  if(key!=='name') paSectOpen();
  try{ renderPierAtt(); }catch(_){}
}
function paSectMove(id, dir){
  if(!poGuard()) return;
  var S=paSects(_poPier), i=-1;
  S.forEach(function(x,n){ if(x.id===id) i=n; });
  var j=i+dir; if(i<0 || j<0 || j>=S.length) return;
  var a=S[i].ord, b=S[j].ord;
  if(a===b || a==null || b==null){ S.forEach(function(x,n){ x.ord=n+1; }); a=S[i].ord; b=S[j].ord; }
  S[i].ord=b; S[j].ord=a;
  poPersist(); paSectOpen(); try{ renderPierAtt(); }catch(_){}
}
function paSectDel(id){
  if(!poGuard()) return;
  var n=(PIER_STAFF||[]).filter(function(s){ return s.sect===id; }).length;
  if(n && !confirm('ลบกลุ่มนี้?\n\nคน '+n+' คนในกลุ่มจะไม่หายไปไหน · ย้ายไปอยู่ UNASSIGNED ท้ายตาราง')) return;
  PIER_SECT=(PIER_SECT||[]).filter(function(x){ return x.id!==id; });
  (PIER_STAFF||[]).forEach(function(s){ if(s.sect===id) s.sect=''; });
  poPersist(); paSectOpen(); try{ renderPierAtt(); }catch(_){}
}
function paStaffSect(sid, secId){
  if(!poGuard()) return;
  var s=(PIER_STAFF||[]).filter(function(x){ return x.id===sid; })[0]; if(!s) return;
  if(String(s.sect||'')===String(secId||'')) return;   // ติ๊กซ้ำที่เดิม · ไม่มีอะไรเปลี่ยน ไม่ต้องขยับจอ
  s.sect=secId||'';
  s.ord=1e9; paOrderNorm(_poPier);   // §paOrder · เข้ากลุ่มใหม่ = ไปต่อท้ายกลุ่มนั้น ไม่ใช่แทรกกลางตามเลขเก่า
  poPersist();
  // §paTickLive · เดิมเรียก paSectOpen() ซึ่งสร้างกล่องใหม่ทั้งใบทุกครั้ง · จอกระพริบ scroll กลับไปบนสุด
  if(!paTickRefresh(sid)) paSectOpen();
  try{ renderPierAtt(); }catch(_){}
}
function paSectOpen(){
  var ro=!poCanEdit(), S=paSects(_poPier), G=paGroups(_poPier);
  var body='<div style="font-size:12px;color:#6E7684;margin-bottom:12px;line-height:1.7">'
    +'ตั้งชื่อกลุ่มด้านบน แล้ว<b style="color:#16265C">ติ๊กในตารางข้างล่าง</b>ว่าใครอยู่กลุ่มไหน<br>'
    +'คนหนึ่งอยู่ได้กลุ่มเดียว · ติ๊กที่ใหม่แล้วที่เก่าหลุดเอง<br>'
    +'อยากสลับลำดับคนในกลุ่ม · <b style="color:#16265C">ลากชื่อขึ้นลง</b> หรือกดปุ่ม &#9650;&#9660; ท้ายชื่อ<br>'
    +'ลบกลุ่มแล้ว<b style="color:#16265C">คนไม่หาย</b> · ตกไปอยู่ UNASSIGNED ท้ายตาราง</div>';
  if(!S.length) body+='<div class="po-warn" style="margin:0 0 12px">ท่านี้ยังไม่มีกลุ่ม · กด "เพิ่มกลุ่ม" เพื่อเริ่ม</div>';
  S.forEach(function(sec,i){
    var rows=(PIER_STAFF||[]).filter(function(s){ return s.pier===_poPier && s.active!==false && s.sect===sec.id; });
    body+='<div class="pa-sec">'
      +'<div class="hd">'
        +'<input class="pl-f nm" value="'+poE(sec.name||'')+'" placeholder="ชื่อกลุ่ม เช่น OFFICE DEPARTMENT" '
          +'oninput="paSectSet(\''+sec.id+'\',\'name\',this.value)"'+(ro?' disabled':'')+'>'
        +'<span class="n">'+rows.length+' คน</span>'
        +(ro?'':'<button class="mv" onclick="paSectMove(\''+sec.id+'\',-1)"'+(i===0?' disabled':'')+' title="ขึ้น">&#9650;</button>'
             +'<button class="mv" onclick="paSectMove(\''+sec.id+'\',1)"'+(i===S.length-1?' disabled':'')+' title="ลง">&#9660;</button>'
             +'<button class="x" onclick="paSectDel(\''+sec.id+'\')" title="ลบกลุ่ม">&times;</button>')
      +'</div>'
      +'</div>';
  });
  // §paSectTick · ตารางติ๊ก · แถวละคน คอลัมน์ละกลุ่ม · เห็นทั้งกระดานในหน้าจอเดียว
  var staff=paSectStaff();
  if(S.length && staff.length) body+='<div class="pa-tick" id="pa-tick">'+paTickTable(S, staff, ro)+'</div>';
  poModal('กลุ่มในตารางการทำงาน · '+poE(poPierName()),
    '<style>'+poCSS().replace(/\.po-host/g,'#po-modal')+paSectCSS()+'</style>'+body,
    (ro?'':poBtn('+ เพิ่มกลุ่ม','paSectAdd()','pri'))+poBtn('ปิด','poModalClose()'), 760);
}
